import { DocsFormatSubpage } from "./DocsFormatSubpage.js"
import type { Said, SiteLanguage } from "../SitePage.js"

/**
 * Everything an observation's file says around what was seen: the witness and what they did, the instrument, the decor, the facts of the
 * sky, the weather. A part of the observation's technical side (see DocsFormatSubpage).
 */
export class DocsFormatContextPage extends DocsFormatSubpage {

  static readonly TITLE: Said<string> = { en: "Around what was seen", fr: "Autour de ce qui a été vu", es: "Alrededor de lo que se vio", it: "Intorno a ciò che è stato visto" }

  constructor() {
    super("docs/format/context", DocsFormatContextPage.TITLE, {
      en: "The rest of an observation's file, after what was seen: the witness's movements and what they did, the instrument, the sound, the decor and the vehicles, what happened in the sky, and the weather with its clouds.",
      fr: "La suite du fichier d'une observation, après ce qui a été vu : les déplacements du témoin et ce qu'il a fait, l'instrument, le son, le décor et les véhicules, ce qui s'est passé dans le ciel, et la météo avec ses nuages.",
      es: "El resto del archivo de una observación, después de lo que se vio: los desplazamientos del testigo y lo que hizo, el instrumento, el sonido, el decorado y los vehículos, lo que ocurrió en el cielo, y el tiempo con sus nubes.",
      it: "Il seguito del file di un'osservazione, dopo ciò che è stato visto: gli spostamenti del testimone e ciò che ha fatto, lo strumento, il suono, lo scenario e i veicoli, ciò che è accaduto nel cielo, e il meteo con le sue nuvole."
    }, {
      en: "The fields of an observation's file around what was seen: the witness's track and events, instrument, sound, decor, sky events, weather and clouds.",
      fr: "Les champs du fichier d'une observation autour de ce qui a été vu : trajet et événements du témoin, instrument, son, décor, événements du ciel, météo et nuages.",
      es: "Los campos del archivo de una observación alrededor de lo que se vio: trayecto y eventos del testigo, instrumento, sonido, decorado, eventos del cielo, tiempo y nubes.",
      it: "I campi del file di un'osservazione intorno a ciò che è stato visto: percorso ed eventi del testimone, strumento, suono, scenario, eventi del cielo, meteo e nuvole."
    })
  }

  protected body(language: SiteLanguage): string {
    const sections = { en: () => this.en(), fr: () => this.fr(), es: () => this.es(), it: () => this.it() }[language]()
    return `
<section class="band">
  <div class="wrap prose-wide">
    <p class="small">${this.excerptNote(language)}</p>
${sections}
  </div>
</section>
`
  }

  private en(): string {
    return `
    <h2 id="everything-around-it">The fields around what was seen</h2>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>observerTrack</code></td><td><code>{ keyframes: [{ t, pose }] }</code> — <code>pose</code> holds <code>lat</code>, <code>lng</code>, <code>elevationM</code> (above the local ground), <code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>, and for a camera <code>fNumber</code> and <code>focusDistanceM</code>. Played the way a person moves: exactly the stated pose at each keyframe, and between them a movement that gathers speed, carries it through the keyframes that keep moving, and slows down into a pause — two keyframes with the same place, or the same heading. A look starts and ends still; a walk or drive already under way at the first keyframe carries on. Stopping and setting off on foot add their own jolt, a nod of the head that dies within a second and a half, turned into the image as much as the instrument lets it (an eye hardly, a hand-held camera fully). And a body at rest is never quite still: standing or waiting, the view sways by millimetres and drifts by a tenth of a degree, slowly, the same way at the same instant — except for a witness the account says was paralysed (tag <code>paralysis</code>). The <code>pitchDeg</code> stated is how the witness looked in the frame of what carried them: while they travel, the player adds how the vehicle itself climbs (the grade of the road under the track, read from the relief, uphill positive, or for an aircraft its own climb, faded as the view turns off the way they go), so a climb raises the view and the <q>Tilt</q> chip states the sum. <code>filter</code> is what was held in front of the instrument, a <code>FILTERS</code> id such as <code>solar-visual</code> for an eclipse. It is held between keyframes, not blended (nobody wears half a pair of glasses), and taken off by stating <code>"none"</code>. A keyframe stating <code>viewOnly: true</code> sets the view of its instant alone (the editor writes it when the view is turned with Alt held): the camera's turn to it and from it is left out of the picture, and an exposure over it is drawn as if the camera had stood still, pointed as it is at the instant shown. A witness flying at a stated altitude gives it as <code>altitudeM</code> (metres above the sea): the player puts the eye there over whatever relief it draws, <code>elevationM</code> then being only the height over the ground the file was written against, which the decor of a cabin round the eye is stated against too.</td></tr>
      <tr><td><code>events</code></td><td>What the witness did, stated as events with their parameters instead of the poses they imply: <code>[{ type: "event", eventType, t, until, params }]</code>, <code>t</code> and <code>until</code> in ms of the recording. The player works the poses out of them when it reads the recording, by the same law for every recording (a turn of the head starts from still and settles, a vehicle's line is a curve), and writes the events alone back as long as nothing has changed those poses; an <code>observerTrack</code> with keyframes of its own wins over them. A parameter takes its provenance like any value. A table of instants (<code>speeds</code>, <code>speedDivisors</code>, <code>heights</code>, <code>metres</code>) has as many rows as the account needs; its value goes from one row to the next gradually, or at once at a row with <code>step: true</code>. On foot: <code>look</code> (a look held from <code>t</code> on, <code>headingDeg</code>, <code>pitchDeg</code>), <code>walk</code> (from <code>from</code> to <code>to</code>, two <code>{ lat, lng }</code>, between <code>t</code> and <code>until</code>, as a person walks and stops) and <code>follow</code> (a body of the reading, or a phenomenon going across the sky, <code>target</code>, which the eyes reach <code>reactionS</code> after, <code>lagS</code> behind it, with no keyframes of its own to be looked at but every <code>sampleMs</code>, looked at at each of its keyframes, in the middle of what they see, the look turning between them as a head does; held where it is lost, at <code>until</code>; <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>). In a vehicle: <code>drive</code> (the vehicle the witness is in, a decor object named by <code>vehicle</code>, follows <code>path</code>, a list of <code>{ lat, lng }</code>, at <code>speeds</code> <code>[{ t, kmh }]</code>, possibly divided by <code>speedDivisors</code> <code>[{ t, divisor }]</code>, placed by the one place it went <code>through</code> <code>{ t, lat, lng }</code>; the driver's <code>eye</code> is <code>{ x, y, z }</code> in the vehicle's model), <code>lookAhead</code> (they look down the road and keep the <code>target</code> <code>{ lat, lng }</code> within about <code>keepDeg</code>, and glance at it for <code>glanceS</code>, then at the road for <code>roadS</code>, once it is more than <code>glanceBeyondDeg</code> off; <code>pitchShare</code> is how much of its height they look up to), <code>lean</code> (towards the mirror: the eye moves by <code>offsetM</code> over <code>turnS</code>, for <code>holdS</code>) and <code>watch</code> (in the <code>mirror</code>, a point of the vehicle's model: <code>firstS</code>, then <code>mirrorS</code> between looks away, glances at the target of <code>glanceS</code> every other time until <code>glancesUntil</code>, the road for <code>roadS</code> otherwise). Every event says whom it is about in <code>who</code>, by an id of the recording, which nothing else of it has: the witness's (<code>observer.id</code>, or <code>"observer"</code> for a witness without one; an event that says none is theirs), a shape's or a group of shapes', a body's, a decor object's. The editor does not save a recording with an event about nothing, or two things of one id. An event of a decor object: <code>fly</code> (an aircraft along a straight line leading to <code>from</code> <code>{ lat, lng }</code>, on <code>headingDeg</code>, at <code>speeds</code>, <code>at.metresBefore</code> that place at <code>at.t</code>, at <code>heights</code> <code>[{ t, altitudeM }]</code> above the witness's eye). A lamp of it (<code>id/lamp</code>, <code>f-hobs/landing-nose</code>), or a group of them that the object's <code>groups</code> name (<code>f-hobs/strobes</code>): <code>light</code> (at <code>intensity</code> from the event's start, 0 off, blinking as it did, and back to what it was at its end when it states one) and <code>blink</code> (on for <code>onS</code>, off for <code>offS</code>, at <code>intensity</code> or what it was, until the event's end, then as before): a landing light put out, strobes switched on, a beacon, the lights on top of a building. The phenomenon's (<code>who</code> the shape it is drawn as, or the group of its shapes) give the account's shapes, as the witness described it: <code>stand</code> (at the <code>place</code> they stated, <code>{ lat, lng }</code>, its <code>metres</code> <code>[{ t, widthM, heightM }]</code> its width and its height above the eye, from which its direction and its size in their sky follow at every instant), <code>appearance</code> (how it looked from <code>t</code> on, its <code>parts</code>: shapes placed and sized in shares of its apparent width, <code>sourceId</code>, <code>kind</code>, <code>points</code>, <code>color</code>, <code>brightness</code>, <code>halo</code>, <code>widthShare</code>, <code>heightShare</code>, <code>alongShare</code>, <code>upShare</code>; a part another appearance has and this one has not is not seen), <code>blink</code> (the shapes it is about, a group of the phenomenon's or one of them, on for <code>onS</code>, off for <code>offS</code>, taking <code>off</code> while off) and <code>vanish</code> (no longer seen). Or, with no place, going across the sky, an account of directions only: <code>travel</code> (<code>from</code> a direction <code>{ azimuthDeg, altitudeDeg }</code> <code>towards</code> another, along the great circle between them, at <code>speeds</code> <code>[{ t, degPerS }]</code>, from still between two; <code>sizeDeg</code> wide at the zenith, smaller as the sine of its altitude when <code>sizeBy</code> is <code>"altitude"</code>; its parts laid along its way on the witness's picture, <code>alongShare</code> ahead or behind, <code>upShare</code> to its left, turned with it), <code>turn</code> (by <code>byDeg</code> to its <code>side</code>, <code>"left"</code> or <code>"right"</code>, from still and settling; the other side on the sky when <code>seenFrom</code> is <code>"craft"</code>, as a pilot says it), <code>roll</code> (banked to <code>toDeg</code>, and back level when <code>andBack</code>, narrower across its way by the cosine of it), <code>vibrate</code> (from side to side <code>hz</code> times a second, by <code>amplitudeShare</code> of its size, from nothing over <code>riseS</code>, then less and less to the event's end) and <code>spiral</code> (<code>turns</code> round a circle beside its way, <code>clockwise</code> or not, <code>radiusDeg</code> wide once open, narrower by <code>shrink</code> by its end, rolling <code>rollDeg</code> as it does); <a href="/demo-data/observer-saint-lo.json"><code>observer-saint-lo.json</code></a>. A body of the reading's (<code>who</code> its id; or, about one part of its model, a node or a bone of it, <code>id/part</code>: <code>craft/legs</code>, <code>etre-2/head</code>, which <code>spin</code> and <code>turn</code> turn alone about its own upright axis, clockwise seen from its top, the rest of the body as it is; a light of it, by its name in the model, <code>engin/front-red</code>, or a group of its parts that the body's <code>groups</code> name, <code>engin/rear</code>; the model's file says which parts it has) add to the keyframes it states: <code>motion</code> (one of its model's movements played once, <code>motion</code> to <code>to</code>, the central tube drawn in), <code>spin</code> (one kept turning, <code>turnsPerS</code>, the legs), <code>rise</code> (<code>distanceM</code> along a straight line <code>angleDeg</code> off the vertical, 0 straight up, towards <code>headingDeg</code>, from still, slowing into its stop or, <code>stops: false</code>, faster and faster as it leaves), <code>turn</code> (to face <code>headingDeg</code>), <code>ride</code> (carried by the body <code>in</code>, <code>aboveM</code> higher), <code>light</code> (a light, or a group of them, lit at <code>cdM2</code> from the event's start, 0 switched off, and lit again as it was at its end when it states one) and <code>blink</code> (one blinking, on for <code>onS</code>, off for <code>offS</code>, lit at <code>cdM2</code> while on or at what it was lit at before, until the event's end, then lit as before; at once, never a fade: an aircraft's strobes, a beacon, the light on top of a mast) and <code>vanish</code>; a posture is a movement of the model too (<code>motion</code> on <code>crouch</code>, which a figure exported with its postures carries: 0 standing, 1 crouched); <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>'s craft and beings. <a href="/demo-data/observer-silly-le-long.json"><code>observer-silly-le-long.json</code></a> states its witness, its aircraft and its phenomenon this way</td></tr>
      <tr><td><code>sampleMs</code></td><td>How often a keyframe is taken, ms: by the editor's recorder as a shape is moved by hand, and where the events are worked out into values (the account's shapes, the look that follows them, a body that rises), all at that same pace, so that what is drawn and the look it is drawn for never fall apart. Of what that gives, keyframes that say the same thing are kept as the first and the last of them: the player draws the same between them. Absent, each keeps its own: 25 ms for a phenomenon going across the sky and the look that follows it, 2 s for one that stands, 250 ms for a body that rises</td></tr>
      <tr><td><code>weatherTrack</code></td><td><code>{ keyframes: [{ t, weather }] }</code> — the sky's conditions along the recording: precipitation, wind, storm, and the clouds as layers with real heights, each able to hold individual clouds placed in metres. Every field of a <code>weather</code> is in the next section</td></tr>
      <tr><td><code>weatherSource</code></td><td><code>{ id, name, url }</code> of the record the weather was looked up from. Its presence means the recording is replayed exactly as authored and never looked up again. Absent means the witness's own account</td></tr>
      <tr><td><code>lightPollution</code></td><td>How bright the night sky of the place is, towns and all: the zenith of a moonless night in magnitudes per square arcsecond, as a Sky Quality Meter reads it or as the <a href="https://doi.org/10.1126/sciadv.1600377">World Atlas of the artificial night sky brightness</a> gives it (its “SQM” figure, Falchi et al. 2016, which <a href="https://www.lightpollutionmap.info">lightpollutionmap.info</a> shows for any place). <code>22</code> is a natural sky, a suburb about <code>19</code>, a city centre <code>17</code>. Absent means a natural sky. The towns' share, what is left once the natural 22 is taken out, is added to the sky as light: brighter toward the horizon, where the low air scatters more of it back, and drawn in the warm white of a 3000 K lamp. It drowns the Milky Way and the zodiacal light, and takes stars away, by the difference in the faintest star an eye can pick out (Crumey 2014): about two magnitudes at <code>19</code>. The Moon now does the same. <code>"derived"</code> when looked up in the atlas, <code>"stated"</code> when the witness measured it. The editor fills it in from the atlas for an observation from 2015 on, as <code>"derived"</code> with the atlas named, and never replaces a figure typed by hand; before 2015 it asks nothing, the sky having been darker than the atlas's</td></tr>
      <tr><td><code>around</code></td><td>What made a noise around the observer, which an aircraft is heard against as against the wind and the rain: <code>cars</code>, <code>trucks</code> (and buses), <code>people</code> and how many of them were <code>talking</code>, all there at once within <code>withinM</code> metres (200 if absent), and <code>roads</code>, each <code>{ distanceM, vehiclesPerMinute, trucksPerMinute, speedKmh }</code> (50 km/h if absent), as a witness can say either. What it sounds like where the observer stands is worked out from the <a href="https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:32021L1226">CNOSSOS-EU</a> sound power of vehicles (a car at 50 km/h is 73 dB(A) at 7.5 m) and from a conversation's 55 dB(A) at 1 m (Pearsons et al. 1977): counted things as spread over their disc, a road as a line. It is added to the weather's noise: a town's traffic masks aircraft a calm field lets through. None of it is played yet: a road's noise played as a bed was a hiss over the aircraft; it is heard when the scene has vehicles of its own. Each figure has its provenance, at <code>around.cars</code> or <code>around.roads.0.distanceM</code>. Absent: a quiet place</td></tr>
      <tr><td><code>observerMap</code></td><td>Whether the map of where the witness stood starts open when the recording is played or edited: <code>true</code> or <code>false</code>. Absent says nothing, and the player decides: open for a witness who went somewhere, closed for one who stayed put. A page embedding the player has the last word (its <code>show-observer-map</code> attribute). The editor writes it when the map is opened or closed there, so that a reader is shown what the author left</td></tr>
      <tr><td><code>snapshots</code></td><td>Where the data the scene would otherwise ask third parties for at every play is kept, in files beside the recording (annexes), so that a finished recording plays the same way in ten years without asking anybody: <code>relief</code> (the ground's height, as the elevation source answered for each patch of ground the scene builds, a zip), <code>imagery</code> (the photograph of the ground, as the tiles the imagery source served, a zip), <code>roads</code>, <code>water</code>, <code>railways</code> (the ways, rivers and tracks of each patch, JSON), <code>upperAir</code> (the air at the levels of the aircraft, JSON) and <code>map</code> (the photograph under the witness map, as the tiles the imagery source served for the ground the map is fitted to, a zip: a map taken as a snapshot shows that photograph and asks for no other, larger when zoomed into, blank beyond it when zoomed out). Each is <code>{ src, takenOn, attribution }</code>, <code>src</code> read relative to the recording's own address, or a <code>data:</code> URL for an annex kept inside the recording itself. A group read from its annex asks nobody for anything; a group without one is asked for live, as everything was before. <code>"live": true</code> on a group asks it live at every play and never takes a snapshot of it (what picking its live source rather than <em>File</em> says), and on <code>snapshots</code> itself every group; <code>"refresh": true</code> on one group asks it live once, and the editor takes it again at the next save. The editor takes what is missing when the recording is saved, and saves the recording and its annexes as one zip to unpack where it is published. <code>weather</code>, <code>place</code>, <code>lightPollution</code> and <code>decor</code> say the weather (<code>weatherTrack</code>, <code>weatherSource</code>), the place's name, the night sky's figure and the scenery are read from the file rather than asked again by the editor (of the weather record as the date or the place change, of the geocoder, the atlas and the survey as the witness moves): <code>{}</code> for those kept inside the recording, <code>{ src }</code> for an annex holding their keys, which the players put back in the recording as they load it. Absent, they are inside the recording and the editor asks again. The time zone is not here: it is written in the recording itself</td></tr>
      <tr><td><code>modules</code></td><td>The modules the recording needs to be drawn as it was made (a catalogue its models come from), by the address of each one's manifest, relative to the recording or absolute: see <a href="/docs/modules/">modules</a>. A reader gets what each manifest states, never its script unless they added that module themselves. Absent, it needs none</td></tr>
      <tr><td><code>soundTrack</code></td><td><code>{ keyframes: [{ t, sound }] }</code> — <code>kind</code> (none/hum/whistle/rumble/crackle), <code>volume</code>, <code>pitchHz</code>, optional <code>src</code> of a real recording. <code>volume</code> and <code>pitchHz</code> glide between keyframes, <code>kind</code> and <code>src</code> change at the keyframe. A <code>src</code> on another site must be served to any origin (CORS)</td></tr>
      <tr><td><code>references</code></td><td>Pictures of the place laid over the scene: <code>src</code> (an address, or a <code>data:</code> URL for a picture added from a disk), <code>kind</code> (photo/panorama/video), <code>registration</code> (<code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>), <code>opacity</code>, <code>credit</code>/<code>creditUrl</code>, optional <code>t</code> and <code>drawing</code>, <code>from</code> (<code>{ lat, lng }</code>, where it was taken: the player fades it out as the witness walks away from that point; absent, it is never faded), and the <code>landmarks</code> it was lined up on (<code>id</code>, <code>label</code>, <code>picture</code> as <code>{ u, v }</code> from the top-left corner, <code>scene</code> as <code>{ azimuthDeg, altitudeDeg }</code>). A <code>video</code> also states <code>t</code>, where its stretch starts on the timeline, <code>video</code> (<code>fromS</code>, <code>toS</code>, <code>rate</code>: which part of the file, how fast), and <code>registrationTrack</code>, where its camera pointed at each instant it was lined up at.</td></tr>
      <tr><td><code>traces</code></td><td>What an investigator drew over the place, imported from their Google Earth file (KML, KMZ) or their GIS's GeoJSON and drawn over the scene as theirs, never as part of the reconstruction: <code>[{ id, title, kind, points, altitude, color, source }]</code>, <code>kind</code> being <code>point</code>, <code>line</code> or <code>polygon</code>, <code>points</code> the vertices as <code>[{ lat, lng, altM }]</code> exactly as the file held them, <code>altitude</code> how <code>altM</code> is read (<code>ground</code>, the default, <code>relative</code> to the ground under each point, or <code>absolute</code> above sea level), <code>color</code> a <code>#rrggbb</code> and <code>source</code> whose it is</td></tr>
      <tr><td><code>instrument</code>, <code>exposureSeconds</code></td><td>What it was observed through, and how long the shutter was open. Absent means the naked eye. <code>instrument</code> is one of <code>eye</code>, <code>rectilinear-lens</code> (a camera of unknown make), <code>roamer-1-120</code>, <code>instamatic-126</code>, <code>slr-35mm-50</code>, <code>slr-35mm-zoom</code>, <code>phone-landscape</code>, <code>phone-portrait</code>, or a digital SLR (<code>eos-5d-iii</code>, <code>nikon-d7000</code>… the sensors of Stellarium's catalogue), binoculars (<code>binoculars-nikon-10x42-edg</code>…) or a telescope (<code>telescope-celestron-c8</code>…); <code>exposureSeconds</code> is one value for the whole recording, held to that device's own range. A device that records a picture (a camera, a phone) lays its lens ghosts over every light of it, as glass and a sensor do: a fainter, out-of-focus copy on the line through the centre of the picture, mirrored through it for a phone's main one, the red disc across the frame from a traffic light. A phone exposes itself from what it sees, up to ISO 3200: a night it films stays dark round its lamps</td></tr>
      <tr><td><code>lens</code></td><td>What the picture was taken through besides the lens, and what was on that glass, for a device that records one: <code>glass</code> (<code>filter</code>, <code>window</code> or <code>windscreen</code>: a filter adds a ghost mirrored through the centre, a pane a fainter twin of every light just aside of it, further off for a windscreen leaning back), <code>drops</code>, <code>condensation</code> and <code>dirt</code> (0 to 1, each scattering a halo round every light, which loses what the halo takes) and <code>sheltered</code>. When <code>drops</code> is absent, they follow the rain or snow falling at each instant, unless <code>sheltered</code> is true: new ones land as often as the rain meets the glass squarely (a lens looking up, a pane facing the wind, a windscreen leaning back catch more), merge with their neighbours; the small ones cling for minutes, the large ones run down after a few seconds, leaving a trail of beads and wiping what they cross, and go on doing so once the rain has stopped. The ghosts of the lens itself follow its aperture: wider for a lens opened up, and the polygon of its blades once stopped down. <code>ghosts</code> states the ghosts of an optic set before the lens, which no catalogue holds (a periscope's mirror and prisms), each as a lens's are: <code>scale</code>, <code>share</code>, <code>blur</code>, <code>offset</code>, <code>tint</code>; <code>reachDeg</code> how far beyond the frame's corner a light still strikes its front glass (30° for a lens); <code>placedDrops</code> drops stated one by one instead of those <code>drops</code> scatters at random, each a <code>radius</code> (share of the picture's height) and a <code>track</code> of <code>{t, x, y}</code> (ms, shares of the picture's width and height from its top left), held at its ends; <code>drops</code> then only says how much light they scatter</td></tr>
      <tr><td><code>lighting</code></td><td>What the picture shows of the light it was taken in, when that says where the Sun was (a side lit, a side in shade): <code>sunFromViewDeg</code>, the arc of the Sun's bearing clockwise from the way the instrument looked at the start (<code>{ fromDeg: 105, toDeg: 285 }</code>: behind it, on either side), and <code>sunAltitudeDeg</code> (<code>{ minDeg, maxDeg }</code>), its least and greatest height. It binds a reading of the observation: the date, the hour, the place and the heading it states may move within what is known of each, but the Sun they put together has to light the scene as the picture shows it, so moving the place moves the hours it allows, and the other way round</td></tr>
      <tr><td><code>iso</code></td><td>The speed of the film or sensor the picture was taken on, when it is known: <code>400</code> for a 400 ISO film. Absent means the device's own (an SLR's colour negative is 100, an Instamatic's 64). A camera's picture is not answered like an eye's: a film does not adapt to the sky, it receives an exposure — the light, times the shutter, over the square of the f-number — and answers it with its own curve (a negative's soft one, a slide's steeper one, a sensor's straight line that stops at white). So a night pose comes out with a black sky and whatever was bright on it standing out. Stated for a device that sets its own exposure (a phone), it is that device set by hand, as in its manual mode</td></tr>
      <tr><td><code>film</code></td><td>The film the picture was taken on, when it is known, as an id of the catalogue: <code>"kodachrome-64"</code>. It gives the speed, unless <code>iso</code> says otherwise, and how the picture answers light, black and white included. Absent means nobody says.</td></tr>
      <tr><td><code>metering</code></td><td>How a device that sets its own exposure read the light, when it is known: <code>"average"</code>, the mean of its whole frame, as camcorders and older phones did, which burns a bright light in a dark frame out to white; or <code>"highlights"</code>, as recent phones do, held back so that a light taking up a fair part of the frame keeps its colour (a lantern twenty metres off comes out orange, white only by its flame), the rest of the night then darker. Absent means the device's own (a phone keeps its highlights)</td></tr>
      <tr><td><code>sway</code></td><td>How much the body holding the instrument moves the view when not walking: <code>1</code> for a person standing or sitting, <code>0</code> for a camera on a tripod, anything between or above for less or more. Absent means <code>1</code> — except for a witness the account says was paralysed (tag <code>paralysis</code>), for whom it is <code>0</code>, and for an exposure longer than half a second, which no hand holds still: that is a tripod, and <code>0</code> too</td></tr>
      <tr><td><code>vehicle</code></td><td>The vehicle the witness was in, when the decor does not draw it: <code>{ kind, windowsOpen, noise }</code>, <code>kind</code> being a road vehicle (<code>car</code>, <code>van</code>, <code>truck</code>, <code>motorcycle</code>, <code>generic</code>) or an aircraft, by its class as the sky's own aircraft are named (<code>business-jet</code>, <code>airliner-narrow</code>, <code>helicopter-light</code>…): one field for both, the two vocabularies having no word in common. Heard from inside: its engine follows the witness's own journey — the gear from the speed, the revs from the gear, the effort from speeding up or slowing down — with the road and the wind, muffled by a closed cabin, let in by open windows. An aircraft has neither gears nor cylinders: what is heard of it is the steady roar of its cabin, at what a passenger measures in that class of machine. <code>noise</code> is its loudness against an ordinary one of its kind (1 by default). Whatever the witness rides also stands between them and everything outside it, and takes more from the highs than from the lows: an aircraft a hundred metres off is a rumble through a fuselage, and under the cabin's own roar it is not heard at all; the rain and the wind come in muffled the same way. <code>windowsOpen</code> lets almost all of it back in. It is also what keeps the player's sound button active when the file has no <code>soundTrack</code>: the button answers for everything the scene plays — this engine, an <code>engine</code> in the decor, an aircraft of the decor in flight, a body of a reading that is heard, rain and wind — not only for the track. Its lights: <code>headlights</code> is a setting as for a decor vehicle (<code>off</code>, <code>position</code>, <code>dipped</code>, <code>main</code>, <code>fog</code>) or <code>auto</code>, the default: the dipped beam from the dusk on and nothing by day, which is what a driver does. <code>headlightKeyframes</code> is <code>[{ t, mode }]</code> for a change during the recording. The beam lights the road ahead of the witness, in the direction the vehicle goes.</td></tr>
      <tr><td><code>decor</code></td><td>Scenery at a real <code>eastM</code>/<code>northM</code> from the witness: buildings (with <code>floors</code>, <code>windows</code>), trees, shrubs, streetlights, vehicles, bridges, overhead lines, other witnesses, aircraft — optionally with a <code>track</code> and <code>lights</code> whose <code>pattern</code> carries a real flash rate. See below</td></tr>
    </table>
    </div>
    <p>A <strong>decor object</strong> is stated in metres, like everything that is not the phenomenon:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>eastM</code>, <code>northM</code>, <code>headingDeg</code></td><td>Where it stands from the witness, and which way its front faces, clockwise from true north</td></tr>
      <tr><td><code>sizeM</code></td><td><code>{ widthM, lengthM, heightM }</code> along its own axes, length being the way it faces. Each axis is optional: one nobody measured keeps the built-in shape's own proportion</td></tr>
      <tr><td><code>model</code></td><td>A real 3D model standing in for the built-in shape: a catalogue entry by <code>id</code>, or a glTF/GLB file at <code>url</code> (which wins, must be readable from any origin, and then needs its <code>credit</code>; a relative one is read from the file that states it). It never decides the size: it is scaled, keeping its proportions, to the first measured axis among length, height and width, or to the real size the catalogue gives it. Seen from inside, and whenever the model cannot be had, the built-in shape is drawn instead. An <code>observer</code> or an <code>entity</code> that names none is never drawn as a built-in shape: it is one of the catalogue's realistic people, picked by its <code>id</code> (a child, or a being a statement describes, names its own model). <code>headingOffsetDeg</code> turns the loaded model about its vertical axis so that its nose points the way the scene expects (0 faces north at a heading of 0); a catalogue entry brings its own. <code>credit</code> is <code>{ title, author, license, sourceUrl }</code>: <code>license</code> as its author states it (<code>"CC BY 4.0"</code>) and <code>sourceUrl</code> where it came from, so that the claim can be checked.</td></tr>
      <tr><td><code>bridge</code></td><td>For a <code>"bridge"</code>: how it is built. <code>sizeM.lengthM</code> is its whole length along the road, embankments included, <code>widthM</code> the deck's width and <code>heightM</code> the height of the road on the deck above the ground; <code>spanM</code> is the open span under the deck, the road running on a bank of earth sloping down to the ground on each side of it; <code>deckThicknessM</code> the slab's thickness (1.2 by default); <code>railing</code> <code>{ heightM, postSpacingM, rails }</code> the railing along both edges, posts and rails whose openings are rectangles (1.05 m, 1.5 m and 2 rails by default). Drawn at those measurements, never stretched</td></tr>
      <tr><td><code>wire</code></td><td>For a <code>"wire"</code> (an electric or telephone line): <code>sizeM.lengthM</code> is the span between its poles, along its <code>headingDeg</code>, and <code>heightM</code> the height of the lowest strand; <code>strands</code> <code>[{ heightM, acrossM }]</code> hangs several (stacked ones share an <code>acrossM</code>, a crossarm's differ); <code>poles</code> is <code>both</code> (default), <code>start</code> or <code>end</code> (the end its heading points away from or towards: the other is anchored on a building) or <code>none</code>; <code>diameterM</code> (8 mm by default) and <code>poleHeightM</code> (half a metre over the highest strand). Straight, without sag, and drawn at those measurements, never stretched</td></tr>
      <tr><td><code>track</code></td><td><code>[{ t, eastM, northM, altitudeM, headingDeg }]</code> when it moves, <code>altitudeM</code> above the ground under it (the eye is at <code>elevationM</code> + 1.6 m, so a body at the eye's level has an <code>altitudeM</code> of that). Position blends between keyframes; the heading is held from one to the next</td></tr>
      <tr><td><code>lights</code></td><td>Its lamps: <code>id</code>, <code>offsetM</code> <code>{ x, y, z }</code> from its centre (right, up, front), <code>color</code>, <code>intensity</code> (1 is an ordinary navigation light) and a <code>pattern</code>: <code>{ "kind": "steady" }</code>, or <code>{ "kind": "flash", perMinute, dutyCycle, phase }</code>, the rate as regulations state it, the lit fraction of each cycle (about 0.5 for a filament flasher, 0.01 for a strobe) and an offset from 0 to 1 between lamps. The editor fills them from presets: airliner, helicopter, car headlights, car hazard flashers, emergency beacons, streetlamp. How it is switched during the recording, from each instant on, <code>keyframes</code> <code>[{ t, intensity, pattern }]</code>: what the events <code>light</code> and <code>blink</code> about it give</td></tr>
      <tr><td><code>groups</code></td><td>Its lamps taken together, so that one event is about them all: <code>{ id, title, members }</code>, its members lamps of it or other groups of its. Named in an event as a lamp is, <code>id/group</code>: an aircraft's two strobes, <code>f-hobs/strobes</code>. Optional</td></tr>
      <tr><td><code>engine</code></td><td>A vehicle heard running: <code>{ kind, noise }</code>, as <code>vehicle</code> above. Its engine follows its own <code>track</code>, heard from where the witness stands, fainter and duller with distance</td></tr>
      <tr><td><code>aircraftSound</code></td><td>An aircraft (kind <code>aircraft</code>) heard while it flies, which it does when its <code>track</code> leaves the ground: the sort of noise it makes, an aircraft kind (<code>airliner-narrow</code> by default, <code>airliner-wide</code>, <code>airliner-supersonic</code>, <code>regional-jet</code>, <code>helicopter-light</code>, <code>light-piston</code>…) or <code>silent</code> for one that makes none. What its model says applies when this is absent (the stand-ins for a phenomenon are silent). It is heard like the aircraft of a record of air traffic: fainter and duller with distance, <em>late</em> by the time sound takes to come (about three seconds per kilometre) so that it is heard where it was, higher in pitch as it comes and lower as it leaves, and masked by the noise of the place; a jet louder taking off than coming in, and louder behind than ahead, with the echo of the ground under it. An aircraft the observer stands within (a pilot in their cockpit) is the one they ride: not heard passing, but as its cabin, and what is outside through its shell, as with <code>vehicle</code></td></tr>
      <tr><td><code>occludesSourceIds</code></td><td>The phenomena the witness said it stood in front of: see the <a href="/docs/format/#four-rules-that-decide-what-a-file-means">rules on the format page</a></td></tr>
      <tr><td><code>facade</code></td><td>Kind <code>building</code> only: <code>{ color?, plain? }</code>. <code>color</code> is the wall, <code>"#rrggbb"</code>; unless <code>plain</code> is <code>true</code>, windows are drawn on every floor and a door on the ground floor of the front face. Drawn at the stated <code>sizeM</code> (all three sides must be stated), never stretched, and not for a building with a witness inside. The editor takes the colour from the material the map states for the walls (stone, brick, concrete, breeze block, wood), or a plaster where it states none. Absent is the plain box.</td></tr>
      <tr><td><code>roof</code></td><td>Kind <code>building</code> only: <code>{ shape, riseM, color?, ridge? }</code>. <code>shape</code> is <code>"flat"</code> (the box), <code>"gable"</code> (two slopes to a ridge along the longer side, or along the depth with <code>ridge: "depth"</code>) or <code>"hip"</code> (four slopes); <code>riseM</code> is how far the ridge stands above the eaves, so the walls are <code>sizeM.heightM</code> less that; <code>color</code> is the roof seen from above, <code>"#rrggbb"</code>. The editor reads them off the laser and the aerial photograph of the survey. Absent is a flat roof the colour of the walls.</td></tr>
      <tr><td><code>origin</code></td><td>The survey this object was taken from, by the id of its provider (<code>"ign-lidar-topo"</code>), when the editor took it from the survey of the place and the author did not place it by hand: a tree, a building, a bridge or a span of line. Choosing another survey, or none, or another place replaces or removes what carries an <code>origin</code>, and never what does not</td></tr>
      <tr><td><code>surveyedOn</code></td><td>The day (<code>YYYY-MM-DD</code>) of the newest survey this object was drawn from, where it comes from one (see <code>origin</code>): the editor warns when it is later than the observation.</td></tr>
      <tr><td><code>lit</code>, <code>litKeyframes</code></td><td>Whether a streetlight's lamp or a vehicle's headlights are on. <code>litKeyframes</code> is <code>[{ t, lit }]</code>, sorted by <code>t</code>, for one that is switched on or off during the recording; without it <code>lit</code> holds throughout. Ignored for a building, a tree or a witness</td></tr>
      <tr><td><code>headlights</code>, <code>headlightKeyframes</code></td><td>How a vehicle's lights are set, since not everybody puts them on, nor as they should: <code>off</code>, <code>position</code> (the position lights, which show the vehicle and light nothing), <code>dipped</code> (the dipped beam), <code>main</code> (the main beam: far, narrow, dazzling) or <code>fog</code> (the fog lamps: low and wide). A beam lights the road, the verges, the trees and the walls in front of the vehicle, whatever the vehicle is drawn as. <code>headlightKeyframes</code> is <code>[{ t, mode }]</code>, sorted by <code>t</code>, for a setting that changes during the recording. Without either, <code>lit</code> says it: lit is the dipped beam. Ignored for anything but a vehicle. Only four vehicles (the witness's own, then the nearest of the decor) have a real beam. The witness's own lamps cast shadows (a bank, a post or a bridge pier keeps the light from what is behind it), and the beam shows in the air in proportion to what the air scatters of it: a faint trace in clear air, a cone of light in fog</td></tr>
      <tr><td><code>observerSide</code>, <code>observerFacing</code>, <code>observerKeyframes</code>, <code>occupiedFloor</code></td><td>The witness inside the object, for a <code>building</code> or a vehicle (at most one object holds them). <code>observerSide</code> is where they are: <code>front</code>, <code>behind</code>, <code>left</code>, <code>right</code>, <code>front-left</code>, <code>front-right</code>, <code>behind-left</code> or <code>behind-right</code>, a vehicle's occupant being at one of its four doors. <code>observerFacing</code> is the window they look through when it is not their seat's: a driver sits at <code>front-left</code> and looks through the windshield, <code>front</code>. <code>observerKeyframes</code>, <code>[{ t, side, facing }]</code>, says where they sit over time, each held until the next, and a keyframe without <code>side</code> means outside from then on, as a driver who gets out. <code>occupiedFloor</code> is the floor of a building they are on, 0 (ground floor) up to <code>floors</code></td></tr>
      <tr><td><code>modelParameters</code></td><td>The settings of the model the object is drawn as, by the key the catalogue entry publishes each under: <code>{ "costumeColor": "#5a6b3a" }</code> for the clothes of a person, <code>foliageColor</code> for a tree, <code>hullColor</code> for a craft, <code>gearUp</code> for an airliner in flight. A model brings its own (the editor draws a field for each of them); an object drawn as a built-in shape has none, it is painted by <code>color</code></td></tr>
      <tr><td><code>sightingUrl</code></td><td>For an <code>observer</code>: the address of that witness's own recording, when it is known, so that the scene's menu can offer to view their account</td></tr>
    </table>
    </div>

    <h2>Events of the sky</h2>
    <p>What happened in the sky while the recording runs, as facts: a laser shot, a rocket launch, a re-entry. Each was there whether anybody saw it or not, so it is neither part of the reading of the account nor decor, which outlasts the observation (a house, a tree). They are stated under <code>skyEvents</code>, at the top of the recording; a recording that put them in its <code>interpretation</code>, as earlier versions did, is still read. Beside them the scene puts what the sources know of that date and place: the meteors of the showers and the sporadic background, the fireballs a camera network recorded, the re-entries on record, the satellites tracked, the aircraft a record of air traffic gives. What the recording states is added to them, never put in their place. <code>skySources: false</code>, at the top of the recording, leaves them out: a sky entered by hand, holding only what the recording states (its events, and the aircraft of its decor).</p>
    <pre data-json=""><code>{
  "skyEvents": {
    "beams": [{
      "id": "meudon-paris",
      "path": [
        { "lat": 48.805055, "lng": 2.231171, "altitudeM": 172.5 },
        { "lat": 48.83632, "lng": 2.33702, "altitudeM": 88 }
      ],
      "wavelengthNm": 532,
      "powerW": 10
    }]
  }
}</code></pre>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>auroras</code></td><td>The aurorae over the night: an oval of light the upper air gives off round the magnetic pole, 90 to 900 km up, which the scene walks along every line of sight. <code>kp</code> says how disturbed the field was (0 to 9, or past 9 the GFZ's open-ended Hp), and <code>activity</code> how it ran, <code>{ t, kp }</code> at instants of the recording joined linearly; 3 when neither is stated. From it follow the oval's equatorward edge at magnetic midnight (66.5° of the real field's apex latitude at 0, some two degrees nearer the equator a step), its width, a diffuse green glow, its arcs and their brightness, and a storm's high red; <code>edgeLatDeg</code>, <code>arcs</code> (0 for the glow only), <code>arcKR</code> (kilorayleighs of green looking up through an arc: 1 as bright as the Milky Way, 1000 lighting the ground as a full Moon) and <code>redKR</code> state any of them otherwise. <code>fromT</code> and <code>untilT</code> say when it is there, fading in and out over a minute. It needs the recording's date, for where the Sun is decides where the oval stands. A recording that states none is shown the one the GFZ's archived index implies (Kp since 1932, Hp60 since 1985), credited, unless <code>skySources</code> is false.</td></tr>
      <tr><td><code>reentries</code></td><td>The atmospheric re-entries that happened, a satellite or rocket stage breaking up into burning pieces. Not bodies: a re-entry burns 70 to 100 km up and is seen from hundreds of kilometres, so it is placed on the Earth and seen through its curvature from wherever the witness stood. Its <code>track</code> gives the leading point at instants of the recording, <code>{ t, lat, lng, altitudeKm }</code>, joined by great circles; each of its <code>fragments</code> follows the same path <code>lagS</code> seconds behind, is seen from <code>fromT</code> until it burns out at <code>untilT</code>, shines with its <code>absoluteMagnitude</code> (at 100 km, as for a fireball) moved to its real distance, in its <code>color</code>, with a tail of the last <code>trainS</code> seconds of its path (4 when absent: a re-entry's tail is long). Each piece comes apart as burning pieces do (<code>sheds</code>): a slow crumbling into faint fragments, each with its own streak, dropping back, drifting and sinking into a narrow fan, and a burst of some thirty at each flare of its <code>lightCurve</code>, a flare being a fragmentation (Zander &amp; Löhle, <em>CEAS Space Journal</em> 2025). A list of phases states it instead, <code>{ fromT, untilT, perS, lifeS, magnitudeDrop, dropBack, spreadKmS, sinkKmS, trainS }</code>, and an empty list a piece that sheds nothing. A flare brighter than magnitude −12 below 50 km is heard as a detonation, after the time sound takes to cover the distance (Chelyabinsk: two and a half minutes). Its light is its own: it shows whether or not the Sun reaches it. <code>type</code> says what came in, and with it its nature: <code>meteor</code> or <code>fireball</code>, natural, <code>satellite</code>, <code>rocket-stage</code> or <code>capsule</code>, put in orbit, or a type a module adds (the extension point <code>reentryTypes</code>); not known when absent, which is often what an account leaves in question. It changes nothing of what is drawn, which follows from the path and the pieces. <code>seen</code> says where the witness saw it, <code>{ fromAzimuthDeg, fromAltitudeDeg, toAzimuthDeg, toAltitudeDeg, durationS }</code>: the editor works its path out from it, at the heights of the path's first and last points, and keeps it as what was said. <code>object</code> names what came down (<code>name</code>, <code>cosparId</code>, <code>norad</code>). Nothing is propagated from orbital elements, which are off by minutes in the last orbit: the path is what the sources establish, with its provenance</td></tr>
      <tr><td><code>launches</code></td><td>The rocket launches that happened, lit by a Sun that has set for the ground but not for the plume, the "space jellyfish". Placed on the Earth like a re-entry: its <code>track</code> gives the stage at instants of the recording, <code>{ t, lat, lng, altitudeKm }</code> (it may begin before the recording does), and <code>burnFromT</code> and <code>burnUntilT</code> the seconds the engine burned. The plume is a string of puffs let go along that path, each spreading with age; what shows of each is the sunlight it scatters towards the witness. The Earth's shadow (where the Sun is lit or not at the puff's height, and how much air its light grazed, which reddens or blues it), the scattering angle and the spreading are computed from the real Sun at the real date, so nothing is stated of them. An optional <code>plume</code> overrides the defaults: <code>exhaustKgPerS</code> (273, a Merlin Vacuum), <code>condensedShare</code> (0.065, the one number nobody has measured), <code>particleRadiusUm</code>, <code>expansionKmPerS</code>, <code>initialRadiusKm</code>, <code>lifetimeS</code>, and for the collar (exhaust just let go, wide and soon gone, beside the narrow trail that stays) <code>collarShare</code> (0.85), <code>collarExpansionKmPerS</code> (2.5), <code>collarLifetimeS</code> (20). <code>vehicle</code> names what flew and, in <code>engine</code>, the engine whose exhaust it is: <code>thrustKN</code> and <code>specificImpulseS</code> (from which the exhaust per second and its velocity follow, hence how wide the collar spreads) and <code>propellant</code> (<code>rp1-lox</code>, <code>methane-lox</code>, <code>hydrogen-lox</code>, <code>hypergolic</code> or <code>solid</code>, which says how much of it turns into particles and how big). What <code>plume</code> states beats what the engine implies. The plume needs the recording's date: without one there is no Sun to light it. <code>vehicle.mission</code> names the mission it flew (<code>"Starlink Group 10-49"</code>). Each puff flies on its own once let go, at the stage's velocity plus the one it was thrown at, pulled by the Earth and stopped by the air only where the air is thick enough to flow round it (below 200 to 300 km), so the plume is the same thing in space from every side: a trail seen end on is a disc, a spiral seen edge on a line. Its colour is the size of its particles': coarse ice scatters white, ice finer than the wavelength blue. <code>jets</code> lists what else the stage lets go, each <code>{ kind, fromT, untilT, angleDeg, azimuthDeg, spinPeriodS, speedKmPerS, massKgPerS, condensedShare, particleRadiusUm, expansionKmPerS, initialRadiusKm, lifetimeS }</code>: <code>kind</code> <code>burn</code> (another burn of the engine, its values those of the plume, a deorbit burn being <code>angleDeg</code> 180, the exhaust leaving ahead of the stage) or <code>vent</code> (propellant let out of the tanks, slower, finer and colder: 0.7 km/s, 20 kg/s, half of it freezing, by default); <code>angleDeg</code> from straight back along the motion (0) through sideways (90); <code>azimuthDeg</code> the side it leaves on round the motion (0 away from the Earth); <code>spinPeriodS</code> the stage's turn round its motion, which turns the jet with it and makes vented propellant draw a spiral. When there are jets, the ascent's burn is drawn only if <code>burnFromT</code> or <code>burnUntilT</code> is stated.</td></tr>
      <tr><td><code>beams</code></td><td>Beams of light sent through the air from the ground, a laser shot or a searchlight. Each has a <code>path</code> of at least two points <code>{ lat, lng, altitudeM }</code> (altitudes above the sea): where it leaves the emitter, where a mirror turns it if one does, and where it ends. Between two points it is a straight line through space, not along the ground, which falls away under it. <code>wavelengthNm</code> is its colour (532 for a green laser), <code>powerW</code> its mean optical power, <code>divergenceMrad</code> how fast it widens (0.1 when absent) and <code>apertureM</code> how wide it leaves (0.01 m when absent); <code>fromT</code> and <code>untilT</code> say when it is on. Nothing of its brightness is stated: what is seen of each metre of it is what the air there (molecules and haze, at its wavelength) scatters of the power left in it towards the eye, at the angle it has to turn, so it is far brighter looking up it than looking along it. It is hidden by what stands in front of it and stops where it meets the ground.</td></tr>
    </table>
    </div>

    <h2>The weather, and its clouds</h2>
    <p>A <code>weather</code> keyframe states the sky's conditions at one moment of the recording's
      clock; between two keyframes every number is blended, and precipitation type and storm are
      held. It carries:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>cloudLayers</code></td><td>The clouds, as a list of layers — see below. <strong>Absent</strong> means the older fields on this row's neighbours describe them, and they are adapted into one water layer and one cirrus veil; <strong>an empty list</strong> means a clear sky somebody looked at</td></tr>
      <tr><td><code>cloudCover</code>, <code>lowerCloudCover</code>, <code>highCloudCover</code></td><td>Fractions of sky (0–1): the total, the water decks alone, and the icy veil alone. Written by recordings made before there were layers, and still kept in step by the editor as a summary of them</td></tr>
      <tr><td><code>cloudBaseM</code>, <code>cloudDarkness</code></td><td>The same era's one base, in metres above the reference ground, and one shade (0 white, 1 very dark)</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>0–1, how steadily the ice crystals fell — what turns a bare ring into sundogs, arcs and a pillar. No record measures it; a cirrus layer carries its own</td></tr>
      <tr><td><code>rareIceCrystals</code></td><td>0–1, the share of a cirrus deck's crystals that are the rare kinds: pyramid-ended columns (the odd-radius haloes at 9°, 20° and 35°) and plates free to turn about a level axis (Lowitz's arcs). Absent means 5%, an ordinary deck. Like the alignment, no record counts them, so it is stated. The simulation behind it was checked against <a href="https://atoptics.co.uk">Atmospheric Optics</a></td></tr>
      <tr><td><code>relativeHumidity</code></td><td>0–1, near the ground. It decides how milky the clear sky is: haze swells with water as the air nears saturation. A looked-up record carries it (from ERA5's temperature and dew point); absent means a typical haze</td></tr>
      <tr><td><code>visibilityKm</code></td><td>The meteorological visibility near the ground, in kilometres, as a weather report states it. It is the haze itself: stated, it decides how much there is, for the distance as for the sky, and the humidity is no longer read for it Past 30 km, it is also how far the relief is drawn (up to 150 km), curving away under the line of sight: a mountain that clear air shows far off is there.</td></tr>
      <tr><td><code>precipitationType</code>, <code>precipitationIntensity</code></td><td>none/rain/snow/hail, and 0–1. Stated at a keyframe, played the way it falls: a shower begins at the keyframe that starts it with its first drops, and reaches the stated rate no faster than real rain does (nothing to heaviest in twenty seconds); it stops the same way. A change the keyframes spread over longer is followed exactly. <code>precipitationAmount</code> (0–1, absent meaning all of it) says how much of that precipitation is falling yet.</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>The general wind: the bearing it blows TOWARD, clockwise from north, and metres per second. It is what carries the clouds — from time zero, so seeking and replaying give the same sky</td></tr>
      <tr><td><code>storm</code></td><td>Lightning and thunder, at the right delay</td></tr>
    </table>
    </div>
    <p>Each <strong>layer</strong> of <code>cloudLayers</code> is a deck of clouds at a real
      height, and stays itself from one keyframe to the next:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>id</code></td><td>Stable across keyframes — layers are matched by it, never by position in the list. A layer present in one keyframe and absent from the next fades out; reordering them changes nothing</td></tr>
      <tr><td><code>type</code></td><td><code>cumulus</code>, <code>stratus</code>, <code>stratocumulus</code>, <code>cirrus</code> or <code>unknown</code>. It decides the shape of the tops and how thin the veil is; a cirrus is also the one that refracts haloes. It switches at the keyframe, it is not blended</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Metres. The base is above the recording's REFERENCE ground, not above a witness who climbs; a witness above the base is inside or over the deck, and the sky is drawn accordingly</td></tr>
      <tr><td><code>coverage</code></td><td>0–1, and it means what it says: the fraction of the sky this layer covers, whatever the size of its clouds</td></tr>
      <tr><td><code>sizeM</code></td><td>The characteristic width of one cloud, in metres. Separate from coverage: the same fraction of sky can be many small clouds or a few large ones</td></tr>
      <tr><td><code>density</code></td><td>0–2, how opaque the cloud matter is; 0 is transparent. Separate from coverage too</td></tr>
      <tr><td><code>darkness</code></td><td>0 white to 1 very dark. Absent means the keyframe's <code>cloudDarkness</code></td></tr>
      <tr><td><code>seed</code></td><td>Which pattern, out of the endless ones the same numbers can draw. Absent means one derived from the id, which is why the id must not change</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>This layer's own wind, when it differs from the general one — the high deck usually does. Absent means the general wind</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>For a cirrus only</td></tr>
      <tr><td><code>instances</code></td><td>Individual clouds inside this layer — see below</td></tr>
    </table>
    </div>
    <p>An <strong>individual cloud</strong> in <code>instances</code> is one cloud of its layer that the
      file places exactly, because the account did: the one the phenomenon went behind, the one that
      was there and nowhere else. It is drawn as one of its layer's own — the same texture, the same
      threshold — told apart from its neighbours by nothing but where it stands and how big it is,
      and it stands even when the layer's <code>coverage</code> is nought. It rides the layer's wind
      like the rest, and it hides a phenomenon it passes in front of.</p>
    <div class="table-scroll">
    <table>
      <tr><th>Field</th><th>Meaning</th></tr>
      <tr><td><code>id</code></td><td>Stable across keyframes, same rule as a layer's</td></tr>
      <tr><td><code>eastM</code>, <code>northM</code></td><td>Where its centre was at time zero, in metres from the witness's starting point. The wind carries it from there</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Its own base and height, metres — a cloud can sit lower or stand taller than its deck</td></tr>
      <tr><td><code>widthM</code>, <code>depthM</code>, <code>rotationDeg</code></td><td>Its footprint, metres, and the bearing that footprint is turned to</td></tr>
      <tr><td><code>density</code>, <code>darkness</code></td><td>Its own; darkness absent means the layer's</td></tr>
    </table>
    </div>
    <pre data-json="weatherTrack.keyframes"><code>{
  "weather": {
    "cloudLayers": [
      {
        "id": "low", "type": "cumulus",
        "baseM": 1500, "thicknessM": 800,
        "coverage": 0.55, "sizeM": 1400, "density": 1, "darkness": 0.15,
        "instances": [
          { "id": "the-one", "eastM": 0, "northM": 4200,
            "baseM": 1500, "thicknessM": 800,
            "widthM": 1900, "depthM": 1300, "rotationDeg": 12, "density": 1 }
        ]
      },
      { "id": "high", "type": "cirrus", "baseM": 8000, "thicknessM": 400,
        "coverage": 0.2, "sizeM": 2200, "density": 0.35, "iceCrystalAlignment": 0.65 }
    ],
    "precipitationType": "none", "precipitationIntensity": 0,
    "windDirectionDeg": 90, "windSpeed": 5, "storm": false
  }
}</code></pre>
    <p>A recording whose weather was <strong>looked up</strong> (it has a <code>weatherSource</code>)
      holds the record's answer, not a link to it: ERA5 gives the low, middle and high bands as three
      layers named <code>record-low</code>, <code>record-mid</code> and <code>record-high</code>, the
      low base estimated from the spread between temperature and dew point, the other two at 3 500 m
      and 8 000 m. Their type is <code>unknown</code> (cirrus for the high one), their size and
      density are drawing assumptions: a reanalysis knows how much of each band was covered, not what
      the clouds looked like. Ask the record again from the editor and the layers are rewritten; edit
      a layer by hand and the recording becomes the author's, the source dropped.</p>
`
  }

  private fr(): string {
    return `
    <h2 id="everything-around-it">Les champs autour de ce qui a été vu</h2>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Sens</th></tr>
      <tr><td><code>observerTrack</code></td><td><code>{ keyframes: [{ t, pose }] }</code> — <code>pose</code> porte <code>lat</code>, <code>lng</code>, <code>elevationM</code> (au-dessus du sol local), <code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>, et pour un appareil <code>fNumber</code> et <code>focusDistanceM</code>. Le lecteur le joue comme bouge une personne. À chaque image clé, la pose est exactement celle indiquée. Entre deux images clés, le mouvement prend de la vitesse, la garde tant que les images clés suivantes continuent de bouger, et ralentit avant une pause (deux images clés au même endroit, ou au même cap). Un regard part de l'immobilité et s'y arrête ; une marche ou un trajet déjà en cours à la première image clé se poursuit. S'arrêter ou repartir à pied ajoute une secousse : un hochement de tête qui s'amortit en une seconde et demie. Elle passe dans l'image autant que l'instrument la laisse passer (à peine pour un œil, entièrement pour un appareil tenu à la main). Enfin, un corps au repos n'est jamais tout à fait immobile : debout ou en attente, la vue oscille de quelques millimètres et dérive d'un dixième de degré, lentement, toujours de la même façon au même instant. Seul fait exception un témoin que le compte rendu dit paralysé (étiquette <code>paralysis</code>). Le <code>pitchDeg</code> indiqué est l'inclinaison du regard du témoin par rapport à ce qui le portait. Tant qu'il se déplace, le lecteur y ajoute la montée du véhicule lui-même (la pente de la route sous le trajet, lue sur le relief, positive en montée, ou pour un avion sa propre montée, atténuée quand le regard s'écarte de la direction suivie) : une côte relève donc la vue, et la pastille <q>Inclinaison</q> affiche la somme. <code>filter</code> est ce qui était tenu devant l'instrument, un id de <code>FILTERS</code> comme <code>solar-visual</code> pour une éclipse. Il reste le même d'une image clé à la suivante, sans fondu (personne ne porte la moitié de lunettes), et on l'ôte en indiquant <code>"none"</code>. Une image clé qui indique <code>viewOnly: true</code> fixe la vue de son seul instant (l'éditeur l'écrit quand on tourne la vue en tenant Alt enfoncé) : la rotation de la caméra vers cette vue et depuis elle n'apparaît pas dans l'image, et une pose photographique (une exposition) qui recouvre cette image clé est dessinée comme si la caméra était restée immobile, pointée comme à l'instant montré. Un témoin qui vole à une altitude donnée l'indique par <code>altitudeM</code> (mètres au-dessus de la mer) : le lecteur place alors l'œil à cette altitude au-dessus du relief qu'il dessine, et <code>elevationM</code> n'est plus que la hauteur au-dessus du sol contre lequel le fichier a été écrit, celle contre laquelle est aussi coté le décor d'une cabine autour de l'œil.</td></tr>
      <tr><td><code>events</code></td><td>Ce qu'a fait le témoin, décrit par des événements et leurs paramètres plutôt que par les poses qui en découlent : <code>[{ type: "event", eventType, t, until, params }]</code>, <code>t</code> et <code>until</code> en ms de l'enregistrement. Le lecteur en déduit les poses au chargement de l'enregistrement, selon les mêmes règles pour tous les enregistrements (une rotation de la tête part de l'immobilité et se stabilise, la trajectoire d'un véhicule est une courbe). À l'écriture, il ne réécrit que les événements, tant que rien n'a modifié ces poses. Un <code>observerTrack</code> qui a ses propres images clés l'emporte sur les événements. Un paramètre porte sa provenance comme toute valeur. Une table d'instants (<code>speeds</code>, <code>speedDivisors</code>, <code>heights</code>, <code>metres</code>) a autant de lignes que le récit en demande ; sa valeur passe progressivement d'une ligne à la suivante, ou d'un coup à une ligne qui porte <code>step: true</code>. À pied : <code>look</code> (un regard tenu à partir de <code>t</code>, <code>headingDeg</code>, <code>pitchDeg</code>), <code>walk</code> (de <code>from</code> à <code>to</code>, deux <code>{ lat, lng }</code>, entre <code>t</code> et <code>until</code>, comme marche et s'arrête une personne) et <code>follow</code> (suivre des yeux <code>target</code>, un corps de la lecture ou un phénomène qui traverse le ciel : les yeux le rejoignent au bout de <code>reactionS</code>, puis le suivent avec <code>lagS</code> de retard. La cible est placée au centre de ce que voit le témoin à chacune de ses images clés, ou toutes les <code>sampleMs</code> si elle n'en a pas, et le regard tourne entre ces instants comme tourne une tête. À <code>until</code>, le regard reste là où le témoin a perdu la cible ; <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>). En véhicule : <code>drive</code> (le véhicule où est le témoin, un objet du décor nommé par <code>vehicle</code>, suit <code>path</code>, une liste de <code>{ lat, lng }</code>, aux vitesses <code>speeds</code> <code>[{ t, kmh }]</code>, éventuellement divisées par <code>speedDivisors</code> <code>[{ t, divisor }]</code>, et situé sur ce chemin grâce au seul point de passage daté, <code>through</code> <code>{ t, lat, lng }</code> ; l'<code>eye</code> du conducteur est <code>{ x, y, z }</code> dans le modèle du véhicule), <code>lookAhead</code> (le témoin regarde la route en gardant la cible <code>target</code> <code>{ lat, lng }</code> à moins de <code>keepDeg</code> environ ; quand elle s'écarte de plus de <code>glanceBeyondDeg</code>, il lui jette des coups d'œil de <code>glanceS</code>, chacun suivi de <code>roadS</code> sur la route ; <code>pitchShare</code> dit jusqu'à quelle part de sa hauteur il lève les yeux), <code>lean</code> (vers le rétroviseur : l'œil se déplace de <code>offsetM</code> en <code>turnS</code>, pendant <code>holdS</code>) et <code>watch</code> (regarder dans le rétroviseur <code>mirror</code>, un point du modèle du véhicule : d'abord pendant <code>firstS</code>, puis pendant <code>mirrorS</code> entre deux regards ailleurs. Jusqu'à <code>glancesUntil</code>, un regard ailleurs sur deux est un coup d'œil direct vers la cible, de <code>glanceS</code> ; les autres vont à la route, pendant <code>roadS</code>). Chaque événement dit dans <code>who</code> à qui ou à quoi il se rapporte, par un id que rien d'autre ne porte dans l'enregistrement : celui du témoin (<code>observer.id</code>, ou <code>"observer"</code> pour un témoin qui n'en a pas ; un événement qui n'en dit aucun est le sien), d'une forme ou d'un groupe de formes, d'un corps, d'un objet du décor. L'éditeur refuse d'enregistrer un fichier où un événement ne se rapporte à rien, ou où deux choses portent le même id. Événement d'un objet du décor : <code>fly</code> (un avion qui vole en ligne droite vers <code>from</code> <code>{ lat, lng }</code>, au cap <code>headingDeg</code>, aux vitesses <code>speeds</code> ; il est à <code>at.metresBefore</code> mètres avant ce lieu à l'instant <code>at.t</code>, et aux hauteurs <code>heights</code> <code>[{ t, altitudeM }]</code> au-dessus de l'œil du témoin). Événements d'un de ses feux (<code>id/feu</code>, <code>f-hobs/landing-nose</code>) ou d'un groupe de feux que nomment les <code>groups</code> de l'objet (<code>f-hobs/strobes</code>) : <code>light</code> (le feu passe à l'intensité <code>intensity</code> au début de l'événement, 0 pour éteint, en gardant son clignotement ; si l'événement indique une fin, le feu revient alors à ce qu'il était) et <code>blink</code> (allumé pendant <code>onS</code>, éteint pendant <code>offS</code>, à <code>intensity</code> ou à ce qu'il était, jusqu'à la fin de l'événement, puis comme avant) : un phare d'atterrissage éteint, des flashs allumés, un gyrophare, le balisage d'un sommet d'immeuble. Les événements du phénomène (<code>who</code> est la forme sous laquelle il est dessiné, ou le groupe de ses formes) donnent les formes du compte rendu, tel que le témoin l'a décrit : <code>stand</code> (le phénomène se tient au lieu <code>place</code> que le témoin a indiqué, <code>{ lat, lng }</code> ; <code>metres</code> <code>[{ t, widthM, heightM }]</code> donne sa largeur et sa hauteur au-dessus de l'œil, d'où l'on déduit à chaque instant sa direction et sa taille dans le ciel du témoin), <code>appearance</code> (son aspect à partir de <code>t</code>, ses <code>parts</code> : des formes placées et dimensionnées en parts de sa largeur apparente, <code>sourceId</code>, <code>kind</code>, <code>points</code>, <code>color</code>, <code>brightness</code>, <code>halo</code>, <code>widthShare</code>, <code>heightShare</code>, <code>alongShare</code>, <code>upShare</code> ; une partie qu'un autre aspect a et que celui-ci n'a pas n'est pas vue), <code>blink</code> (les formes concernées, un groupe de formes du phénomène ou l'une d'elles, sont allumées pendant <code>onS</code>, éteintes pendant <code>offS</code>, et prennent <code>off</code> pendant qu'elles sont éteintes) et <code>vanish</code> (il n'est plus vu). Ou, sans lieu, traversant le ciel, un compte rendu en directions seulement : <code>travel</code> (<code>from</code> une direction <code>{ azimuthDeg, altitudeDeg }</code> <code>towards</code> une autre, le long du grand cercle qui les joint, aux vitesses <code>speeds</code> <code>[{ t, degPerS }]</code>, en douceur entre deux ; <code>sizeDeg</code> de large au zénith, et réduit en proportion du sinus de sa hauteur quand <code>sizeBy</code> vaut <code>"altitude"</code> ; ses parties disposées le long de sa route sur l'image du témoin, <code>alongShare</code> devant ou derrière, <code>upShare</code> à sa gauche, tournées avec elle), <code>turn</code> (de <code>byDeg</code> vers son côté <code>side</code>, <code>"left"</code> ou <code>"right"</code>, en douceur ; l'autre côté sur le ciel quand <code>seenFrom</code> vaut <code>"craft"</code>, comme le dit un pilote), <code>roll</code> (incliné jusqu'à <code>toDeg</code>, et revenu à plat avec <code>andBack</code>, plus étroit en travers de sa route du cosinus de l'inclinaison), <code>vibrate</code> (d'un côté à l'autre <code>hz</code> fois par seconde, de <code>amplitudeShare</code> de sa taille, depuis rien en <code>riseS</code>, puis de moins en moins jusqu'à la fin de l'événement) et <code>spiral</code> (<code>turns</code> tours d'un cercle à côté de sa route, <code>clockwise</code> ou non, de <code>radiusDeg</code> une fois ouvert, réduit de <code>shrink</code> à la fin, en roulant de <code>rollDeg</code>) ; <a href="/demo-data/observer-saint-lo.json"><code>observer-saint-lo.json</code></a>. Les événements d'un corps de la lecture s'ajoutent aux images clés qu'il indique. Leur <code>who</code> est son id ; pour une partie de son modèle (un nœud ou un os), c'est <code>id/partie</code> : <code>craft/legs</code>, <code>etre-2/head</code>, et <code>spin</code> et <code>turn</code> font alors tourner cette partie seule autour de son propre axe vertical, dans le sens horaire vue d'en haut, sans toucher au reste du corps. Pour un feu, c'est son nom dans le modèle (<code>engin/front-red</code>), ou un groupe de ses parties que nomment les <code>groups</code> du corps (<code>engin/rear</code>) ; c'est le fichier du modèle qui dit quelles parties il a. Ces événements sont : <code>motion</code> (un mouvement de son modèle, nommé par <code>motion</code>, joué une fois jusqu'à <code>to</code> : par exemple le tube central qui rentre), <code>spin</code> (un mouvement joué en continu, à <code>turnsPerS</code> tours par seconde : par exemple les pieds), <code>rise</code> (<code>distanceM</code> le long d'une droite à <code>angleDeg</code> de la verticale, 0 tout droit, vers <code>headingDeg</code>, depuis l'arrêt, ralentissant jusqu'à s'arrêter ou, <code>stops: false</code>, de plus en plus vite en partant), <code>turn</code> (se tourner vers <code>headingDeg</code>), <code>ride</code> (porté par le corps <code>in</code>, <code>aboveM</code> plus haut), <code>light</code> (un feu, ou un groupe de feux, allumé à <code>cdM2</code> dès le début de l'événement, 0 éteint, et rallumé comme il était à sa fin quand il en énonce une) et <code>blink</code> (un feu qui clignote, allumé pendant <code>onS</code>, éteint pendant <code>offS</code>, à <code>cdM2</code> une fois allumé ou à ce qu'il était avant, jusqu'à la fin de l'événement, puis comme avant ; d'un coup, jamais en fondu : les flashs d'un avion, un gyrophare, le feu d'un pylône) et <code>vanish</code> ; une posture est aussi un mouvement du modèle (<code>motion</code> sur <code>crouch</code>, que porte une silhouette exportée avec ses postures : 0 debout, 1 accroupi) ; l'engin et les êtres de <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>. <a href="/demo-data/observer-silly-le-long.json"><code>observer-silly-le-long.json</code></a> énonce ainsi son témoin, son avion et son phénomène</td></tr>
      <tr><td><code>sampleMs</code></td><td>L'intervalle entre deux images clés, en ms. Il sert à l'enregistreur de l'éditeur quand on déplace une forme à la main, et partout où les événements sont convertis en valeurs (les formes du compte rendu, le regard qui les suit, un corps qui s'élève). Tous utilisent le même pas, pour que ce qui est dessiné et le regard qui le suit ne se décalent jamais. Parmi les images clés obtenues, une suite d'images clés identiques est réduite à la première et à la dernière : le lecteur dessine la même chose entre elles. Absent, chaque calcul garde son propre pas : 25 ms pour un phénomène qui traverse le ciel et le regard qui le suit, 2 s pour un phénomène immobile, 250 ms pour un corps qui s'élève</td></tr>
      <tr><td><code>weatherTrack</code></td><td><code>{ keyframes: [{ t, weather }] }</code> — l'état du ciel le long de l'enregistrement : précipitation, vent, orage, et les nuages en couches à hauteur réelle, chacune pouvant porter des nuages individuels placés en mètres. Chaque champ d'un <code>weather</code> est dans la section suivante</td></tr>
      <tr><td><code>weatherSource</code></td><td><code>{ id, name, url }</code> du relevé d'où vient la météo. Sa présence signifie que l'enregistrement est rejoué tel qu'il a été composé et que la météo n'est jamais redemandée. Absent : la météo vient du récit du témoin lui-même</td></tr>
      <tr><td><code>lightPollution</code></td><td>La brillance du ciel nocturne du lieu, villes comprises : le zénith d'une nuit sans Lune en magnitudes par seconde d'arc carrée, tel qu'un Sky Quality Meter le lit ou que l'<a href="https://doi.org/10.1126/sciadv.1600377">atlas mondial de la brillance artificielle du ciel nocturne</a> le donne (son chiffre « SQM », Falchi et al. 2016, que <a href="https://www.lightpollutionmap.info">lightpollutionmap.info</a> affiche pour tout lieu). <code>22</code> est un ciel naturel, une banlieue vers <code>19</code>, un centre-ville <code>17</code>. Absent : un ciel naturel. La part des villes, ce qui reste une fois ôtés les 22 naturels, s'ajoute au ciel comme de la lumière : plus forte vers l'horizon, où l'air bas en renvoie davantage, et dessinée du blanc chaud d'une lampe à 3000 K. Elle noie la Voie lactée et la lumière zodiacale, et fait disparaître des étoiles : la magnitude limite (celle de la plus faible étoile qu'un œil distingue) baisse (Crumey 2014), d'environ deux magnitudes à <code>19</code>. La Lune en fait désormais autant. Sa provenance est <code>"derived"</code> quand la valeur vient de l'atlas, <code>"stated"</code> quand le témoin l'a mesurée. L'éditeur la remplit d'après l'atlas pour une observation de 2015 ou après, en <code>"derived"</code> avec l'atlas nommé, et ne remplace jamais une valeur saisie à la main ; avant 2015 il ne demande rien, le ciel ayant été plus sombre que celui de l'atlas</td></tr>
      <tr><td><code>around</code></td><td>Ce qui faisait du bruit autour de l'observateur, contre quoi un avion s'entend comme contre le vent et la pluie : <code>cars</code> (voitures), <code>trucks</code> (camions et bus), <code>people</code> (personnes) et combien d'entre elles <code>talking</code> (parlaient), présents à la fois dans un rayon de <code>withinM</code> mètres (200 si absent), et <code>roads</code> (routes), chacune <code>{ distanceM, vehiclesPerMinute, trucksPerMinute, speedKmh }</code> (50 km/h si absent), puisqu'un témoin peut dire l'un ou l'autre. Ce qu'on en entend là où se tient l'observateur se calcule d'après la puissance acoustique des véhicules de <a href="https://eur-lex.europa.eu/legal-content/FR/TXT/?uri=CELEX:32021L1226">CNOSSOS-EU</a> (une voiture à 50 km/h fait 73 dB(A) à 7,5 m) et les 55 dB(A) à 1 m d'une conversation (Pearsons et al. 1977) : ce qui est compté comme réparti sur son disque, une route comme une ligne. Cela s'ajoute au bruit de la météo : la circulation d'une ville masque des avions qu'un champ calme laisse entendre. Rien n'en est encore joué : le bruit d'une route joué en nappe faisait un souffle par-dessus les avions ; on l'entendra quand la scène aura ses propres véhicules. Chaque valeur a sa provenance, à <code>around.cars</code> ou <code>around.roads.0.distanceM</code>. Absent : un lieu calme</td></tr>
      <tr><td><code>observerMap</code></td><td>Si la carte de l'endroit où se tenait le témoin s'ouvre d'emblée quand l'enregistrement est joué ou édité : <code>true</code> ou <code>false</code>. Absent : le lecteur décide, ouverte pour un témoin qui s'est déplacé, fermée pour un qui est resté sur place. Une page qui intègre le lecteur a le dernier mot (son attribut <code>show-observer-map</code>). L'éditeur l'écrit quand on y ouvre ou ferme la carte, pour que celui qui regarde l'enregistrement la trouve comme l'auteur l'a laissée</td></tr>
      <tr><td><code>snapshots</code></td><td>Les données que la scène demanderait sinon à des tiers à chaque lecture, gardées dans des fichiers à côté de l'enregistrement (des annexes) : ainsi un enregistrement terminé se rejoue à l'identique dans dix ans sans rien demander à personne. Ces groupes de données sont <code>relief</code> (la hauteur du sol, telle que la source d'altitude l'a donnée pour chaque morceau de terrain que construit la scène, un zip), <code>imagery</code> (la photo du sol, sous la forme des tuiles servies par la source d'imagerie, un zip), <code>roads</code>, <code>water</code>, <code>railways</code> (les routes, l'eau et les voies de chaque morceau, en JSON), <code>upperAir</code> (l'air à l'altitude des avions, en JSON) et <code>map</code> (la photo sous la carte du témoin, sous la forme des tuiles servies par la source d'imagerie pour le terrain auquel la carte est ajustée, un zip : une carte prise en instantané montre cette photo et n'en demande aucune autre, agrandie quand on zoome dedans, vide au-delà quand on dézoome). Chacun vaut <code>{ src, takenOn, attribution }</code>, <code>src</code> étant lu par rapport à l'adresse de l'enregistrement, ou une URL <code>data:</code> pour une annexe gardée dans l'enregistrement même. Un groupe lu dans son annexe ne demande rien à personne ; un groupe sans annexe est demandé en direct, comme tout l'était avant. <code>"live": true</code> sur un groupe le fait demander en direct à chaque lecture, sans jamais en prendre d'instantané (c'est ce que signifie choisir pour ce groupe sa source en direct plutôt que <em>Fichier</em>) ; placé sur <code>snapshots</code> lui-même, il vaut pour tous les groupes. <code>"refresh": true</code> sur un groupe le fait demander en direct une fois, et l'éditeur en reprend un instantané à la sauvegarde suivante. À la sauvegarde, l'éditeur prend les instantanés qui manquent, et enregistre l'enregistrement et ses annexes en un seul zip, à décompresser là où il est publié. Les clés <code>weather</code>, <code>place</code>, <code>lightPollution</code> et <code>decor</code> indiquent que la météo (<code>weatherTrack</code>, <code>weatherSource</code>), le nom du lieu, la valeur du ciel nocturne et le décor sont lus dans le fichier au lieu d'être redemandés par l'éditeur (au service météo quand la date ou le lieu changent ; au géocodeur, à l'atlas et au relevé du décor quand le témoin se déplace). Elles valent <code>{}</code> si ces données sont dans l'enregistrement, ou <code>{ src }</code> pour une annexe qui contient leurs clés, que les lecteurs remettent dans l'enregistrement en le chargeant. Absentes, les données sont dans l'enregistrement, mais l'éditeur les redemande. Le fuseau horaire n'y est pas : il est écrit dans l'enregistrement lui-même</td></tr>
      <tr><td><code>modules</code></td><td>Les modules dont l'enregistrement a besoin pour être dessiné tel qu'il a été fait (un catalogue d'où viennent ses modèles), par l'adresse du manifeste de chacun, relative à l'enregistrement ou absolue : voir <a href="/docs/modules/">modules</a>. Un lecteur reçoit ce que chaque manifeste énonce, jamais son script, sauf s'il a ajouté ce module lui-même. Absent, il n'en a besoin d'aucun</td></tr>
      <tr><td><code>soundTrack</code></td><td><code>{ keyframes: [{ t, sound }] }</code> — <code>kind</code> (none/hum/whistle/rumble/crackle), <code>volume</code>, <code>pitchHz</code>, et un <code>src</code> facultatif vers un vrai enregistrement. <code>volume</code> et <code>pitchHz</code> glissent d'une image clé à l'autre, <code>kind</code> et <code>src</code> changent à l'image clé. Un <code>src</code> sur un autre site doit être servi à toute origine (CORS)</td></tr>
      <tr><td><code>references</code></td><td>Photos des lieux posées sur la scène : <code>src</code> (une adresse, ou une URL <code>data:</code> pour une photo ajoutée depuis un disque), <code>kind</code> (photo/panorama/video), <code>registration</code> (<code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>), <code>opacity</code>, <code>credit</code>/<code>creditUrl</code>, <code>t</code> et <code>drawing</code> facultatifs, <code>from</code> (<code>{ lat, lng }</code>, d'où elle a été prise : le lecteur l'efface en fondu quand le témoin s'éloigne de ce point ; absent, elle ne s'efface jamais), et les <code>landmarks</code> sur lesquels elle a été recalée (<code>id</code>, <code>label</code>, <code>picture</code> en <code>{ u, v }</code> depuis le coin haut gauche, <code>scene</code> en <code>{ azimuthDeg, altitudeDeg }</code>) Une <code>video</code> indique aussi <code>t</code>, l'instant de la ligne de temps où commence son extrait, <code>video</code> (<code>fromS</code>, <code>toS</code>, <code>rate</code> : quelle partie du fichier, à quelle vitesse) et <code>registrationTrack</code>, où pointait sa caméra à chacun des instants où elle a été recalée.</td></tr>
      <tr><td><code>traces</code></td><td>Ce qu'un enquêteur a dessiné sur les lieux, importé de son fichier Google Earth (KML, KMZ) ou du GeoJSON de son SIG et affiché sur la scène comme étant le sien, jamais comme une partie de la reconstitution : <code>[{ id, title, kind, points, altitude, color, source }]</code>, <code>kind</code> valant <code>point</code>, <code>line</code> ou <code>polygon</code>, <code>points</code> les sommets en <code>[{ lat, lng, altM }]</code> tels que le fichier les portait, <code>altitude</code> la façon de lire <code>altM</code> (<code>ground</code>, par défaut, <code>relative</code> au sol sous chaque point, ou <code>absolute</code> au-dessus du niveau de la mer), <code>color</code> un <code>#rrggbb</code> et <code>source</code> à qui il appartient</td></tr>
      <tr><td><code>instrument</code>, <code>exposureSeconds</code></td><td>À travers quoi l'observation a été faite, et combien de temps l'obturateur est resté ouvert. Absent : l'œil nu. <code>instrument</code> vaut <code>eye</code>, <code>rectilinear-lens</code> (un appareil de modèle inconnu), <code>roamer-1-120</code>, <code>instamatic-126</code>, <code>slr-35mm-50</code>, <code>slr-35mm-zoom</code>, <code>phone-landscape</code>, <code>phone-portrait</code>, ou un reflex numérique (<code>eos-5d-iii</code>, <code>nikon-d7000</code>… les capteurs du catalogue de Stellarium), des jumelles (<code>binoculars-nikon-10x42-edg</code>…) ou un télescope (<code>telescope-celestron-c8</code>…) ; <code>exposureSeconds</code> est une seule valeur pour tout l'enregistrement, limitée à la plage de l'appareil. Un appareil qui enregistre une image (un appareil photo, un téléphone) ajoute à chaque lumière les reflets fantômes de son objectif, comme le font le verre et le capteur : une copie plus faible et floue de la lumière, sur la droite qui passe par le centre de l'image. Pour le reflet principal d'un téléphone, cette copie est symétrique de la lumière par rapport au centre : le disque rouge à l'opposé d'un feu tricolore. Un téléphone s'expose lui-même d'après ce qu'il voit, jusqu'à ISO 3200 : une nuit qu'il filme reste sombre autour de ses lampes</td></tr>
      <tr><td><code>lens</code></td><td>Ce à travers quoi l'image a été prise en plus de l'objectif, et ce qu'il y avait sur ce verre, pour un appareil qui en enregistre une : <code>glass</code> (<code>filter</code>, <code>window</code> ou <code>windscreen</code> : un filtre ajoute un reflet symétrique par rapport au centre, une vitre un double plus faible de chaque lumière juste à côté, plus loin pour un pare-brise incliné), <code>drops</code>, <code>condensation</code> et <code>dirt</code> (de 0 à 1 ; chacun diffuse autour de chaque lumière un halo, pris sur la lumière elle-même) et <code>sheltered</code>. Sans <code>drops</code>, les gouttes suivent la pluie ou la neige qui tombe à chaque instant, sauf si <code>sheltered</code> est vrai. De nouvelles gouttes se posent d'autant plus souvent que la pluie frappe le verre de face (un objectif levé, une vitre face au vent, un pare-brise incliné en reçoivent plus), et fusionnent avec leurs voisines ; les petites restent accrochées des minutes, les grosses coulent au bout de quelques secondes en laissant une traînée de perles et en essuyant ce qu'elles croisent, et continuent une fois la pluie arrêtée. Les reflets de l'objectif lui-même suivent son ouverture : plus larges à pleine ouverture, et en forme du polygone de ses lamelles une fois diaphragmé. <code>ghosts</code> indique les reflets d'une optique placée devant l'objectif, qu'aucun catalogue ne connaît (le miroir et les prismes d'un périscope), chacun comme ceux d'un objectif : <code>scale</code>, <code>share</code>, <code>blur</code>, <code>offset</code>, <code>tint</code> ; <code>reachDeg</code> jusqu'où, au-delà du coin du cadre, une lumière frappe encore sa première surface (30° pour un objectif) ; <code>placedDrops</code> des gouttes indiquées une à une au lieu de celles que <code>drops</code> répartit au hasard, chacune un <code>radius</code> (part de la hauteur de l'image) et une <code>track</code> de <code>{t, x, y}</code> (ms, parts de la largeur et de la hauteur de l'image depuis son coin haut gauche), la goutte restant immobile avant le premier et après le dernier point ; <code>drops</code> ne dit plus alors que combien de lumière elles diffusent</td></tr>
      <tr><td><code>lighting</code></td><td>Ce que l'image montre de la lumière où elle a été prise, quand cela dit où était le Soleil (un côté éclairé, un côté à l'ombre) : <code>sunFromViewDeg</code>, l'arc des gisements du Soleil, dans le sens horaire depuis la direction où regardait l'instrument au départ (<code>{ fromDeg: 105, toDeg: 285 }</code> : derrière lui, d'un côté ou de l'autre), et <code>sunAltitudeDeg</code> (<code>{ minDeg, maxDeg }</code>), sa plus petite et sa plus grande hauteur. Il contraint toute lecture de l'observation : la date, l'heure, le lieu et le cap qu'elle indique peuvent bouger dans ce qu'on sait de chacun, mais le Soleil qu'ils composent doit éclairer la scène comme l'image la montre, si bien que déplacer le lieu déplace les heures permises, et inversement</td></tr>
      <tr><td><code>iso</code></td><td>La sensibilité du film ou du capteur de la photo, quand on la connaît : <code>400</code> pour un film 400 ISO. Absent : celle de l'appareil (100 pour le négatif couleur d'un reflex, 64 pour celui d'un Instamatic). La photo d'un appareil ne répond pas comme un œil : un film ne s'adapte pas au ciel, il reçoit une exposition (la lumière, fois le temps de pose, divisée par le carré de l'ouverture) et y répond selon sa propre courbe (douce pour un négatif, plus raide pour une diapositive, droite puis arrêtée net au blanc pour un capteur). Une pose de nuit sort donc avec un ciel noir, et ce qui y brillait ressort. Indiquée pour un appareil qui règle lui-même son exposition (un téléphone), elle signifie que cet appareil a été réglé à la main, comme en mode manuel</td></tr>
      <tr><td><code>film</code></td><td>La pellicule de la prise de vue, quand on la connaît, par son identifiant dans le catalogue : <code>"kodachrome-64"</code>. Elle donne la sensibilité, sauf si <code>iso</code> en dit une autre, et la réponse à la lumière, noir et blanc compris. Absente : personne ne le dit.</td></tr>
      <tr><td><code>metering</code></td><td>Comment un appareil qui règle lui-même son exposition a lu la lumière, quand on le sait : <code>"average"</code>, la moyenne de toute l'image, comme les caméscopes et les anciens téléphones : une lumière vive dans une image sombre sort alors blanche, brûlée. Ou <code>"highlights"</code>, comme les téléphones récents : l'exposition est réduite pour qu'une lumière qui occupe une part notable de l'image garde sa couleur (une lanterne à vingt mètres sort orange, blanche seulement près de sa flamme), et le reste de la nuit sort plus sombre. Absent : celle de l'appareil (un téléphone protège ses hautes lumières)</td></tr>
      <tr><td><code>sway</code></td><td>Combien le corps qui tient l'instrument fait bouger la vue quand il ne marche pas : <code>1</code> pour une personne debout ou assise, <code>0</code> pour un appareil sur trépied, entre les deux ou au-delà pour moins ou plus. Absent, c'est <code>1</code>, sauf pour un témoin que le compte rendu dit paralysé (étiquette <code>paralysis</code>), pour qui c'est <code>0</code>, et pour une pose de plus d'une demi-seconde, qu'aucune main ne tient immobile : c'est un trépied, et <code>0</code> aussi</td></tr>
      <tr><td><code>vehicle</code></td><td>Le véhicule où se trouvait le témoin, quand le décor ne le dessine pas : <code>{ kind, windowsOpen, noise }</code>, <code>kind</code> valant soit un véhicule routier (<code>car</code>, <code>van</code>, <code>truck</code>, <code>motorcycle</code>, <code>generic</code>), soit un avion, par sa classe comme se nomment les avions du ciel (<code>business-jet</code>, <code>airliner-narrow</code>, <code>helicopter-light</code>…) : un seul champ pour les deux, les deux vocabulaires n'ayant aucun mot en commun. Entendu de l'intérieur, son moteur suit le trajet du témoin : le rapport engagé dépend de la vitesse, le régime du rapport, l'effort de ce que le véhicule accélère ou ralentit. S'y ajoutent le bruit de roulement et le vent, étouffés par un habitacle fermé, et qui entrent par des vitres ouvertes. Un avion n'a ni rapports ni cylindres : ce qu'on en entend est le grondement continu de sa cabine, au niveau qu'y mesure un passager pour cette classe de machine. <code>noise</code> est son niveau sonore par rapport à un véhicule ordinaire de son type (1 par défaut). Le véhicule où se trouve le témoin s'interpose aussi entre lui et tout ce qui est dehors, et atténue plus les aigus que les graves : un avion à cent mètres n'est qu'un grondement à travers un fuselage, et sous le bruit de la cabine il n'est plus entendu du tout ; la pluie et le vent entrent étouffés de même. <code>windowsOpen</code> laisse presque tout revenir. C'est aussi ce qui garde actif le bouton de son du lecteur quand le fichier n'a pas de <code>soundTrack</code> : le bouton commande tout ce que joue la scène (ce moteur, un <code>engine</code> du décor, un avion du décor en vol, un corps d'une lecture qui s'entend, la pluie et le vent), et pas seulement la piste. Ses feux : <code>headlights</code> est un réglage comme pour un véhicule de décor (<code>off</code>, <code>position</code>, <code>dipped</code>, <code>main</code>, <code>fog</code>) ou <code>auto</code>, par défaut : les feux de croisement à partir du crépuscule et rien le jour, ce que fait un conducteur. <code>headlightKeyframes</code> est <code>[{ t, mode }]</code> pour un changement pendant l'enregistrement. Le faisceau éclaire la route devant le témoin, dans la direction où va le véhicule.</td></tr>
      <tr><td><code>decor</code></td><td>Le décor, à une vraie distance <code>eastM</code>/<code>northM</code> du témoin : bâtiments (avec <code>floors</code>, <code>windows</code>), arbres, buissons, lampadaires, véhicules, ponts, lignes aériennes, autres témoins, aéronefs — éventuellement avec une <code>track</code> et des <code>lights</code> dont le <code>pattern</code> porte une vraie cadence d'éclats. Voir ci-dessous</td></tr>
    </table>
    </div>
    <p>Un <strong>objet du décor</strong> s'énonce en mètres, comme tout ce qui n'est pas le phénomène :</p>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Sens</th></tr>
      <tr><td><code>eastM</code>, <code>northM</code>, <code>headingDeg</code></td><td>Où il se tient par rapport au témoin, et vers où regarde son avant, en degrés depuis le nord vrai dans le sens horaire</td></tr>
      <tr><td><code>sizeM</code></td><td><code>{ widthM, lengthM, heightM }</code> selon ses propres axes, la longueur étant le sens où il regarde. Chaque axe est facultatif : celui que personne n'a mesuré garde la proportion de la forme intégrée</td></tr>
      <tr><td><code>model</code></td><td>Un vrai modèle 3D à la place de la forme intégrée : une entrée du catalogue par <code>id</code>, ou un fichier glTF/GLB à <code>url</code> (qui l'emporte, doit être lisible depuis toute origine, et exige alors son <code>credit</code> ; une adresse relative se lit depuis le fichier qui l'énonce). Il ne décide jamais de la taille : il est mis à l'échelle, proportions gardées, sur le premier axe mesuré parmi longueur, hauteur et largeur, ou sur la taille réelle que lui donne le catalogue. Vu de l'intérieur, et chaque fois que le modèle ne peut être obtenu, c'est la forme intégrée qui est dessinée. Un <code>observer</code> ou une <code>entity</code> qui n'en nomme aucun n'est jamais dessiné en forme intégrée : c'est une des personnes réalistes du catalogue, choisie par son <code>id</code> (un enfant, ou un être que décrit un témoignage, nomme son propre modèle). <code>headingOffsetDeg</code> tourne le modèle chargé autour de son axe vertical pour que son nez pointe où la scène l'attend (0 regarde le nord pour un cap de 0) ; une entrée du catalogue apporte le sien. <code>credit</code> est <code>{ title, author, license, sourceUrl }</code> : <code>license</code> telle que son auteur l'énonce (<code>"CC BY 4.0"</code>) et <code>sourceUrl</code> d'où il vient, pour que cette licence puisse être vérifiée.</td></tr>
      <tr><td><code>bridge</code></td><td>Pour un <code>"bridge"</code> : comment il est construit. <code>sizeM.lengthM</code> est toute sa longueur le long de la route, remblais compris, <code>widthM</code> la largeur du tablier et <code>heightM</code> la hauteur de la chaussée sur le tablier au-dessus du sol ; <code>spanM</code> est la portée libre sous le tablier, la route courant de chaque côté sur un remblai de terre qui descend jusqu'au sol ; <code>deckThicknessM</code> l'épaisseur de la dalle (1,2 par défaut) ; <code>railing</code> <code>{ heightM, postSpacingM, rails }</code> le garde-corps des deux rives, poteaux et lisses dont les ouvertures sont des rectangles (1,05 m, 1,5 m et 2 lisses par défaut). Dessiné à ces cotes, jamais étiré</td></tr>
      <tr><td><code>wire</code></td><td>Pour un <code>"wire"</code> (une ligne électrique ou téléphonique) : <code>sizeM.lengthM</code> est la portée entre ses poteaux, le long de son <code>headingDeg</code>, et <code>heightM</code> la hauteur du fil le plus bas ; <code>strands</code> <code>[{ heightM, acrossM }]</code> en suspend plusieurs (des fils superposés partagent un <code>acrossM</code>, ceux d'une traverse diffèrent) ; <code>poles</code> vaut <code>both</code> (par défaut), <code>start</code> ou <code>end</code> (seulement à l'extrémité de départ ou d'arrivée selon son cap : l'autre extrémité est ancrée sur un bâtiment) ou <code>none</code> ; <code>diameterM</code> (8 mm par défaut) et <code>poleHeightM</code> (un demi-mètre au-dessus du fil le plus haut). Droite, sans flèche (le fil ne s'affaisse pas), et dessinée à ces mesures, jamais étirée</td></tr>
      <tr><td><code>track</code></td><td><code>[{ t, eastM, northM, altitudeM, headingDeg }]</code> quand il se déplace, <code>altitudeM</code> au-dessus du sol sous lui (l'œil est à <code>elevationM</code> + 1,6 m : un corps à hauteur d'œil a cet <code>altitudeM</code>). La position est interpolée entre les images clés ; le cap est tenu de l'une à la suivante</td></tr>
      <tr><td><code>lights</code></td><td>Ses feux : <code>id</code>, <code>offsetM</code> <code>{ x, y, z }</code> depuis son centre (droite, haut, avant), <code>color</code>, <code>intensity</code> (1 pour un feu de navigation ordinaire) et un <code>pattern</code> : <code>{ "kind": "steady" }</code>, ou <code>{ "kind": "flash", perMinute, dutyCycle, phase }</code>, la cadence telle que l'énoncent les règlements, la part allumée de chaque cycle (environ 0,5 pour un clignotant à filament, 0,01 pour un stroboscope) et un décalage de 0 à 1 entre feux. L'éditeur les remplit depuis des préréglages : avion de ligne, hélicoptère, phares de voiture, feux de détresse, gyrophares, lampadaire. <code>keyframes</code> <code>[{ t, intensity, pattern }]</code> dit comment un feu est allumé ou éteint pendant l'enregistrement, à partir de chaque instant : c'est ce que produisent les événements <code>light</code> et <code>blink</code> qui le concernent</td></tr>
      <tr><td><code>groups</code></td><td>Ses feux pris ensemble, pour qu'un seul événement les concerne tous : <code>{ id, title, members }</code>, les membres étant des feux de l'objet ou d'autres de ses groupes. Nommé dans un événement comme un feu, <code>id/groupe</code> : les deux flashs d'un avion, <code>f-hobs/strobes</code>. Facultatif</td></tr>
      <tr><td><code>engine</code></td><td>Un véhicule qu'on entend tourner : <code>{ kind, noise }</code>, comme <code>vehicle</code> plus haut. Son moteur suit sa propre <code>track</code>, entendu depuis le témoin, plus faible et plus sourd avec la distance</td></tr>
      <tr><td><code>aircraftSound</code></td><td>Un aéronef (kind <code>aircraft</code>) qu'on entend en vol, c'est-à-dire quand sa <code>track</code> quitte le sol : le genre de bruit qu'il fait, un type d'aéronef (<code>airliner-narrow</code> par défaut, <code>airliner-wide</code>, <code>airliner-supersonic</code>, <code>regional-jet</code>, <code>helicopter-light</code>, <code>light-piston</code>…) ou <code>silent</code> pour un appareil qui n'en fait pas. Quand le champ est absent, c'est ce que dit son modèle qui s'applique (les modèles qui figurent un phénomène sont silencieux). Il s'entend comme les aéronefs d'un relevé de trafic : plus faible et plus sourd avec la distance, <em>en retard</em> du temps que met le son à venir (environ trois secondes par kilomètre) donc entendu là où il était, plus aigu quand il approche et plus grave quand il s'éloigne, et masqué par le bruit du lieu ; un avion à réaction plus fort au décollage qu'en approche, et derrière que devant, avec l'écho du sol sous lui. Un aéronef à l'intérieur duquel se tient le témoin (un pilote dans son poste) est celui qu'il monte : on ne l'entend pas passer, mais comme sa cabine, et ce qui est dehors à travers sa coque, comme avec <code>vehicle</code></td></tr>
      <tr><td><code>occludesSourceIds</code></td><td>Les phénomènes devant lesquels le témoin a dit que cet objet se trouvait : voir les <a href="/docs/format/#four-rules-that-decide-what-a-file-means">règles de la page du format</a></td></tr>
      <tr><td><code>facade</code></td><td>Type <code>building</code> seulement : <code>{ color?, plain? }</code>. <code>color</code> est le mur, <code>"#rrggbb"</code> ; sauf si <code>plain</code> vaut <code>true</code>, des fenêtres sont dessinées à chaque étage et une porte au rez-de-chaussée de la face avant. Dessinée à la <code>sizeM</code> indiquée (ses trois dimensions doivent l'être), jamais étirée, et pas pour un bâtiment qui a un témoin dedans. L'éditeur prend la couleur dans la matière que la carte énonce pour les murs (pierre, brique, béton, parpaing, bois), ou un enduit là où elle n'en énonce pas. Absent : la simple boîte.</td></tr>
      <tr><td><code>roof</code></td><td>Type <code>building</code> seulement : <code>{ shape, riseM, color?, ridge? }</code>. <code>shape</code> vaut <code>"flat"</code> (la boîte), <code>"gable"</code> (deux pentes jusqu'à un faîte le long du grand côté, ou de la profondeur avec <code>ridge: "depth"</code>) ou <code>"hip"</code> (quatre pentes) ; <code>riseM</code> est la hauteur du faîte au-dessus de l'égout, donc les murs font <code>sizeM.heightM</code> moins cela ; <code>color</code> est le toit vu d'en haut, <code>"#rrggbb"</code>. L'éditeur les lit dans le laser et la photo aérienne du relevé. Absent : toit plat de la couleur des murs.</td></tr>
      <tr><td><code>origin</code></td><td>Le relevé dont cet objet a été tiré, par l'id de son fournisseur (<code>"ign-lidar-topo"</code>), quand l'éditeur l'a pris du relevé du lieu et que l'auteur ne l'a pas placé à la main : un arbre, un bâtiment, un pont ou une portée de ligne. Choisir un autre relevé, ou aucun, ou un autre lieu, remplace ou retire ce qui porte une <code>origin</code>, et jamais ce qui n'en porte pas</td></tr>
      <tr><td><code>surveyedOn</code></td><td>Le jour (<code>AAAA-MM-JJ</code>) du relevé le plus récent dont cet objet est tiré, quand il vient d'un relevé (voir <code>origin</code>) : l'éditeur avertit quand il est postérieur à l'observation.</td></tr>
      <tr><td><code>lit</code>, <code>litKeyframes</code></td><td>Si la lampe d'un lampadaire ou les phares d'un véhicule sont allumés. <code>litKeyframes</code> est <code>[{ t, lit }]</code>, trié par <code>t</code>, pour un éclairage allumé ou éteint pendant l'enregistrement ; sans lui, <code>lit</code> vaut pour toute la durée. Ignoré pour un bâtiment, un arbre ou un témoin</td></tr>
      <tr><td><code>headlights</code>, <code>headlightKeyframes</code></td><td>Comment les feux d'un véhicule sont réglés, car tout le monde ne les met pas, ni comme il faut : <code>off</code>, <code>position</code> (les feux de position, qui montrent le véhicule et n'éclairent rien), <code>dipped</code> (les feux de croisement), <code>main</code> (les feux de route : loin, étroits, éblouissants) ou <code>fog</code> (les antibrouillards : bas et larges). Un faisceau éclaire la route, les bas-côtés, les arbres et les murs devant le véhicule, quelle que soit la façon dont il est dessiné. <code>headlightKeyframes</code> est <code>[{ t, mode }]</code>, trié par <code>t</code>, pour un réglage qui change pendant l'enregistrement. Sans l'un ni l'autre, <code>lit</code> le dit : allumé, ce sont les feux de croisement. Ignoré pour tout autre qu'un véhicule. Seuls quatre véhicules (celui du témoin, puis les plus proches du décor) ont un vrai faisceau. Les phares du témoin projettent des ombres (un talus, un poteau ou une pile de pont retient la lumière de ce qui est derrière), et le faisceau se voit dans l'air en proportion de ce que l'air en diffuse : une trace discrète par air clair, un cône de lumière dans le brouillard</td></tr>
      <tr><td><code>observerSide</code>, <code>observerFacing</code>, <code>observerKeyframes</code>, <code>occupiedFloor</code></td><td>Le témoin à l'intérieur de l'objet, pour un <code>building</code> ou un véhicule (un seul objet à la fois le contient). <code>observerSide</code> dit où il est : <code>front</code>, <code>behind</code>, <code>left</code>, <code>right</code>, <code>front-left</code>, <code>front-right</code>, <code>behind-left</code> ou <code>behind-right</code>, l'occupant d'un véhicule étant à l'une de ses quatre portières. <code>observerFacing</code> est la vitre par laquelle il regarde quand ce n'est pas celle de sa place : un conducteur est assis en <code>front-left</code> et regarde par le pare-brise, <code>front</code>. <code>observerKeyframes</code>, <code>[{ t, side, facing }]</code>, dit où il est assis au fil du temps, chacune tenue jusqu'à la suivante, et une image clé sans <code>side</code> veut dire dehors à partir de là, comme un conducteur qui descend. <code>occupiedFloor</code> est l'étage d'un bâtiment où il se trouve, de 0 (rez-de-chaussée) à <code>floors</code></td></tr>
      <tr><td><code>modelParameters</code></td><td>Les réglages du modèle sous lequel l'objet est dessiné, par la clé sous laquelle l'entrée du catalogue publie chacun : <code>{ "costumeColor": "#5a6b3a" }</code> pour les vêtements d'une personne, <code>foliageColor</code> pour un arbre, <code>hullColor</code> pour un engin, <code>gearUp</code> pour un avion de ligne en vol. Un modèle apporte les siens (l'éditeur dessine un champ pour chacun) ; un objet dessiné comme une forme intégrée n'en a pas, il est peint par <code>color</code></td></tr>
      <tr><td><code>sightingUrl</code></td><td>Pour un <code>observer</code> : l'adresse de l'enregistrement propre à ce témoin, quand elle est connue, afin que le menu de la scène puisse proposer de voir son témoignage</td></tr>
    </table>
    </div>

    <h2>Événements du ciel</h2>
    <p>Ce qui s'est passé dans le ciel pendant l'enregistrement, en tant que faits : un tir laser, un lancement de fusée, une rentrée atmosphérique. Chacun a eu lieu que quelqu'un l'ait vu ou non : ce n'est donc ni la lecture du compte rendu, ni le décor, qui dure plus longtemps que l'observation (une maison, un arbre). Ils sont déclarés sous <code>skyEvents</code>, au premier niveau de l'enregistrement ; un enregistrement qui les mettait dans son <code>interpretation</code>, comme le faisaient les versions précédentes, est encore lu. À côté d'eux, la scène met ce que les sources savent de cette date et de ce lieu : les météores des essaims et le fond sporadique, les bolides enregistrés par un réseau de caméras, les rentrées connues, les satellites suivis, les avions d'un relevé du trafic aérien. Ce que dit l'enregistrement s'y ajoute, sans jamais les remplacer. <code>skySources: false</code>, au premier niveau de l'enregistrement, les écarte : un ciel saisi à la main, qui ne contient que ce que dit l'enregistrement (ses événements, et les aéronefs de son décor).</p>
    <pre data-json=""><code>{
  "skyEvents": {
    "beams": [{
      "id": "meudon-paris",
      "path": [
        { "lat": 48.805055, "lng": 2.231171, "altitudeM": 172.5 },
        { "lat": 48.83632, "lng": 2.33702, "altitudeM": 88 }
      ],
      "wavelengthNm": 532,
      "powerW": 10
    }]
  }
}</code></pre>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Signification</th></tr>
      <tr><td><code>auroras</code></td><td>Les aurores de la nuit : un ovale de lumière émise par la haute atmosphère autour du pôle magnétique, de 90 à 900 km d'altitude, que la scène parcourt le long de chaque ligne de visée. <code>kp</code> dit le degré d'agitation du champ (de 0 à 9, ou au-delà de 9 l'indice Hp du GFZ, sans plafond), et <code>activity</code> son évolution, <code>{ t, kp }</code> à des instants de l'enregistrement reliés linéairement ; 3 si ni l'un ni l'autre n'est donné. En découlent le bord de l'ovale côté équateur à minuit magnétique (66,5° de latitude d'apex du champ réel à 0, environ deux degrés plus près de l'équateur par cran), sa largeur, une lueur verte diffuse, ses arcs et leur éclat, et le rouge haut d'un orage ; <code>edgeLatDeg</code>, <code>arcs</code> (0 pour la lueur seule), <code>arcKR</code> (kilorayleighs de vert en regardant à travers la hauteur d'un arc : 1 l'éclat de la Voie lactée, 1 000 éclaire le sol comme la pleine Lune) et <code>redKR</code> donnent chacun autrement. <code>fromT</code> et <code>untilT</code> disent quand elle est là, apparaissant et disparaissant en une minute. Elle demande la date de l'enregistrement, car la position du Soleil décide de celle de l'ovale. Un enregistrement qui n'en donne aucune reçoit celle qu'implique l'indice archivé par le GFZ (Kp depuis 1932, Hp60 depuis 1985), crédité, sauf si <code>skySources</code> vaut false.</td></tr>
      <tr><td><code>reentries</code></td><td>Les rentrées atmosphériques qui ont eu lieu, un satellite ou un étage de fusée se désagrégeant en morceaux qui brûlent. Pas des corps : une rentrée brûle entre 70 et 100 km d'altitude et se voit à des centaines de kilomètres, elle est donc placée sur la Terre et vue à travers sa courbure depuis l'endroit où se tenait le témoin. Sa <code>track</code> donne le point de tête à des instants de l'enregistrement, <code>{ t, lat, lng, altitudeKm }</code>, reliés par des grands cercles ; chacun de ses <code>fragments</code> suit le même chemin <code>lagS</code> secondes derrière, se voit de <code>fromT</code> jusqu'à s'éteindre à <code>untilT</code>, brille de sa <code>absoluteMagnitude</code> (à 100 km, comme pour un bolide) ramenée à sa distance réelle, de sa couleur <code>color</code>, avec une traînée des <code>trainS</code> dernières secondes de son chemin (4 en son absence : la traînée d'une rentrée est longue). Chaque morceau se désagrège comme le font les morceaux qui brûlent (<code>sheds</code>) : un émiettement lent en fragments faibles, chacun avec sa strie, qui prennent du retard, s'écartent et descendent en un éventail étroit, et une salve d'une trentaine de fragments à chaque pic de sa <code>lightCurve</code>, chaque pic marquant une rupture (Zander &amp; Löhle, <em>CEAS Space Journal</em> 2025). <code>sheds</code> peut aussi décrire ce détachement par une liste de phases, <code>{ fromT, untilT, perS, lifeS, magnitudeDrop, dropBack, spreadKmS, sinkKmS, trainS }</code> ; une liste vide décrit un morceau qui ne perd aucun fragment. Un pic plus brillant que la magnitude −12 sous 50 km s'entend comme une détonation, après le temps que met le son à parcourir la distance (Tcheliabinsk : deux minutes et demie). Sa lumière est la sienne : elle se voit que le Soleil l'atteigne ou non. <code>type</code> dit ce qui est entré, et avec lui sa nature : <code>meteor</code> (météore) ou <code>fireball</code> (bolide), naturels, <code>satellite</code>, <code>rocket-stage</code> (étage de fusée) ou <code>capsule</code>, mis en orbite, ou un type qu'ajoute un module (le point d'extension <code>reentryTypes</code>) ; inconnu en son absence, ce que laisse souvent en question un compte rendu. Il ne change rien à ce qui est dessiné, qui découle du chemin et des morceaux. <code>seen</code> dit où le témoin l'a vue, <code>{ fromAzimuthDeg, fromAltitudeDeg, toAzimuthDeg, toAltitudeDeg, durationS }</code> : l'éditeur en déduit son chemin, aux altitudes des premier et dernier points du chemin, et le garde comme ce qui a été dit. <code>object</code> nomme ce qui est retombé (<code>name</code>, <code>cosparId</code>, <code>norad</code>). Rien n'est propagé depuis des éléments orbitaux, faux de plusieurs minutes sur la dernière orbite : le chemin est ce que les sources établissent, avec sa provenance</td></tr>
      <tr><td><code>launches</code></td><td>Les lancements de fusée qui ont eu lieu, éclairés par un Soleil couché pour le sol mais pas pour le panache, la « méduse spatiale ». Placés sur la Terre comme une rentrée : leur <code>track</code> donne l'étage à des instants de l'enregistrement, <code>{ t, lat, lng, altitudeKm }</code> (elle peut commencer avant l'enregistrement), et <code>burnFromT</code> et <code>burnUntilT</code> les secondes où le moteur a brûlé. Le panache est une file de bouffées lâchées le long de ce chemin, chacune s'étalant avec l'âge ; ce qui se voit de chacune est la lumière du Soleil qu'elle diffuse vers le témoin. L'ombre de la Terre (où le Soleil éclaire ou non à la hauteur de la bouffée, et combien d'air sa lumière a frôlé, ce qui la rougit ou la bleuit), l'angle de diffusion et l'étalement sont calculés depuis le vrai Soleil à la vraie date : rien n'en est déclaré. Un <code>plume</code> facultatif remplace les valeurs par défaut : <code>exhaustKgPerS</code> (273, un Merlin Vacuum), <code>condensedShare</code> (0,065, le seul nombre que personne n'a mesuré), <code>particleRadiusUm</code>, <code>expansionKmPerS</code>, <code>initialRadiusKm</code>, <code>lifetimeS</code>, et pour la collerette (le gaz fraîchement éjecté, large et vite disparu, à côté de la traînée étroite qui reste) <code>collarShare</code> (0,85), <code>collarExpansionKmPerS</code> (2,5), <code>collarLifetimeS</code> (20). <code>vehicle</code> nomme ce qui a volé et, dans <code>engine</code>, le moteur dont c'est l'échappement : <code>thrustKN</code> et <code>specificImpulseS</code> (dont se déduisent le débit d'échappement et sa vitesse, donc la largeur de la collerette) et <code>propellant</code> (<code>rp1-lox</code>, <code>methane-lox</code>, <code>hydrogen-lox</code>, <code>hypergolic</code> ou <code>solid</code>, qui dit quelle part devient des particules et de quelle taille). Ce que dit <code>plume</code> l'emporte sur ce que dit le moteur. Le panache a besoin de la date de l'enregistrement : sans elle il n'y a pas de Soleil pour l'éclairer. <code>vehicle.mission</code> nomme la mission qu'il effectuait (<code>"Starlink Group 10-49"</code>). Chaque bouffée vole seule une fois lâchée, à la vitesse de l'étage plus celle à laquelle elle a été lancée, tirée par la Terre et freinée par l'air seulement là où il est assez dense pour s'écouler autour d'elle (sous 200 à 300 km). Le panache est donc une vraie forme dans l'espace, la même vue de tous les côtés : une traînée vue dans l'axe est un disque, une spirale vue par la tranche une ligne. Sa couleur dépend de la taille de ses particules : la glace grossière diffuse du blanc, la glace plus fine que la longueur d'onde diffuse du bleu. <code>jets</code> liste ce que l'étage lâche d'autre, chacun <code>{ kind, fromT, untilT, angleDeg, azimuthDeg, spinPeriodS, speedKmPerS, massKgPerS, condensedShare, particleRadiusUm, expansionKmPerS, initialRadiusKm, lifetimeS }</code> : <code>kind</code> vaut <code>burn</code> (un autre allumage du moteur, avec les valeurs du panache ; un freinage de désorbitation est <code>angleDeg</code> 180, l'échappement partant devant l'étage) ou <code>vent</code> (des ergols vidangés des réservoirs, plus lents, plus fins et plus froids : 0,7 km/s, 20 kg/s, la moitié gelant, par défaut) ; <code>angleDeg</code> depuis l'arrière du mouvement (0) jusqu'au côté (90) ; <code>azimuthDeg</code> le côté par lequel il part autour du mouvement (0 à l'opposé de la Terre) ; <code>spinPeriodS</code> la période de rotation de l'étage autour de sa direction de vol : elle fait tourner le jet avec lui, et les ergols vidangés dessinent alors une spirale. Quand il y a des jets, l'allumage de l'ascension n'est dessiné que si <code>burnFromT</code> ou <code>burnUntilT</code> est donné.</td></tr>
      <tr><td><code>beams</code></td><td>Les faisceaux de lumière envoyés dans l'air depuis le sol, un tir laser ou un projecteur. Chacun a un <code>path</code> d'au moins deux points <code>{ lat, lng, altitudeM }</code> (altitudes au-dessus de la mer) : où il quitte l'émetteur, où un miroir le renvoie s'il y en a un, et où il finit. Entre deux points, le faisceau est une droite dans l'espace : il ne suit pas le sol, qui s'abaisse sous lui. <code>wavelengthNm</code> est sa couleur (532 pour un laser vert), <code>powerW</code> sa puissance optique moyenne, <code>divergenceMrad</code> la vitesse à laquelle il s'élargit (0,1 par défaut) et <code>apertureM</code> sa largeur au départ (0,01 m par défaut) ; <code>fromT</code> et <code>untilT</code> disent quand il est allumé. Rien de sa luminosité n'est déclaré : ce qui se voit de chaque mètre est ce que l'air à cet endroit (molécules et brume, à sa longueur d'onde) diffuse vers l'œil de la puissance qui lui reste, selon l'angle dont la lumière doit être déviée pour atteindre l'œil ; il est donc bien plus vif vu en remontant vers lui qu'en le regardant s'éloigner. Il est caché par ce qui se trouve devant lui et s'arrête où il rencontre le sol.</td></tr>
    </table>
    </div>

    <h2>La météo et ses nuages</h2>
    <p>Une image clé <code>weather</code> indique l'état du ciel à un instant de l'horloge de
      l'enregistrement ; entre deux images clés, chaque nombre est interpolé, le type de précipitation et
      l'orage sont maintenus. Il porte :</p>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Sens</th></tr>
      <tr><td><code>cloudLayers</code></td><td>Les nuages, en liste de couches — voir plus bas. <strong>Absent</strong> : les nuages sont décrits par les anciens champs des lignes suivantes, convertis en une couche d'eau et un voile de cirrus ; <strong>une liste vide</strong> : un ciel dégagé que quelqu'un a regardé</td></tr>
      <tr><td><code>cloudCover</code>, <code>lowerCloudCover</code>, <code>highCloudCover</code></td><td>Fractions de ciel (0–1) : le total, les couches d'eau seules, le voile glacé seul. Écrits par les enregistrements antérieurs aux couches, et toujours tenus à jour par l'éditeur comme résumé de celles-ci</td></tr>
      <tr><td><code>cloudBaseM</code>, <code>cloudDarkness</code></td><td>Champs de la même époque : la base unique des nuages, en mètres au-dessus du sol de référence, et leur teinte unique (0 blanc, 1 très sombre)</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>0–1, la régularité de la chute des cristaux de glace — ce qui fait d'un anneau nu des parhélies, des arcs et un pilier. Aucun relevé ne le mesure ; une couche de cirrus a sa propre valeur</td></tr>
      <tr><td><code>rareIceCrystals</code></td><td>0–1, la part des cristaux d'un voile de cirrus qui sont de types rares : colonnes à bouts pyramidaux (les halos à rayon impair, à 9°, 20° et 35°) et plaquettes libres de tourner autour d'un axe horizontal (les arcs de Lowitz). Absent signifie 5 %, un voile ordinaire. Comme l'alignement, aucun relevé ne les compte : il est déclaré. La simulation qui en découle a été vérifiée par comparaison avec <a href="https://atoptics.co.uk">Atmospheric Optics</a></td></tr>
      <tr><td><code>relativeHumidity</code></td><td>0–1, près du sol. Elle décide de la blancheur du ciel clair : la brume gonfle d'eau à mesure que l'air approche de la saturation. Un relevé consulté la porte (tirée de la température et du point de rosée d'ERA5) ; absente, une brume ordinaire</td></tr>
      <tr><td><code>visibilityKm</code></td><td>La visibilité météorologique près du sol, en kilomètres, telle qu'un bulletin la donne. C'est la brume elle-même : déclarée, elle décide de sa quantité, pour le lointain comme pour le ciel, et l'humidité n'est plus lue pour cela Au-delà de 30 km, c'est aussi la distance jusqu'à laquelle le relief est dessiné (150 km au plus), en s'abaissant avec la courbure de la Terre : une montagne qu'un air limpide montre au loin est là.</td></tr>
      <tr><td><code>precipitationType</code>, <code>precipitationIntensity</code></td><td>none/rain/snow/hail, et 0–1. Indiquée à une image clé, elle est jouée comme tombe une vraie précipitation : une averse commence par ses premières gouttes à l'image clé qui la déclenche, et n'atteint l'intensité indiquée pas plus vite qu'une vraie pluie (de rien au plus fort en vingt secondes) ; elle s'arrête de même. Un changement que les images clés étalent sur plus longtemps est suivi tel quel. <code>precipitationAmount</code> (0–1, absent veut dire tout) dit quelle part de cette précipitation tombe déjà.</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>Le vent général : le cap VERS lequel il souffle, dans le sens horaire depuis le nord, et des mètres par seconde. C'est lui qui porte les nuages, depuis l'instant zéro : aller directement à un instant ou y arriver en lecture donne donc le même ciel</td></tr>
      <tr><td><code>storm</code></td><td>Éclairs et tonnerre, au bon retard</td></tr>
    </table>
    </div>
    <p>Chaque <strong>couche</strong> de <code>cloudLayers</code> est une nappe de nuages à une
      hauteur réelle, et reste la même d'une image clé à l'autre :</p>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Sens</th></tr>
      <tr><td><code>id</code></td><td>Stable d'une image clé à l'autre : c'est par lui que les couches se correspondent, jamais par leur rang dans la liste. Une couche présente à une image clé et absente à la suivante s'estompe ; les réordonner ne change rien</td></tr>
      <tr><td><code>type</code></td><td><code>cumulus</code>, <code>stratus</code>, <code>stratocumulus</code>, <code>cirrus</code> ou <code>unknown</code>. Il décide de la forme des sommets et de la finesse du voile ; un cirrus est aussi celui qui réfracte les halos. Il change d'un coup à l'image clé, il n'est pas interpolé</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>En mètres. La base est au-dessus du sol de RÉFÉRENCE de l'enregistrement, pas au-dessus d'un témoin qui grimpe ; un témoin plus haut que la base est dans la nappe ou au-dessus, et le ciel est dessiné en conséquence</td></tr>
      <tr><td><code>coverage</code></td><td>0–1, au sens propre : la fraction du ciel que cette couche couvre, quelle que soit la taille de ses nuages</td></tr>
      <tr><td><code>sizeM</code></td><td>La largeur caractéristique d'un nuage, en mètres. Indépendante de la couverture : une même fraction de ciel peut être beaucoup de petits nuages ou quelques gros</td></tr>
      <tr><td><code>density</code></td><td>0–2, l'opacité de la matière nuageuse ; 0 est transparent. Indépendante de la couverture elle aussi</td></tr>
      <tr><td><code>darkness</code></td><td>0 blanc à 1 très sombre. Absent : le <code>cloudDarkness</code> de l'image clé</td></tr>
      <tr><td><code>seed</code></td><td>Le choix du motif, parmi les innombrables que peuvent dessiner les mêmes valeurs. Absent : un motif dérivé de l'id, c'est pourquoi l'id ne doit pas changer</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>Le vent propre à cette couche, lorsqu'il diffère du vent général — c'est le cas de la couche haute d'ordinaire. Absent : le vent général</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>Pour un cirrus seulement</td></tr>
      <tr><td><code>instances</code></td><td>Les nuages individuels de cette couche — voir plus bas</td></tr>
    </table>
    </div>
    <p>Un <strong>nuage individuel</strong> dans <code>instances</code> est un nuage de sa couche que
      le fichier place exactement, parce que le récit le fait : celui derrière lequel le phénomène
      est passé, celui qui était là et nulle part ailleurs. Il est dessiné comme un nuage de sa
      couche — même texture, même seuil — et ne se distingue de ses voisins que par sa position et sa
      taille ; il est là même quand la <code>coverage</code> de la couche est nulle. Il suit le vent
      de la couche comme les autres, et il masque un phénomène devant lequel il passe.</p>
    <div class="table-scroll">
    <table>
      <tr><th>Champ</th><th>Sens</th></tr>
      <tr><td><code>id</code></td><td>Stable d'une image clé à l'autre, même règle que pour une couche</td></tr>
      <tr><td><code>eastM</code>, <code>northM</code></td><td>Où était son centre à l'instant zéro, en mètres depuis le point de départ du témoin. Le vent l'emporte de là</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Sa propre base et sa propre hauteur, en mètres — un nuage peut être plus bas ou plus haut que sa nappe</td></tr>
      <tr><td><code>widthM</code>, <code>depthM</code>, <code>rotationDeg</code></td><td>Son emprise, en mètres, et le cap vers lequel cette emprise est tournée</td></tr>
      <tr><td><code>density</code>, <code>darkness</code></td><td>Les siens ; une obscurité absente est celle de la couche</td></tr>
    </table>
    </div>
    <pre data-json="weatherTrack.keyframes"><code>{
  "weather": {
    "cloudLayers": [
      {
        "id": "low", "type": "cumulus",
        "baseM": 1500, "thicknessM": 800,
        "coverage": 0.55, "sizeM": 1400, "density": 1, "darkness": 0.15,
        "instances": [
          { "id": "the-one", "eastM": 0, "northM": 4200,
            "baseM": 1500, "thicknessM": 800,
            "widthM": 1900, "depthM": 1300, "rotationDeg": 12, "density": 1 }
        ]
      },
      { "id": "high", "type": "cirrus", "baseM": 8000, "thicknessM": 400,
        "coverage": 0.2, "sizeM": 2200, "density": 0.35, "iceCrystalAlignment": 0.65 }
    ],
    "precipitationType": "none", "precipitationIntensity": 0,
    "windDirectionDeg": 90, "windSpeed": 5, "storm": false
  }
}</code></pre>
    <p>Un enregistrement dont la météo a été <strong>relevée</strong> (il a un
      <code>weatherSource</code>) garde la réponse du relevé, pas un lien vers lui : ERA5 donne les
      bandes basse, moyenne et haute en trois couches nommées <code>record-low</code>,
      <code>record-mid</code> et <code>record-high</code>, la base basse estimée depuis l'écart entre
      température et point de rosée, les deux autres à 3 500 m et 8 000 m. Leur type est
      <code>unknown</code> (cirrus pour la haute), leur taille et leur densité sont des hypothèses de
      dessin : une réanalyse sait quelle part de chaque bande était couverte, pas à quoi les nuages
      ressemblaient. Redemandez le relevé depuis l'éditeur et les couches sont réécrites ; modifiez
      une couche à la main et l'enregistrement devient celui de l'auteur, la source retirée.</p>
`
  }

  private es(): string {
    return `
    <h2 id="everything-around-it">Los campos alrededor de lo que se vio</h2>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>observerTrack</code></td><td><code>{ keyframes: [{ t, pose }] }</code> — <code>pose</code> contiene <code>lat</code>, <code>lng</code>, <code>elevationM</code> (sobre el suelo local), <code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>, y para una cámara <code>fNumber</code> y <code>focusDistanceM</code>. Se reproduce como se mueve una persona: exactamente la pose indicada en cada fotograma clave, y entre ellos un movimiento que gana velocidad, la mantiene a través de los fotogramas clave que siguen moviéndose, y frena hasta una pausa — dos fotogramas clave con el mismo lugar, o el mismo rumbo. Una mirada empieza y acaba inmóvil; una marcha a pie o en coche ya en curso en el primer fotograma clave continúa. Detenerse y echar a andar añaden su propia sacudida, un cabeceo que se extingue en un segundo y medio, trasladado a la imagen tanto como el instrumento lo permite (apenas un ojo, del todo una cámara sostenida a mano). Y un cuerpo en reposo nunca está del todo quieto: de pie o esperando, la vista oscila unos milímetros y deriva una décima de grado, despacio, del mismo modo en el mismo instante — salvo para un testigo que el relato dice que quedó paralizado (etiqueta <code>paralysis</code>). El <code>pitchDeg</code> indicado es cómo miraba el testigo en el marco de lo que lo llevaba: mientras se desplaza, el reproductor suma cómo sube el propio vehículo (la pendiente de la carretera bajo la traza, leída del relieve, positiva al subir, o para un avión su propia subida, atenuada cuando la mirada se aparta de su camino), de modo que una cuesta eleva la vista y el chip <q>Inclinación</q> indica la suma. <code>filter</code> es lo que se sostenía delante del instrumento, un id de <code>FILTERS</code> como <code>solar-visual</code> para un eclipse. Se mantiene entre fotogramas clave, sin mezclarse (nadie lleva media gafa), y se quita declarando <code>"none"</code>. Un fotograma clave que indica <code>viewOnly: true</code> fija la vista de su solo instante (el editor lo escribe cuando la vista se gira con Alt pulsado): el giro de la cámara hacia él y desde él queda fuera de la imagen, y una exposición que lo toca se dibuja como si la cámara hubiera quedado quieta, apuntada como en el instante mostrado. Un testigo que vuela a una altitud dada la indica con <code>altitudeM</code> (metros sobre el mar): el reproductor pone entonces el ojo a esa altitud sobre el relieve que dibuja, y <code>elevationM</code> ya solo es la altura sobre el suelo con el que se escribió el archivo, contra la que se acota también el decorado de una cabina alrededor del ojo.</td></tr>
      <tr><td><code>events</code></td><td>Lo que hizo el testigo, expresado como eventos con sus parámetros en lugar de las poses que implican: <code>[{ type: "event", eventType, t, until, params }]</code>, <code>t</code> y <code>until</code> en ms de la grabación. El reproductor calcula las poses al leer la grabación, con la misma ley para todas (un giro de cabeza parte de la quietud y se asienta, la línea de un vehículo es una curva), y solo vuelve a escribir los eventos mientras nada haya cambiado esas poses; un <code>observerTrack</code> con fotogramas clave propios prevalece sobre ellos. Un parámetro lleva su procedencia como cualquier valor. Una tabla de instantes (<code>speeds</code>, <code>speedDivisors</code>, <code>heights</code>, <code>metres</code>) tiene tantas filas como el relato necesite; su valor pasa poco a poco de una fila a la siguiente, o de golpe en una fila con <code>step: true</code>. A pie: <code>look</code> (una mirada sostenida a partir de <code>t</code>, <code>headingDeg</code>, <code>pitchDeg</code>), <code>walk</code> (de <code>from</code> a <code>to</code>, dos <code>{ lat, lng }</code>, entre <code>t</code> y <code>until</code>, como camina y se detiene una persona) y <code>follow</code> (un cuerpo de la lectura, o un fenómeno que cruza el cielo, <code>target</code>, que los ojos alcanzan <code>reactionS</code> después, con <code>lagS</code> de retraso, mirado cada <code>sampleMs</code> a falta de fotogramas clave propios, mirado en cada uno de sus fotogramas clave, en el centro de lo que ve, la mirada girando entre ellos como gira una cabeza; sostenida donde lo pierde, en <code>until</code>; <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>). En vehículo: <code>drive</code> (el vehículo del testigo, un objeto del decorado nombrado por <code>vehicle</code>, sigue <code>path</code>, una lista de <code>{ lat, lng }</code>, a las velocidades <code>speeds</code> <code>[{ t, kmh }]</code>, eventualmente divididas por <code>speedDivisors</code> <code>[{ t, divisor }]</code>, situado por el único lugar por el que pasó, <code>through</code> <code>{ t, lat, lng }</code>; el <code>eye</code> del conductor es <code>{ x, y, z }</code> en el modelo del vehículo), <code>lookAhead</code> (mira la carretera y mantiene el objetivo <code>target</code> <code>{ lat, lng }</code> a unos <code>keepDeg</code>, y le echa vistazos de <code>glanceS</code> seguidos de <code>roadS</code> a la carretera cuando está a más de <code>glanceBeyondDeg</code>; <code>pitchShare</code> dice hasta qué parte de su altura alza la vista), <code>lean</code> (hacia el retrovisor: el ojo se desplaza <code>offsetM</code> en <code>turnS</code>, durante <code>holdS</code>) y <code>watch</code> (en el retrovisor <code>mirror</code>, un punto del modelo del vehículo: <code>firstS</code>, luego <code>mirrorS</code> entre miradas a otra parte, un vistazo directo de <code>glanceS</code> una vez de cada dos hasta <code>glancesUntil</code>, la carretera durante <code>roadS</code> si no). Cada evento dice de quién es en <code>who</code>, mediante un id de la grabación que nada más tiene: el del testigo (<code>observer.id</code>, o <code>"observer"</code> para un testigo sin id; un evento que no dice ninguno es suyo), el de una forma o un grupo de formas, de un cuerpo, de un objeto del decorado. El editor no guarda una grabación con un evento sobre nada, o con dos cosas del mismo id. Un evento de un objeto del decorado: <code>fly</code> (un avión a lo largo de una línea recta que lleva a <code>from</code> <code>{ lat, lng }</code>, con rumbo <code>headingDeg</code>, a las velocidades <code>speeds</code>, a <code>at.metresBefore</code> de ese lugar en el instante <code>at.t</code>, a <code>heights</code> <code>[{ t, altitudeM }]</code> por encima del ojo del testigo). Una de sus luces (<code>id/luz</code>, <code>f-hobs/landing-nose</code>), o un grupo de ellas que nombran los <code>groups</code> del objeto (<code>f-hobs/strobes</code>): <code>light</code> (a <code>intensity</code> desde el inicio del evento, 0 apagada, parpadeando como antes, y de vuelta a lo que era a su final cuando declara uno) y <code>blink</code> (encendida durante <code>onS</code>, apagada durante <code>offS</code>, a <code>intensity</code> o a lo que era, hasta el final del evento, luego como antes): un faro de aterrizaje apagado, destellos encendidos, una baliza giratoria, el balizamiento de lo alto de un edificio. Los del fenómeno (<code>who</code> la forma con que se dibuja, o el grupo de sus formas) dan las formas del relato, tal como lo describió el testigo: <code>stand</code> (en el lugar <code>place</code> que declaró, <code>{ lat, lng }</code>, sus <code>metres</code> <code>[{ t, widthM, heightM }]</code> su ancho y su altura sobre el ojo, de los que se siguen en cada instante su dirección y su tamaño en su cielo), <code>appearance</code> (su aspecto a partir de <code>t</code>, sus <code>parts</code>: formas situadas y dimensionadas en partes de su ancho aparente, <code>sourceId</code>, <code>kind</code>, <code>points</code>, <code>color</code>, <code>brightness</code>, <code>halo</code>, <code>widthShare</code>, <code>heightShare</code>, <code>alongShare</code>, <code>upShare</code>; una parte que otro aspecto tiene y este no, no se ve), <code>blink</code> (las formas de las que es, un grupo de las del fenómeno o una de ellas, encendidas durante <code>onS</code>, apagadas durante <code>offS</code>, tomando <code>off</code> mientras están apagadas) y <code>vanish</code> (ya no se ve). O, sin lugar, cruzando el cielo, un relato solo de direcciones: <code>travel</code> (<code>from</code> una dirección <code>{ azimuthDeg, altitudeDeg }</code> <code>towards</code> otra, a lo largo del gran círculo que las une, a las velocidades <code>speeds</code> <code>[{ t, degPerS }]</code>, suavemente entre dos; <code>sizeDeg</code> de ancho en el cenit, más pequeño como el seno de su altura cuando <code>sizeBy</code> es <code>"altitude"</code>; sus partes dispuestas a lo largo de su camino en la imagen del testigo, <code>alongShare</code> delante o detrás, <code>upShare</code> a su izquierda, giradas con él), <code>turn</code> (de <code>byDeg</code> hacia su lado <code>side</code>, <code>"left"</code> o <code>"right"</code>, suavemente; el otro lado en el cielo cuando <code>seenFrom</code> es <code>"craft"</code>, como lo dice un piloto), <code>roll</code> (inclinado hasta <code>toDeg</code>, y de vuelta horizontal con <code>andBack</code>, más estrecho a lo ancho de su camino según el coseno), <code>vibrate</code> (de un lado a otro <code>hz</code> veces por segundo, en <code>amplitudeShare</code> de su tamaño, desde nada en <code>riseS</code>, luego cada vez menos hasta el final del evento) y <code>spiral</code> (<code>turns</code> vueltas de un círculo junto a su camino, <code>clockwise</code> o no, de <code>radiusDeg</code> una vez abierto, reducido en <code>shrink</code> al final, rodando <code>rollDeg</code>); <a href="/demo-data/observer-saint-lo.json"><code>observer-saint-lo.json</code></a>. Los de un cuerpo de la lectura (<code>who</code> su id; o, sobre una parte de su modelo, un nodo o un hueso, <code>id/parte</code>: <code>craft/legs</code>, <code>etre-2/head</code>, que <code>spin</code> y <code>turn</code> hacen girar sola alrededor de su propio eje vertical, en sentido horario vista desde arriba, el resto del cuerpo tal como está; una luz, por su nombre en el modelo, <code>engin/front-red</code>, o un grupo de sus partes que nombran los <code>groups</code> del cuerpo, <code>engin/rear</code>; el archivo del modelo dice qué partes tiene) se añaden a los fotogramas clave que declara: <code>motion</code> (un movimiento de su modelo reproducido una vez, <code>motion</code> hasta <code>to</code>, el tubo central que se recoge), <code>spin</code> (uno que gira sin parar, <code>turnsPerS</code>, las patas), <code>rise</code> (<code>distanceM</code> a lo largo de una recta a <code>angleDeg</code> de la vertical, 0 recto hacia arriba, hacia <code>headingDeg</code>, desde parado, frenando hasta detenerse o, <code>stops: false</code>, cada vez más rápido al irse), <code>turn</code> (girarse hacia <code>headingDeg</code>), <code>ride</code> (llevado por el cuerpo <code>in</code>, <code>aboveM</code> más arriba), <code>light</code> (una luz, o un grupo de ellas, encendida a <code>cdM2</code> desde el inicio del evento, 0 apagada, y encendida de nuevo como estaba a su final cuando declara uno) y <code>blink</code> (una luz que parpadea, encendida durante <code>onS</code>, apagada durante <code>offS</code>, a <code>cdM2</code> encendida o a lo que estaba antes, hasta el final del evento, luego como antes; de golpe, nunca en fundido: los destellos de un avión, una baliza giratoria, la luz de lo alto de una torre) y <code>vanish</code>; una postura también es un movimiento del modelo (<code>motion</code> sobre <code>crouch</code>, que lleva una figura exportada con sus posturas: 0 de pie, 1 agachada); la nave y los seres de <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>. <a href="/demo-data/observer-silly-le-long.json"><code>observer-silly-le-long.json</code></a> expresa así a su testigo, su avión y su fenómeno</td></tr>
      <tr><td><code>sampleMs</code></td><td>Con qué frecuencia se toma un fotograma clave, en ms: por el grabador del editor cuando se mueve una forma a mano, y donde los eventos se desarrollan en valores (las formas del relato, la mirada que las sigue, un cuerpo que se eleva), todos al mismo paso, para que lo que se dibuja y la mirada para la que se dibuja nunca se desfasen. De lo que eso da, los fotogramas clave que dicen lo mismo solo conservan el primero y el último: el reproductor dibuja lo mismo entre ellos. Ausente, cada uno conserva el suyo: 25 ms para un fenómeno que cruza el cielo y la mirada que lo sigue, 2 s para uno inmóvil, 250 ms para un cuerpo que se eleva</td></tr>
      <tr><td><code>weatherTrack</code></td><td><code>{ keyframes: [{ t, weather }] }</code> — las condiciones del cielo a lo largo de la grabación: precipitación, viento, tormenta, y las nubes como capas con alturas reales, cada una capaz de contener nubes individuales situadas en metros. Todos los campos de un <code>weather</code> están en la sección siguiente</td></tr>
      <tr><td><code>weatherSource</code></td><td><code>{ id, name, url }</code> del registro del que se consultó el tiempo. Su presencia significa que la grabación se reproduce exactamente como se compuso y no se vuelve a consultar nunca. Si falta, es el propio relato del testigo</td></tr>
      <tr><td><code>lightPollution</code></td><td>El brillo del cielo nocturno del lugar, ciudades incluidas: el cenit de una noche sin Luna en magnitudes por segundo de arco cuadrado, tal como lo lee un Sky Quality Meter o lo da el <a href="https://doi.org/10.1126/sciadv.1600377">atlas mundial del brillo artificial del cielo nocturno</a> (su cifra «SQM», Falchi et al. 2016, que <a href="https://www.lightpollutionmap.info">lightpollutionmap.info</a> muestra para cualquier lugar). <code>22</code> es un cielo natural, un suburbio ronda <code>19</code>, el centro de una ciudad <code>17</code>. Si falta, un cielo natural. La parte de las ciudades, lo que queda al quitar los 22 naturales, se suma al cielo como luz: más intensa hacia el horizonte, donde el aire bajo devuelve más, y dibujada con el blanco cálido de una lámpara de 3000 K. Ahoga la Vía Láctea y la luz zodiacal, y quita estrellas, por la diferencia en la estrella más débil que un ojo distingue (Crumey 2014): unas dos magnitudes a <code>19</code>. La Luna ahora hace lo mismo. <code>"derived"</code> cuando se consulta en el atlas, <code>"stated"</code> cuando el testigo lo midió. El editor lo rellena a partir del atlas para una observación de 2015 en adelante, como <code>"derived"</code> con el atlas nombrado, y nunca reemplaza una cifra escrita a mano; antes de 2015 no consulta nada, porque el cielo era más oscuro que el del atlas</td></tr>
      <tr><td><code>around</code></td><td>Lo que hacía ruido alrededor del observador, contra lo que se oye un avión como contra el viento y la lluvia: <code>cars</code> (coches), <code>trucks</code> (camiones y autobuses), <code>people</code> (personas) y cuántas de ellas <code>talking</code> (hablaban), presentes a la vez en un radio de <code>withinM</code> metros (200 si falta), y <code>roads</code> (carreteras), cada una <code>{ distanceM, vehiclesPerMinute, trucksPerMinute, speedKmh }</code> (50 km/h si falta), pues un testigo puede decir lo uno o lo otro. Lo que se oye donde está el observador se calcula con la potencia sonora de los vehículos de <a href="https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:32021L1226">CNOSSOS-EU</a> (un coche a 50 km/h hace 73 dB(A) a 7,5 m) y los 55 dB(A) a 1 m de una conversación (Pearsons et al. 1977): lo contado como repartido en su disco, una carretera como una línea. Se suma al ruido del tiempo: el tráfico de una ciudad enmascara aviones que un campo tranquilo deja oír. Nada de ello se reproduce aún: el ruido de una carretera reproducido como fondo era un soplido sobre los aviones; se oirá cuando la escena tenga sus propios vehículos. Cada cifra tiene su procedencia, en <code>around.cars</code> o <code>around.roads.0.distanceM</code>. Si falta: un lugar tranquilo</td></tr>
      <tr><td><code>observerMap</code></td><td>Si el mapa de dónde estaba el testigo empieza abierto cuando se reproduce o edita la grabación: <code>true</code> o <code>false</code>. Si falta, decide el reproductor: abierto para un testigo que se desplazó, cerrado para uno que se quedó en su sitio. Una página que integra el reproductor tiene la última palabra (su atributo <code>show-observer-map</code>). El editor lo escribe cuando se abre o se cierra el mapa en él, para que un lector vea lo que el autor dejó</td></tr>
      <tr><td><code>snapshots</code></td><td>Dónde se guardan, en archivos junto a la grabación (anexos), los datos que la escena pediría si no a terceros en cada reproducción, para que una grabación terminada se reproduzca igual dentro de diez años sin pedir nada a nadie: <code>relief</code> (la altura del suelo, tal como la fuente de altitud la dio para cada parcela de terreno que construye la escena, un zip), <code>imagery</code> (la foto del suelo, como las teselas que sirvió la fuente de imágenes, un zip), <code>roads</code>, <code>water</code>, <code>railways</code> (carreteras, agua y vías de cada parcela, en JSON), <code>upperAir</code> (el aire a la altura de los aviones, en JSON) y <code>map</code> (la foto bajo el mapa del testigo, como las teselas que sirvió la fuente de imágenes para el terreno al que se ajusta el mapa, un zip: un mapa tomado como instantánea muestra esa foto y no pide ninguna otra, ampliada al acercarse, vacía más allá al alejarse). Cada uno es <code>{ src, takenOn, attribution }</code>, con <code>src</code> leído respecto a la dirección de la grabación, o una URL <code>data:</code> para un anexo guardado dentro de la propia grabación. Un grupo leído de su anexo no pide nada a nadie; uno sin anexo se pide en directo, como todo antes. <code>"live": true</code> en un grupo lo pide en directo en cada reproducción y nunca toma una instantánea de él (lo que dice elegir su fuente en directo en lugar de <em>Archivo</em>), y en el propio <code>snapshots</code> todos los grupos; <code>"refresh": true</code> en un grupo lo pide en directo una vez, y el editor lo vuelve a tomar al guardar. El editor toma lo que falta al guardar, y guarda la grabación y sus anexos en un único zip que descomprimir donde se publica. <code>weather</code>, <code>place</code>, <code>lightPollution</code> y <code>decor</code> dicen que el tiempo (<code>weatherTrack</code>, <code>weatherSource</code>), el nombre del lugar, la cifra del cielo nocturno y el decorado se leen del archivo en lugar de volver a pedirse (al registro meteorológico cuando cambian la fecha o el lugar, al geocodificador, al atlas y al levantamiento cuando el testigo se mueve): <code>{}</code> si están dentro de la grabación, <code>{ src }</code> para un anexo con sus claves, que los reproductores devuelven a la grabación al cargarla. Si faltan, están dentro de la grabación y el editor los vuelve a pedir. El huso horario no está aquí: está escrito en la propia grabación</td></tr>
      <tr><td><code>modules</code></td><td>Los módulos que la grabación necesita para dibujarse tal como se hizo (un catálogo del que vienen sus modelos), por la dirección del manifiesto de cada uno, relativa a la grabación o absoluta: véase <a href="/docs/modules/">módulos</a>. Un lector recibe lo que declara cada manifiesto, nunca su script salvo que haya añadido ese módulo él mismo. Ausente, no necesita ninguno</td></tr>
      <tr><td><code>soundTrack</code></td><td><code>{ keyframes: [{ t, sound }] }</code> — <code>kind</code> (none/hum/whistle/rumble/crackle), <code>volume</code>, <code>pitchHz</code>, y un <code>src</code> opcional de una grabación real. <code>volume</code> y <code>pitchHz</code> se deslizan entre fotogramas clave, <code>kind</code> y <code>src</code> cambian en el fotograma clave. Un <code>src</code> en otro sitio debe servirse a cualquier origen (CORS)</td></tr>
      <tr><td><code>references</code></td><td>Imágenes del lugar superpuestas a la escena: <code>src</code> (una dirección, o una URL <code>data:</code> para una imagen añadida desde un disco), <code>kind</code> (photo/panorama/video), <code>registration</code> (<code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>), <code>opacity</code>, <code>credit</code>/<code>creditUrl</code>, <code>t</code> y <code>drawing</code> opcionales, <code>from</code> (<code>{ lat, lng }</code>, desde dónde se tomó: el reproductor la desvanece a medida que el testigo se aleja de ese punto; si falta, nunca se desvanece), y los <code>landmarks</code> con los que se alineó (<code>id</code>, <code>label</code>, <code>picture</code> como <code>{ u, v }</code> desde la esquina superior izquierda, <code>scene</code> como <code>{ azimuthDeg, altitudeDeg }</code>). Un <code>video</code> indica además <code>t</code>, donde empieza su tramo en la línea de tiempo, <code>video</code> (<code>fromS</code>, <code>toS</code>, <code>rate</code>: qué parte del archivo, a qué velocidad) y <code>registrationTrack</code>, adónde apuntaba su cámara en cada instante ajustado.</td></tr>
      <tr><td><code>traces</code></td><td>Lo que un investigador dibujó sobre el lugar, importado de su archivo de Google Earth (KML, KMZ) o del GeoJSON de su SIG y mostrado sobre la escena como suyo, nunca como parte de la reconstrucción: <code>[{ id, title, kind, points, altitude, color, source }]</code>, siendo <code>kind</code> <code>point</code>, <code>line</code> o <code>polygon</code>, <code>points</code> los vértices como <code>[{ lat, lng, altM }]</code> tal como los tenía el archivo, <code>altitude</code> cómo se lee <code>altM</code> (<code>ground</code>, por defecto, <code>relative</code> al suelo bajo cada punto, o <code>absolute</code> sobre el nivel del mar), <code>color</code> un <code>#rrggbb</code> y <code>source</code> de quién es</td></tr>
      <tr><td><code>instrument</code>, <code>exposureSeconds</code></td><td>A través de qué se observó, y cuánto tiempo estuvo abierto el obturador. Si falta, el ojo desnudo. <code>instrument</code> es uno de <code>eye</code>, <code>rectilinear-lens</code> (una cámara de marca desconocida), <code>roamer-1-120</code>, <code>instamatic-126</code>, <code>slr-35mm-50</code>, <code>slr-35mm-zoom</code>, <code>phone-landscape</code>, <code>phone-portrait</code>, o una réflex digital (<code>eos-5d-iii</code>, <code>nikon-d7000</code>… los sensores del catálogo de Stellarium), unos prismáticos (<code>binoculars-nikon-10x42-edg</code>…) o un telescopio (<code>telescope-celestron-c8</code>…); <code>exposureSeconds</code> es un valor para toda la grabación, limitado al rango propio de ese aparato; un aparato que registra una imagen (una cámara, un teléfono) pone sobre cada luz los reflejos fantasma de su objetivo, como hacen el vidrio y el sensor: una copia más débil y desenfocada sobre la recta que pasa por el centro de la imagen, simétrica respecto a él para el reflejo principal de un teléfono, el disco rojo opuesto a un semáforo. Un teléfono se expone solo según lo que ve, hasta ISO 3200: una noche que filma sigue oscura alrededor de sus lámparas</td></tr>
      <tr><td><code>lens</code></td><td>A través de qué se tomó la imagen además del objetivo, y qué había sobre ese cristal, para un aparato que registra una: <code>glass</code> (<code>filter</code>, <code>window</code> o <code>windscreen</code>: un filtro añade un reflejo simétrico respecto al centro, un cristal un doble más débil de cada luz justo al lado, más lejos para un parabrisas inclinado), <code>drops</code>, <code>condensation</code> y <code>dirt</code> (de 0 a 1, cada uno con un halo alrededor de cada luz, que pierde lo que el halo toma) y <code>sheltered</code>. Sin <code>drops</code>, las gotas siguen la lluvia o la nieve que cae en cada instante, salvo si <code>sheltered</code> es verdadero: caen nuevas tanto más a menudo cuanto más de frente golpea la lluvia el cristal (un objetivo levantado, un cristal de cara al viento, un parabrisas inclinado reciben más), se funden con sus vecinas; las pequeñas se quedan minutos, las grandes bajan al cabo de unos segundos dejando un reguero de perlas y limpiando lo que cruzan, y siguen haciéndolo cuando ya no llueve. Los reflejos del propio objetivo siguen su apertura: más anchos con el objetivo abierto, y con el polígono de sus laminillas una vez cerrado. <code>ghosts</code> indica los reflejos de una óptica colocada delante del objetivo, que ningún catálogo conoce (el espejo y los prismas de un periscopio), cada uno como los de un objetivo: <code>scale</code>, <code>share</code>, <code>blur</code>, <code>offset</code>, <code>tint</code>; <code>reachDeg</code> hasta dónde, más allá de la esquina del encuadre, una luz alcanza aún su primera superficie (30° para un objetivo); <code>placedDrops</code> gotas indicadas una a una en lugar de las que <code>drops</code> reparte al azar, cada una un <code>radius</code> (parte de la altura de la imagen) y una <code>track</code> de <code>{t, x, y}</code> (ms, partes del ancho y del alto de la imagen desde su esquina superior izquierda), mantenida en sus extremos; <code>drops</code> solo dice entonces cuánta luz difunden</td></tr>
      <tr><td><code>lighting</code></td><td>Lo que la imagen muestra de la luz en que se tomó, cuando eso dice dónde estaba el Sol (un lado iluminado, un lado en sombra): <code>sunFromViewDeg</code>, el arco de los rumbos del Sol, en sentido horario desde la dirección en que miraba el instrumento al principio (<code>{ fromDeg: 105, toDeg: 285 }</code>: detrás de él, a uno u otro lado), y <code>sunAltitudeDeg</code> (<code>{ minDeg, maxDeg }</code>), su menor y su mayor altura. Compromete a una lectura de la observación: la fecha, la hora, el lugar y el rumbo que indica pueden moverse dentro de lo que se sabe de cada uno, pero el Sol que componen tiene que iluminar la escena como la muestra la imagen, de modo que desplazar el lugar desplaza las horas permitidas, y al revés</td></tr>
      <tr><td><code>iso</code></td><td>La sensibilidad de la película o del sensor con que se tomó la imagen, cuando se conoce: <code>400</code> para una película de 400 ISO. Si falta, la del propio aparato (el negativo en color de una réflex es 100, el de una Instamatic 64). La imagen de una cámara no responde como la de un ojo: una película no se adapta al cielo, recibe una exposición — la luz, por el tiempo de obturación, dividida por el cuadrado del número f — y responde a ella con su propia curva (la suave de un negativo, la más abrupta de una diapositiva, la línea recta de un sensor que se detiene en el blanco). Así, una pose nocturna sale con un cielo negro y lo que brillaba en él destacando. Indicada para un aparato que ajusta su propia exposición (un teléfono), es ese aparato ajustado a mano, como en su modo manual</td></tr>
      <tr><td><code>film</code></td><td>La película de la toma, cuando se conoce, por su identificador en el catálogo: <code>"kodachrome-64"</code>. Da la sensibilidad, salvo que <code>iso</code> indique otra, y la respuesta a la luz, blanco y negro incluido. Si falta, nadie lo dice.</td></tr>
      <tr><td><code>metering</code></td><td>Cómo leyó la luz un aparato que ajusta su propia exposición, cuando se sabe: <code>"average"</code>, la media de toda la imagen, como las videocámaras y los teléfonos antiguos, que quema en blanco una luz viva en una imagen oscura; o <code>"highlights"</code>, como los teléfonos recientes, conteniéndose para que una luz que ocupa una parte notable de la imagen conserve su color (un farolillo a veinte metros sale naranja, blanco solo junto a su llama), el resto de la noche más oscuro. Ausente: la del aparato (un teléfono protege sus altas luces)</td></tr>
      <tr><td><code>sway</code></td><td>Cuánto mueve la vista el cuerpo que sostiene el instrumento cuando no camina: <code>1</code> para una persona de pie o sentada, <code>0</code> para una cámara sobre trípode, cualquier valor intermedio o superior para menos o más. Si falta, <code>1</code> — salvo para un testigo que el relato dice que quedó paralizado (etiqueta <code>paralysis</code>), para quien es <code>0</code>, y para una exposición de más de medio segundo, que ninguna mano sostiene inmóvil: eso es un trípode, y también <code>0</code></td></tr>
      <tr><td><code>vehicle</code></td><td>El vehículo en el que iba el testigo, cuando el decorado no lo dibuja: <code>{ kind, windowsOpen, noise }</code>, siendo <code>kind</code> o bien un vehículo de carretera (<code>car</code>, <code>van</code>, <code>truck</code>, <code>motorcycle</code>, <code>generic</code>), o bien una aeronave, por su clase tal como se nombran las aeronaves del cielo (<code>business-jet</code>, <code>airliner-narrow</code>, <code>helicopter-light</code>…): un solo campo para ambos, al no tener los dos vocabularios ninguna palabra en común. Oído desde dentro: su motor sigue el propio trayecto del testigo — la marcha según la velocidad, las revoluciones según la marcha, el esfuerzo según acelere o frene — con la rodadura y el viento, amortiguados por un habitáculo cerrado, dejados entrar por ventanillas abiertas. Una aeronave no tiene ni marchas ni cilindros: lo que se oye de ella es el rugido continuo de su cabina, al nivel que mide en ella un pasajero para esa clase de máquina. <code>noise</code> es su sonoridad frente a uno corriente de su tipo (1 por defecto). Aquello en lo que va el testigo se interpone además entre él y todo lo que está fuera, y quita más a los agudos que a los graves: una aeronave a cien metros no es más que un retumbo a través de un fuselaje, y bajo el rugido de la cabina ya no se oye en absoluto; la lluvia y el viento entran amortiguados igual. <code>windowsOpen</code> deja volver casi todo. Es también lo que mantiene activo el botón de sonido del reproductor cuando el archivo no tiene <code>soundTrack</code>: el botón responde de todo lo que reproduce la escena — este motor, un <code>engine</code> del decorado, una aeronave del decorado en vuelo, un cuerpo de una lectura que se oye, la lluvia y el viento — y no solo de la pista. Sus luces: <code>headlights</code> es un ajuste como para un vehículo del decorado (<code>off</code>, <code>position</code>, <code>dipped</code>, <code>main</code>, <code>fog</code>) o <code>auto</code>, por defecto: las luces de cruce desde el crepúsculo y nada de día, que es lo que hace un conductor. <code>headlightKeyframes</code> es <code>[{ t, mode }]</code> para un cambio durante la grabación. El haz ilumina la carretera delante del testigo, en la dirección en que va el vehículo.</td></tr>
      <tr><td><code>decor</code></td><td>Decorado a unos <code>eastM</code>/<code>northM</code> reales del testigo: edificios (con <code>floors</code>, <code>windows</code>), árboles, arbustos, farolas, vehículos, puentes, líneas aéreas, otros testigos, aeronaves — opcionalmente con una <code>track</code> y <code>lights</code> cuyo <code>pattern</code> lleva una cadencia de destellos real. Véase más abajo</td></tr>
    </table>
    </div>
    <p>Un <strong>elemento del decorado</strong> se expresa en metros, como todo lo que no es el fenómeno:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>eastM</code>, <code>northM</code>, <code>headingDeg</code></td><td>Dónde está respecto al testigo, y hacia dónde mira su frente, en sentido horario desde el norte verdadero</td></tr>
      <tr><td><code>sizeM</code></td><td><code>{ widthM, lengthM, heightM }</code> a lo largo de sus propios ejes, siendo la longitud el sentido hacia el que mira. Cada eje es opcional: uno que nadie midió conserva la proporción propia de la forma integrada</td></tr>
      <tr><td><code>model</code></td><td>Un modelo 3D real en lugar de la forma integrada: una entrada del catálogo por <code>id</code>, o un archivo glTF/GLB en <code>url</code> (que prevalece, debe poder leerse desde cualquier origen, y entonces necesita su <code>credit</code>; una relativa se lee desde el archivo que la indica). Nunca decide el tamaño: se escala, conservando sus proporciones, al primer eje medido entre longitud, altura y anchura, o al tamaño real que le da el catálogo. Visto desde dentro, y siempre que no se pueda obtener el modelo, se dibuja en su lugar la forma integrada. <code>headingOffsetDeg</code> gira el modelo cargado sobre su eje vertical para que su morro apunte hacia donde la escena lo espera (0 mira al norte con un rumbo de 0); una entrada del catálogo trae el suyo. <code>credit</code> es <code>{ title, author, license, sourceUrl }</code>: <code>license</code> tal como la enuncia su autor (<code>"CC BY 4.0"</code>) y <code>sourceUrl</code> de dónde viene, para que la afirmación sea verificable.</td></tr>
      <tr><td><code>bridge</code></td><td>Para un <code>"bridge"</code>: cómo está construido. <code>sizeM.lengthM</code> es toda su longitud a lo largo de la carretera, terraplenes incluidos, <code>widthM</code> la anchura del tablero y <code>heightM</code> la altura de la calzada sobre el tablero por encima del suelo; <code>spanM</code> es la luz libre bajo el tablero, discurriendo la carretera sobre un terraplén de tierra que desciende hasta el suelo a cada lado; <code>deckThicknessM</code> el espesor de la losa (1,2 por defecto); <code>railing</code> <code>{ heightM, postSpacingM, rails }</code> la barandilla de ambos bordes, postes y barras cuyas aberturas son rectángulos (1,05 m, 1,5 m y 2 barras por defecto). Dibujado con esas medidas, nunca estirado</td></tr>
      <tr><td><code>wire</code></td><td>Para un <code>"wire"</code> (una línea eléctrica o telefónica): <code>sizeM.lengthM</code> es el vano entre sus postes, a lo largo de su <code>headingDeg</code>, y <code>heightM</code> la altura del cable más bajo; <code>strands</code> <code>[{ heightM, acrossM }]</code> cuelga varios (los superpuestos comparten un <code>acrossM</code>, los de una cruceta difieren); <code>poles</code> es <code>both</code> (por defecto), <code>start</code> o <code>end</code> (el extremo del que se aleja su rumbo o hacia el que apunta: el otro está anclado a un edificio) o <code>none</code>; <code>diameterM</code> (8 mm por defecto) y <code>poleHeightM</code> (medio metro sobre el cable más alto). Recta, sin flecha, y dibujada a esas medidas, nunca estirada</td></tr>
      <tr><td><code>track</code></td><td><code>[{ t, eastM, northM, altitudeM, headingDeg }]</code> cuando se mueve, <code>altitudeM</code> por encima del suelo bajo él (el ojo está a <code>elevationM</code> + 1,6 m: un cuerpo a la altura del ojo tiene ese <code>altitudeM</code>). La posición se interpola entre fotogramas clave; el rumbo se mantiene de uno al siguiente</td></tr>
      <tr><td><code>lights</code></td><td>Sus luces: <code>id</code>, <code>offsetM</code> <code>{ x, y, z }</code> desde su centro (derecha, arriba, delante), <code>color</code>, <code>intensity</code> (1 es una luz de navegación corriente) y un <code>pattern</code>: <code>{ "kind": "steady" }</code>, o <code>{ "kind": "flash", perMinute, dutyCycle, phase }</code>, la cadencia tal como la establecen los reglamentos, la fracción encendida de cada ciclo (cerca de 0,5 para un intermitente de filamento, 0,01 para un estroboscopio) y un desfase de 0 a 1 entre luces. El editor las rellena a partir de ajustes predefinidos: “Avión de pasajeros”, “Helicóptero”, “Coche, faros encendidos”, “Coche, luces de emergencia”, “Rotativos de vehículo de emergencia”, “Farola”. Cómo se enciende o se apaga durante la grabación, a partir de cada instante, <code>keyframes</code> <code>[{ t, intensity, pattern }]</code>: lo que dan los eventos <code>light</code> y <code>blink</code> sobre ella</td></tr>
      <tr><td><code>groups</code></td><td>Sus luces tomadas juntas, para que un solo evento trate de todas: <code>{ id, title, members }</code>, sus miembros luces suyas u otros de sus grupos. Nombrado en un evento como una luz, <code>id/grupo</code>: los dos destellos de un avión, <code>f-hobs/strobes</code>. Opcional</td></tr>
      <tr><td><code>engine</code></td><td>Un vehículo que se oye en marcha: <code>{ kind, noise }</code>, como <code>vehicle</code> más arriba. Su motor sigue su propia <code>track</code>, oído desde donde está el testigo, más débil y apagado con la distancia</td></tr>
      <tr><td><code>aircraftSound</code></td><td>Una aeronave (kind <code>aircraft</code>) que se oye mientras vuela, lo que hace cuando su <code>track</code> deja el suelo: la clase de ruido que hace, una clase de aeronave (<code>airliner-narrow</code> por defecto, <code>airliner-wide</code>, <code>airliner-supersonic</code>, <code>regional-jet</code>, <code>helicopter-light</code>, <code>light-piston</code>…) o <code>silent</code> para una que no hace ninguno. Lo que dice su modelo se aplica cuando esto falta (los sustitutos de un fenómeno son silenciosos). Se oye como las aeronaves de un registro de tráfico aéreo: más débil y más sorda con la distancia, <em>tarde</em> por el tiempo que el sonido tarda en llegar (unos tres segundos por kilómetro), de modo que se oye donde estaba, más aguda cuando se acerca y más grave cuando se aleja, y enmascarada por el ruido del lugar; un avión a reacción más fuerte al despegar que en aproximación, y detrás que delante, con el eco del suelo bajo él. Una aeronave dentro de la cual está el observador (un piloto en su cabina de mando) es la que monta: no se oye pasar, sino como su cabina, y lo que está fuera a través de su casco, como con <code>vehicle</code></td></tr>
      <tr><td><code>occludesSourceIds</code></td><td>Los fenómenos delante de los cuales el testigo dijo que este elemento estaba: consulta las <a href="/docs/format/#four-rules-that-decide-what-a-file-means">reglas de la página del formato</a></td></tr>
      <tr><td><code>facade</code></td><td>Solo el tipo <code>building</code>: <code>{ color?, plain? }</code>. <code>color</code> es el muro, <code>"#rrggbb"</code>; salvo que <code>plain</code> sea <code>true</code>, se dibujan ventanas en cada planta y una puerta en la planta baja de la cara frontal. Se dibuja al <code>sizeM</code> enunciado (deben estarlo los tres lados), nunca estirada, y no para un edificio con un testigo dentro. El editor toma el color del material que el mapa enuncia para los muros (piedra, ladrillo, hormigón, bloque, madera), o un enlucido donde no enuncia ninguno. Ausente es la caja lisa.</td></tr>
      <tr><td><code>roof</code></td><td>Solo el tipo <code>building</code>: <code>{ shape, riseM, color?, ridge? }</code>. <code>shape</code> es <code>"flat"</code> (la caja), <code>"gable"</code> (dos vertientes hasta una cumbrera a lo largo del lado mayor, o de la profundidad con <code>ridge: "depth"</code>) o <code>"hip"</code> (cuatro vertientes); <code>riseM</code> es lo que la cumbrera sube sobre el alero, así que los muros miden <code>sizeM.heightM</code> menos eso; <code>color</code> es el tejado visto desde arriba, <code>"#rrggbb"</code>. El editor los lee del láser y de la foto aérea del levantamiento. Ausente es un tejado plano del color de los muros.</td></tr>
      <tr><td><code>origin</code></td><td>El levantamiento del que se tomó este objeto, por el id de su proveedor (<code>"ign-lidar-topo"</code>), cuando el editor lo tomó del levantamiento del lugar y el autor no lo colocó a mano: un árbol, un edificio, un puente o un vano de línea. Elegir otro levantamiento, o ninguno, u otro lugar, sustituye o quita lo que lleva un <code>origin</code>, y nunca lo que no lo lleva</td></tr>
      <tr><td><code>surveyedOn</code></td><td>El día (<code>AAAA-MM-DD</code>) del levantamiento más reciente del que se extrajo este objeto, cuando viene de uno (véase <code>origin</code>): el editor advierte cuando es posterior a la observación.</td></tr>
      <tr><td><code>lit</code>, <code>litKeyframes</code></td><td>Si la lámpara de una farola o los faros de un vehículo están encendidos. <code>litKeyframes</code> es <code>[{ t, lit }]</code>, ordenado por <code>t</code>, para una luz que se enciende o se apaga durante la grabación; sin él, <code>lit</code> vale para toda la duración. Se ignora en un edificio, un árbol o un testigo</td></tr>
      <tr><td><code>headlights</code>, <code>headlightKeyframes</code></td><td>Cómo están puestas las luces de un vehículo, pues no todo el mundo las enciende, ni como debe: <code>off</code>, <code>position</code> (las luces de posición, que muestran el vehículo y no iluminan nada), <code>dipped</code> (las luces de cruce), <code>main</code> (las luces de carretera: lejos, estrechas, deslumbrantes) o <code>fog</code> (los faros antiniebla: bajos y anchos). Un haz ilumina la carretera, los arcenes, los árboles y las paredes delante del vehículo, sea cual sea la forma en que se dibuje. <code>headlightKeyframes</code> es <code>[{ t, mode }]</code>, ordenado por <code>t</code>, para un ajuste que cambia durante la grabación. Sin ninguno de los dos, lo dice <code>lit</code>: encendido son las luces de cruce. Se ignora para todo lo que no sea un vehículo. Solo cuatro vehículos (el del testigo y luego los más cercanos del decorado) tienen un haz real. Los faros del testigo proyectan sombras (un talud, un poste o un pilar de puente retiene la luz de lo que hay detrás), y el haz se ve en el aire en proporción a lo que el aire difunde de él: un rastro tenue con el aire limpio, un cono de luz en la niebla</td></tr>
      <tr><td><code>observerSide</code>, <code>observerFacing</code>, <code>observerKeyframes</code>, <code>occupiedFloor</code></td><td>El testigo dentro del objeto, para un <code>building</code> o un vehículo (solo un objeto a la vez lo contiene). <code>observerSide</code> dice dónde está: <code>front</code>, <code>behind</code>, <code>left</code>, <code>right</code>, <code>front-left</code>, <code>front-right</code>, <code>behind-left</code> o <code>behind-right</code>, estando el ocupante de un vehículo en una de sus cuatro puertas. <code>observerFacing</code> es la ventana por la que mira cuando no es la de su asiento: un conductor se sienta en <code>front-left</code> y mira por el parabrisas, <code>front</code>. <code>observerKeyframes</code>, <code>[{ t, side, facing }]</code>, dice dónde se sienta a lo largo del tiempo, cada uno mantenido hasta el siguiente, y un fotograma sin <code>side</code> significa fuera a partir de entonces, como un conductor que se baja. <code>occupiedFloor</code> es la planta de un edificio en la que está, de 0 (planta baja) a <code>floors</code></td></tr>
      <tr><td><code>modelParameters</code></td><td>Los ajustes del modelo con el que se dibuja el objeto, por la clave con que la entrada del catálogo publica cada uno: <code>{ "costumeColor": "#5a6b3a" }</code> para la ropa de una persona, <code>foliageColor</code> para un árbol, <code>hullColor</code> para una nave, <code>gearUp</code> para un avión de línea en vuelo. Un modelo trae los suyos (el editor dibuja un campo para cada uno); un objeto dibujado como forma integrada no tiene ninguno, se pinta con <code>color</code></td></tr>
      <tr><td><code>sightingUrl</code></td><td>Para un <code>observer</code>: la dirección de la grabación propia de ese testigo, cuando se conoce, para que el menú de la escena pueda ofrecer ver su testimonio</td></tr>
    </table>
    </div>

    <h2>Eventos del cielo</h2>
    <p>Lo que ocurrió en el cielo durante la grabación, como hechos: un disparo láser, un lanzamiento de cohete, una reentrada. Cada uno ocurrió lo viera alguien o no: no es la lectura del relato, ni el decorado, que dura más que la observación (una casa, un árbol). Se declaran bajo <code>skyEvents</code>, en el primer nivel de la grabación; una grabación que los ponía en su <code>interpretation</code>, como hacían las versiones anteriores, se sigue leyendo. Junto a ellos la escena pone lo que las fuentes saben de esa fecha y ese lugar: los meteoros de las lluvias y el fondo esporádico, los bólidos que registró una red de cámaras, las reentradas conocidas, los satélites seguidos, los aviones de un registro del tráfico aéreo. Lo que dice la grabación se les añade, sin sustituirlos nunca. <code>skySources: false</code>, en el primer nivel de la grabación, los deja fuera: un cielo introducido a mano, que solo contiene lo que dice la grabación (sus eventos, y las aeronaves de su entorno).</p>
    <pre data-json=""><code>{
  "skyEvents": {
    "beams": [{
      "id": "meudon-paris",
      "path": [
        { "lat": 48.805055, "lng": 2.231171, "altitudeM": 172.5 },
        { "lat": 48.83632, "lng": 2.33702, "altitudeM": 88 }
      ],
      "wavelengthNm": 532,
      "powerW": 10
    }]
  }
}</code></pre>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>auroras</code></td><td>Las auroras de la noche: un óvalo de luz que la alta atmósfera emite alrededor del polo magnético, de 90 a 900 km de altura, que la escena recorre a lo largo de cada línea de visión. <code>kp</code> dice lo agitado que estaba el campo (de 0 a 9, o por encima de 9 el índice Hp del GFZ, sin techo), y <code>activity</code> cómo evolucionó, <code>{ t, kp }</code> en instantes de la grabación unidos linealmente; 3 si no se indica ninguno. De ahí se siguen el borde del óvalo hacia el ecuador a medianoche magnética (66,5° de latitud de ápice del campo real en 0, unos dos grados más cerca del ecuador por paso), su anchura, un resplandor verde difuso, sus arcos y su brillo, y el rojo alto de una tormenta; <code>edgeLatDeg</code>, <code>arcs</code> (0 para el resplandor solo), <code>arcKR</code> (kilorayleighs de verde mirando a través de la altura de un arco: 1 el brillo de la Vía Láctea, 1000 ilumina el suelo como la luna llena) y <code>redKR</code> indican cada uno de otro modo. <code>fromT</code> y <code>untilT</code> dicen cuándo está, apareciendo y desapareciendo en un minuto. Necesita la fecha de la grabación, pues la posición del Sol decide la del óvalo. Una grabación que no indica ninguna recibe la que implica el índice archivado por el GFZ (Kp desde 1932, Hp60 desde 1985), acreditado, salvo si <code>skySources</code> es false.</td></tr>
      <tr><td><code>reentries</code></td><td>Las reentradas atmosféricas que ocurrieron, un satélite o una etapa de cohete que se desintegra en pedazos que arden. No son cuerpos: una reentrada arde entre 70 y 100 km de altura y se ve a cientos de kilómetros, así que se sitúa sobre la Tierra y se ve a través de su curvatura desde donde estaba el testigo. Su <code>track</code> da el punto de cabeza en instantes de la grabación, <code>{ t, lat, lng, altitudeKm }</code>, unidos por círculos máximos; cada uno de sus <code>fragments</code> sigue el mismo camino <code>lagS</code> segundos detrás, se ve desde <code>fromT</code> hasta apagarse en <code>untilT</code>, brilla con su <code>absoluteMagnitude</code> (a 100 km, como un bólido) llevada a su distancia real, en su <code>color</code>, con una estela de los últimos <code>trainS</code> segundos de su camino (4 si falta: la estela de una reentrada es larga). Cada pedazo se desintegra como lo hacen los pedazos que arden (<code>sheds</code>): un desmoronamiento lento en fragmentos débiles, cada uno con su estría, que se retrasan, se apartan y descienden en un abanico estrecho, y una ráfaga de una treintena en cada destello de su <code>lightCurve</code>, pues un destello es una ruptura (Zander &amp; Löhle, <em>CEAS Space Journal</em> 2025). Una lista de fases lo enuncia en su lugar, <code>{ fromT, untilT, perS, lifeS, magnitudeDrop, dropBack, spreadKmS, sinkKmS, trainS }</code>, y una lista vacía un pedazo que no suelta nada. Un destello más brillante que la magnitud −12 por debajo de 50 km se oye como una detonación, tras el tiempo que tarda el sonido en recorrer la distancia (Cheliábinsk: dos minutos y medio). Su luz es propia: se ve tanto si el Sol la alcanza como si no. <code>type</code> dice lo que entró, y con ello su naturaleza: <code>meteor</code> (meteoro) o <code>fireball</code> (bólido), naturales, <code>satellite</code>, <code>rocket-stage</code> (etapa de cohete) o <code>capsule</code>, puestos en órbita, o un tipo que añade un módulo (el punto de extensión <code>reentryTypes</code>); desconocido si falta, lo que a menudo deja en duda un relato. No cambia nada de lo que se dibuja, que se sigue del camino y los pedazos. <code>seen</code> dice dónde la vio el testigo, <code>{ fromAzimuthDeg, fromAltitudeDeg, toAzimuthDeg, toAltitudeDeg, durationS }</code>: el editor deduce de ello su camino, a las alturas del primer y último punto del camino, y lo guarda como lo que se dijo. <code>object</code> nombra lo que cayó (<code>name</code>, <code>cosparId</code>, <code>norad</code>). Nada se propaga desde elementos orbitales, errados en minutos en la última órbita: el camino es lo que establecen las fuentes, con su procedencia</td></tr>
      <tr><td><code>launches</code></td><td>Los lanzamientos de cohete que ocurrieron, iluminado por un Sol que se puso para el suelo pero no para la estela, la «medusa espacial». Situados sobre la Tierra como una reentrada: su <code>track</code> da la etapa en instantes de la grabación, <code>{ t, lat, lng, altitudeKm }</code> (puede empezar antes que la grabación), y <code>burnFromT</code> y <code>burnUntilT</code> los segundos en que el motor ardió. La estela es una fila de bocanadas soltadas a lo largo de ese camino, cada una expandiéndose con la edad; lo que se ve de cada una es la luz del Sol que difunde hacia el testigo. La sombra de la Tierra (dónde el Sol ilumina o no a la altura de la bocanada, y cuánto aire rozó su luz, lo que la enrojece o azulea), el ángulo de difusión y la expansión se calculan con el Sol real en la fecha real: nada se declara de ellos. Un <code>plume</code> opcional sustituye los valores por defecto: <code>exhaustKgPerS</code> (273, un Merlin Vacuum), <code>condensedShare</code> (0,065, el único número que nadie ha medido), <code>particleRadiusUm</code>, <code>expansionKmPerS</code>, <code>initialRadiusKm</code>, <code>lifetimeS</code>, y para el collar (el escape recién soltado, ancho y pronto desaparecido, junto a la estela estrecha que queda) <code>collarShare</code> (0,85), <code>collarExpansionKmPerS</code> (2,5), <code>collarLifetimeS</code> (20). <code>vehicle</code> nombra lo que voló y, en <code>engine</code>, el motor cuyo escape es: <code>thrustKN</code> y <code>specificImpulseS</code> (de los que se deducen el caudal de escape y su velocidad, y con ellos lo ancho del collar) y <code>propellant</code> (<code>rp1-lox</code>, <code>methane-lox</code>, <code>hydrogen-lox</code>, <code>hypergolic</code> o <code>solid</code>, que dice qué parte se vuelve partículas y de qué tamaño). Lo que dice <code>plume</code> prevalece sobre lo que dice el motor. La estela necesita la fecha de la grabación: sin ella no hay Sol que la ilumine. <code>vehicle.mission</code> nombra la misión que cumplía (<code>"Starlink Group 10-49"</code>). Cada bocanada vuela sola una vez soltada, a la velocidad de la etapa más la que se le dio, atraída por la Tierra y frenada por el aire solo donde es lo bastante denso para fluir a su alrededor (por debajo de 200 a 300 km): la estela es la misma cosa en el espacio vista desde todos los lados, una estela vista de frente es un disco, una espiral vista de canto una línea. Su color es el del tamaño de sus partículas: el hielo grueso difunde blanco, el hielo más fino que la longitud de onda azul. <code>jets</code> enumera lo que la etapa suelta además, cada uno <code>{ kind, fromT, untilT, angleDeg, azimuthDeg, spinPeriodS, speedKmPerS, massKgPerS, condensedShare, particleRadiusUm, expansionKmPerS, initialRadiusKm, lifetimeS }</code>: <code>kind</code> <code>burn</code> (otro encendido del motor, con los valores de la estela; un frenado de desorbitación es <code>angleDeg</code> 180, el escape saliendo por delante) o <code>vent</code> (propelentes purgados de los depósitos, más lentos, finos y fríos: 0,7 km/s, 20 kg/s, la mitad congelándose, por defecto); <code>angleDeg</code> desde atrás del movimiento (0) hasta el lado (90); <code>azimuthDeg</code> el lado por el que sale alrededor del movimiento (0 opuesto a la Tierra); <code>spinPeriodS</code> la vuelta de la etapa alrededor de su movimiento, que hace girar el chorro con ella y dibujar una espiral a los propelentes purgados. Cuando hay chorros, el encendido del ascenso solo se dibuja si se da <code>burnFromT</code> o <code>burnUntilT</code>.</td></tr>
      <tr><td><code>beams</code></td><td>Los haces de luz enviados por el aire desde el suelo, un disparo láser o un reflector. Cada uno tiene un <code>path</code> de al menos dos puntos <code>{ lat, lng, altitudeM }</code> (altitudes sobre el mar): donde sale del emisor, donde un espejo lo desvía si lo hay, y donde termina. Entre dos puntos es una recta a través del espacio, no a lo largo del suelo, que desciende bajo ella. <code>wavelengthNm</code> es su color (532 para un láser verde), <code>powerW</code> su potencia óptica media, <code>divergenceMrad</code> lo rápido que se ensancha (0,1 por defecto) y <code>apertureM</code> su anchura al salir (0,01 m por defecto); <code>fromT</code> y <code>untilT</code> dicen cuándo está encendido. Nada de su brillo se declara: lo que se ve de cada metro es lo que el aire allí (moléculas y bruma, a su longitud de onda) difunde hacia el ojo de la potencia que le queda, según el ángulo que la luz debe girar; por eso es mucho más vivo visto remontándolo que viéndolo alejarse. Lo oculta lo que está delante y se detiene donde encuentra el suelo.</td></tr>
    </table>
    </div>

    <h2>El tiempo, y sus nubes</h2>
    <p>Un fotograma clave <code>weather</code> expresa las condiciones del cielo en un momento del reloj
      de la grabación; entre dos fotogramas clave cada número se interpola, y el tipo de precipitación y la
      tormenta se mantienen. Contiene:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>cloudLayers</code></td><td>Las nubes, como una lista de capas — véase más abajo. <strong>Si falta</strong>, las describen los campos antiguos de las filas vecinas, adaptados a una capa de agua y un velo de cirros; <strong>una lista vacía</strong> significa un cielo despejado que alguien miró</td></tr>
      <tr><td><code>cloudCover</code>, <code>lowerCloudCover</code>, <code>highCloudCover</code></td><td>Fracciones de cielo (0–1): el total, solo las capas de agua, y solo el velo helado. Escritas por grabaciones hechas antes de que hubiera capas, y que el editor sigue manteniendo al día como resumen de ellas</td></tr>
      <tr><td><code>cloudBaseM</code>, <code>cloudDarkness</code></td><td>La base única de esa misma época, en metros sobre el suelo de referencia, y un tono único (0 blanco, 1 muy oscuro)</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>0–1, con qué regularidad caían los cristales de hielo — lo que convierte un simple anillo en parhelios, arcos y un pilar. Ningún registro lo mide; una capa de cirros lleva el suyo</td></tr>
      <tr><td><code>rareIceCrystals</code></td><td>0–1, la proporción de los cristales de un velo de cirros que son de tipos raros: columnas con extremos piramidales (los halos de radio impar, a 9°, 20° y 35°) y placas libres de girar en torno a un eje horizontal (los arcos de Lowitz). Ausente significa 5%, un velo ordinario. Como la alineación, ningún registro los cuenta: se declara. La simulación que se deriva se ha comprobado coherente con <a href="https://atoptics.co.uk">Atmospheric Optics</a></td></tr>
      <tr><td><code>relativeHumidity</code></td><td>0–1, cerca del suelo. Decide lo lechoso que es el cielo despejado: la bruma se hincha de agua a medida que el aire se acerca a la saturación. Un registro consultado la trae (a partir de la temperatura y el punto de rocío de ERA5); si falta, una bruma típica</td></tr>
      <tr><td><code>visibilityKm</code></td><td>La visibilidad meteorológica cerca del suelo, en kilómetros, tal como la da un parte. Es la bruma misma: declarada, decide cuánta hay, para la lejanía como para el cielo, y la humedad deja de leerse para ello Más allá de 30 km, es también la distancia hasta la que se dibuja el relieve (150 km como máximo), descendiendo con la curvatura de la Tierra: una montaña que un aire límpido muestra a lo lejos está ahí.</td></tr>
      <tr><td><code>precipitationType</code>, <code>precipitationIntensity</code></td><td>none/rain/snow/hail, y 0–1. Indicada en un fotograma clave, reproducida como cae: un chubasco empieza en el fotograma clave que lo inicia con sus primeras gotas, y no alcanza la intensidad indicada más deprisa que una lluvia real (de nada a lo más fuerte en veinte segundos); se detiene del mismo modo. Un cambio que los fotogramas clave reparten en más tiempo se sigue tal cual. <code>precipitationAmount</code> (0–1, ausente significa toda) dice qué parte de esa precipitación cae ya.</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>El viento general: el rumbo HACIA el que sopla, en sentido horario desde el norte, y metros por segundo. Es lo que arrastra las nubes — desde el instante cero, de modo que buscar y volver a reproducir dan el mismo cielo</td></tr>
      <tr><td><code>storm</code></td><td>Relámpagos y truenos, con el retraso correcto</td></tr>
    </table>
    </div>
    <p>Cada <strong>capa</strong> de <code>cloudLayers</code> es un manto de nubes a una altura real,
      y sigue siendo ella misma de un fotograma clave al siguiente:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>id</code></td><td>Estable entre fotogramas clave — las capas se emparejan por él, nunca por su posición en la lista. Una capa presente en un fotograma clave y ausente del siguiente se desvanece; reordenarlas no cambia nada</td></tr>
      <tr><td><code>type</code></td><td><code>cumulus</code>, <code>stratus</code>, <code>stratocumulus</code>, <code>cirrus</code> o <code>unknown</code>. Decide la forma de las cimas y lo fino que es el velo; un cirro es además el que refracta los halos. Cambia en el fotograma clave, no se interpola</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Metros. La base está sobre el suelo de REFERENCIA de la grabación, no sobre un testigo que sube; un testigo por encima de la base está dentro del manto o sobre él, y el cielo se dibuja en consecuencia</td></tr>
      <tr><td><code>coverage</code></td><td>0–1, y significa lo que dice: la fracción del cielo que cubre esta capa, sea cual sea el tamaño de sus nubes</td></tr>
      <tr><td><code>sizeM</code></td><td>La anchura característica de una nube, en metros. Independiente de la cobertura: la misma fracción de cielo puede ser muchas nubes pequeñas o unas pocas grandes</td></tr>
      <tr><td><code>density</code></td><td>0–2, lo opaca que es la materia de la nube; 0 es transparente. También independiente de la cobertura</td></tr>
      <tr><td><code>darkness</code></td><td>De 0 blanco a 1 muy oscuro. Si falta, el <code>cloudDarkness</code> del fotograma clave</td></tr>
      <tr><td><code>seed</code></td><td>Qué patrón, de entre los infinitos que los mismos números pueden dibujar. Si falta, uno derivado del id, y por eso el id no debe cambiar</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>El viento propio de esta capa, cuando difiere del general — la capa alta suele hacerlo. Si falta, el viento general</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>Solo para un cirro</td></tr>
      <tr><td><code>instances</code></td><td>Nubes individuales dentro de esta capa — véase más abajo</td></tr>
    </table>
    </div>
    <p>Una <strong>nube individual</strong> en <code>instances</code> es una nube de su capa que el
      archivo sitúa con exactitud, porque el relato lo hizo: aquella tras la que pasó el fenómeno, la que
      estaba allí y en ningún otro sitio. Se dibuja como una más de su capa — la misma textura, el mismo
      umbral —, sin distinguirse de sus vecinas más que por dónde está y lo grande que es,
      y está ahí incluso cuando la <code>coverage</code> de la capa es nula. Se desplaza con el viento de
      la capa como las demás, y oculta un fenómeno ante el que pasa.</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significado</th></tr>
      <tr><td><code>id</code></td><td>Estable entre fotogramas clave, misma regla que para una capa</td></tr>
      <tr><td><code>eastM</code>, <code>northM</code></td><td>Dónde estaba su centro en el instante cero, en metros desde el punto de partida del testigo. El viento la arrastra desde allí</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Su propia base y su propia altura, en metros — una nube puede estar más baja o alzarse más que su manto</td></tr>
      <tr><td><code>widthM</code>, <code>depthM</code>, <code>rotationDeg</code></td><td>Su huella, en metros, y el rumbo hacia el que está girada esa huella</td></tr>
      <tr><td><code>density</code>, <code>darkness</code></td><td>Las suyas propias; si falta la oscuridad, la de la capa</td></tr>
    </table>
    </div>
    <pre data-json="weatherTrack.keyframes"><code>{
  "weather": {
    "cloudLayers": [
      {
        "id": "low", "type": "cumulus",
        "baseM": 1500, "thicknessM": 800,
        "coverage": 0.55, "sizeM": 1400, "density": 1, "darkness": 0.15,
        "instances": [
          { "id": "the-one", "eastM": 0, "northM": 4200,
            "baseM": 1500, "thicknessM": 800,
            "widthM": 1900, "depthM": 1300, "rotationDeg": 12, "density": 1 }
        ]
      },
      { "id": "high", "type": "cirrus", "baseM": 8000, "thicknessM": 400,
        "coverage": 0.2, "sizeM": 2200, "density": 0.35, "iceCrystalAlignment": 0.65 }
    ],
    "precipitationType": "none", "precipitationIntensity": 0,
    "windDirectionDeg": 90, "windSpeed": 5, "storm": false
  }
}</code></pre>
    <p>Una grabación cuyo tiempo fue <strong>consultado</strong> (tiene un <code>weatherSource</code>)
      guarda la respuesta del registro, no un enlace a él: ERA5 da las bandas baja, media y alta como tres
      capas llamadas <code>record-low</code>, <code>record-mid</code> y <code>record-high</code>, la
      base baja estimada a partir de la diferencia entre temperatura y punto de rocío, las otras dos a 3 500 m
      y 8 000 m. Su tipo es <code>unknown</code> (cirro para la alta), su tamaño y su densidad
      son supuestos de dibujo: un reanálisis sabe qué parte de cada banda estaba cubierta, no qué aspecto
      tenían las nubes. Vuelve a pedir el registro desde el editor y las capas se reescriben; edita
      una capa a mano y la grabación pasa a ser del autor, y la fuente se elimina.</p>
`
  }

  private it(): string {
    return `
    <h2 id="everything-around-it">I campi intorno a ciò che è stato visto</h2>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>observerTrack</code></td><td><code>{ keyframes: [{ t, pose }] }</code> — <code>pose</code> contiene <code>lat</code>, <code>lng</code>, <code>elevationM</code> (sopra il suolo locale), <code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>, e per una fotocamera <code>fNumber</code> e <code>focusDistanceM</code>. Riprodotto come si muove una persona: esattamente la posa indicata a ogni fotogramma chiave, e fra l'uno e l'altro un movimento che prende velocità, la mantiene attraverso i fotogrammi chiave che continuano a muoversi, e rallenta fino a una pausa — due fotogrammi chiave con lo stesso luogo, o la stessa direzione. Uno sguardo inizia e finisce fermo; una camminata o un tragitto in auto già in corso al primo fotogramma chiave prosegue. Fermarsi e ripartire a piedi aggiungono il loro sobbalzo, un cenno del capo che si spegne in un secondo e mezzo, trasferito nell'immagine quanto lo strumento lo lascia passare (appena per un occhio, del tutto per una fotocamera tenuta in mano). E un corpo a riposo non è mai del tutto immobile: in piedi o in attesa, la vista oscilla di qualche millimetro e deriva di un decimo di grado, lentamente, allo stesso modo nello stesso istante — tranne per un testimone che il resoconto dice paralizzato (tag <code>paralysis</code>). Il <code>pitchDeg</code> indicato è come il testimone guardava nel riferimento di ciò che lo portava: finché si sposta, il lettore aggiunge come sale il veicolo stesso (la pendenza della strada sotto la traccia, letta dal rilievo, positiva in salita, o per un aereo la sua stessa salita, attenuata quando lo sguardo si allontana dalla sua strada), così che una salita alza la vista e il chip <q>Inclinazione</q> indica la somma. <code>filter</code> è ciò che si teneva davanti allo strumento, un id di <code>FILTERS</code> come <code>solar-visual</code> per un'eclissi. Viene mantenuto tra i fotogrammi chiave, non sfumato (nessuno porta mezzi occhiali), e si toglie dichiarando <code>"none"</code>. Un fotogramma chiave che indica <code>viewOnly: true</code> fissa la vista del suo solo istante (l'editor lo scrive quando la vista è girata tenendo Alt premuto): la rotazione della fotocamera verso di esso e da esso resta fuori dall'immagine, e un'esposizione che lo tocca è disegnata come se la fotocamera fosse rimasta ferma, puntata come all'istante mostrato. Un testimone che vola a una quota data la indica con <code>altitudeM</code> (metri sul mare): il lettore pone allora l'occhio a quella quota sopra il rilievo che disegna, e <code>elevationM</code> è solo l'altezza sopra il suolo rispetto a cui è stato scritto il file, rispetto alla quale è quotato anche lo scenario di una cabina attorno all'occhio.</td></tr>
      <tr><td><code>events</code></td><td>Ciò che ha fatto il testimone, espresso come eventi con i loro parametri invece delle pose che implicano: <code>[{ type: "event", eventType, t, until, params }]</code>, <code>t</code> e <code>until</code> in ms della registrazione. Il lettore ne calcola le pose leggendo la registrazione, con la stessa legge per tutte (una rotazione della testa parte da ferma e si assesta, la linea di un veicolo è una curva), e riscrive solo gli eventi finché nulla ha cambiato quelle pose; un <code>observerTrack</code> con fotogrammi chiave propri prevale su di essi. Un parametro porta la sua provenienza come ogni valore. Una tabella di istanti (<code>speeds</code>, <code>speedDivisors</code>, <code>heights</code>, <code>metres</code>) ha tante righe quante ne servono al racconto; il suo valore passa gradualmente da una riga alla successiva, o di colpo a una riga con <code>step: true</code>. A piedi: <code>look</code> (uno sguardo tenuto da <code>t</code> in poi, <code>headingDeg</code>, <code>pitchDeg</code>), <code>walk</code> (da <code>from</code> a <code>to</code>, due <code>{ lat, lng }</code>, tra <code>t</code> e <code>until</code>, come cammina e si ferma una persona) e <code>follow</code> (un corpo della lettura, o un fenomeno che attraversa il cielo, <code>target</code>, che gli occhi raggiungono <code>reactionS</code> dopo, con <code>lagS</code> di ritardo, guardato ogni <code>sampleMs</code> in mancanza di fotogrammi chiave propri, guardato a ciascuno dei suoi fotogrammi chiave, al centro di ciò che vede, lo sguardo che gira tra di essi come gira una testa; tenuto dove lo perde, a <code>until</code>; <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>). In veicolo: <code>drive</code> (il veicolo del testimone, un oggetto della scena nominato da <code>vehicle</code>, segue <code>path</code>, un elenco di <code>{ lat, lng }</code>, alle velocità <code>speeds</code> <code>[{ t, kmh }]</code>, eventualmente divise per <code>speedDivisors</code> <code>[{ t, divisor }]</code>, collocato dall'unico luogo per cui è passato, <code>through</code> <code>{ t, lat, lng }</code>; l'<code>eye</code> del conducente è <code>{ x, y, z }</code> nel modello del veicolo), <code>lookAhead</code> (guarda la strada e tiene il bersaglio <code>target</code> <code>{ lat, lng }</code> entro circa <code>keepDeg</code>, e gli lancia occhiate di <code>glanceS</code> seguite da <code>roadS</code> sulla strada quando è a più di <code>glanceBeyondDeg</code>; <code>pitchShare</code> dice fino a che parte della sua altezza alza lo sguardo), <code>lean</code> (verso lo specchietto: l'occhio si sposta di <code>offsetM</code> in <code>turnS</code>, per <code>holdS</code>) e <code>watch</code> (nello specchietto <code>mirror</code>, un punto del modello del veicolo: <code>firstS</code>, poi <code>mirrorS</code> tra due sguardi altrove, un'occhiata diretta di <code>glanceS</code> una volta su due fino a <code>glancesUntil</code>, la strada per <code>roadS</code> altrimenti). Ogni evento dice di chi è in <code>who</code>, con un id della registrazione che nient'altro ha: quello del testimone (<code>observer.id</code>, o <code>"observer"</code> per un testimone senza id; un evento che non ne dice nessuno è suo), di una forma o di un gruppo di forme, di un corpo, di un oggetto della scena. L'editor non salva una registrazione con un evento su niente, o con due cose dello stesso id. Un evento di un oggetto della scena: <code>fly</code> (un aereo lungo una linea retta che porta a <code>from</code> <code>{ lat, lng }</code>, con rotta <code>headingDeg</code>, alle velocità <code>speeds</code>, a <code>at.metresBefore</code> da quel luogo all'istante <code>at.t</code>, a <code>heights</code> <code>[{ t, altitudeM }]</code> sopra l'occhio del testimone). Una sua luce (<code>id/luce</code>, <code>f-hobs/landing-nose</code>), o un gruppo di luci che i <code>groups</code> dell'oggetto nominano (<code>f-hobs/strobes</code>): <code>light</code> (a <code>intensity</code> dall'inizio dell'evento, 0 spenta, lampeggiando come prima, e tornata a ciò che era alla sua fine quando ne dichiara una) e <code>blink</code> (accesa per <code>onS</code>, spenta per <code>offS</code>, a <code>intensity</code> o a ciò che era, fino alla fine dell'evento, poi come prima): un faro di atterraggio spento, dei flash accesi, un lampeggiante, il balisaggio della cima di un edificio. Quelli del fenomeno (<code>who</code> la forma con cui è disegnato, o il gruppo delle sue forme) danno le forme del resoconto, come il testimone lo ha descritto: <code>stand</code> (nel luogo <code>place</code> che ha dichiarato, <code>{ lat, lng }</code>, i suoi <code>metres</code> <code>[{ t, widthM, heightM }]</code> la sua larghezza e la sua altezza sopra l'occhio, da cui seguono a ogni istante la sua direzione e la sua dimensione nel suo cielo), <code>appearance</code> (il suo aspetto da <code>t</code> in poi, le sue <code>parts</code>: forme collocate e dimensionate in parti della sua larghezza apparente, <code>sourceId</code>, <code>kind</code>, <code>points</code>, <code>color</code>, <code>brightness</code>, <code>halo</code>, <code>widthShare</code>, <code>heightShare</code>, <code>alongShare</code>, <code>upShare</code>; una parte che un altro aspetto ha e questo no non è vista), <code>blink</code> (le forme di cui è, un gruppo di quelle del fenomeno o una di esse, accese per <code>onS</code>, spente per <code>offS</code>, che prendono <code>off</code> da spente) e <code>vanish</code> (non è più visto). Oppure, senza luogo, attraversando il cielo, un resoconto di sole direzioni: <code>travel</code> (<code>from</code> una direzione <code>{ azimuthDeg, altitudeDeg }</code> <code>towards</code> un'altra, lungo il cerchio massimo che le unisce, alle velocità <code>speeds</code> <code>[{ t, degPerS }]</code>, gradualmente tra due; <code>sizeDeg</code> di larghezza allo zenit, più piccolo come il seno della sua altezza quando <code>sizeBy</code> è <code>"altitude"</code>; le sue parti disposte lungo il suo cammino nell'immagine del testimone, <code>alongShare</code> davanti o dietro, <code>upShare</code> alla sua sinistra, girate con esso), <code>turn</code> (di <code>byDeg</code> verso il suo lato <code>side</code>, <code>"left"</code> o <code>"right"</code>, gradualmente; l'altro lato nel cielo quando <code>seenFrom</code> è <code>"craft"</code>, come lo dice un pilota), <code>roll</code> (inclinato fino a <code>toDeg</code>, e tornato in piano con <code>andBack</code>, più stretto di traverso secondo il coseno), <code>vibrate</code> (da un lato all'altro <code>hz</code> volte al secondo, di <code>amplitudeShare</code> della sua dimensione, da niente in <code>riseS</code>, poi sempre meno fino alla fine dell'evento) e <code>spiral</code> (<code>turns</code> giri di un cerchio accanto al suo cammino, <code>clockwise</code> o no, di <code>radiusDeg</code> una volta aperto, ridotto di <code>shrink</code> alla fine, rollando di <code>rollDeg</code>); <a href="/demo-data/observer-saint-lo.json"><code>observer-saint-lo.json</code></a>. Quelli di un corpo della lettura (<code>who</code> il suo id; o, su una parte del suo modello, un nodo o un osso, <code>id/parte</code>: <code>craft/legs</code>, <code>etre-2/head</code>, che <code>spin</code> e <code>turn</code> fanno girare da sola attorno al proprio asse verticale, in senso orario vista dall'alto, il resto del corpo così com'è; una luce, con il suo nome nel modello, <code>engin/front-red</code>, o un gruppo delle sue parti che i <code>groups</code> del corpo nominano, <code>engin/rear</code>; è il file del modello a dire quali parti ha) si aggiungono ai fotogrammi chiave che dichiara: <code>motion</code> (un movimento del suo modello eseguito una volta, <code>motion</code> fino a <code>to</code>, il tubo centrale che rientra), <code>spin</code> (uno che continua a girare, <code>turnsPerS</code>, le gambe), <code>rise</code> (<code>distanceM</code> lungo una retta a <code>angleDeg</code> dalla verticale, 0 dritto in alto, verso <code>headingDeg</code>, da fermo, rallentando fino a fermarsi o, <code>stops: false</code>, sempre più veloce mentre se ne va), <code>turn</code> (voltarsi verso <code>headingDeg</code>), <code>ride</code> (portato dal corpo <code>in</code>, <code>aboveM</code> più in alto), <code>light</code> (una luce, o un gruppo di luci, accesa a <code>cdM2</code> dall'inizio dell'evento, 0 spenta, e riaccesa com'era alla sua fine quando ne dichiara una) e <code>blink</code> (una luce che lampeggia, accesa per <code>onS</code>, spenta per <code>offS</code>, a <code>cdM2</code> da accesa o a ciò che era prima, fino alla fine dell'evento, poi come prima; di colpo, mai in dissolvenza: i flash di un aereo, un lampeggiante, la luce in cima a un traliccio) e <code>vanish</code>; anche una postura è un movimento del modello (<code>motion</code> su <code>crouch</code>, che porta una figura esportata con le sue posture: 0 in piedi, 1 accovacciata); il velivolo e gli esseri di <a href="/demo-data/observer-valensole.json"><code>observer-valensole.json</code></a>. <a href="/demo-data/observer-silly-le-long.json"><code>observer-silly-le-long.json</code></a> esprime così il suo testimone, il suo aereo e il suo fenomeno</td></tr>
      <tr><td><code>sampleMs</code></td><td>Ogni quanto si prende un fotogramma chiave, in ms: dal registratore dell'editor quando si sposta una forma a mano, e dove gli eventi sono sviluppati in valori (le forme del resoconto, lo sguardo che le segue, un corpo che si alza), tutti allo stesso passo, perché ciò che è disegnato e lo sguardo per cui lo è non si sfasino mai. Di ciò che ne risulta, i fotogrammi chiave che dicono la stessa cosa conservano solo il primo e l'ultimo: il lettore disegna lo stesso tra di essi. Assente, ciascuno conserva il proprio: 25 ms per un fenomeno che attraversa il cielo e lo sguardo che lo segue, 2 s per uno immobile, 250 ms per un corpo che si alza</td></tr>
      <tr><td><code>weatherTrack</code></td><td><code>{ keyframes: [{ t, weather }] }</code> — le condizioni del cielo lungo la registrazione: precipitazioni, vento, temporale, e le nuvole come strati ad altezze reali, ognuno in grado di contenere nuvole singole collocate in metri. Ogni campo di un <code>weather</code> è nella sezione seguente</td></tr>
      <tr><td><code>weatherSource</code></td><td><code>{ id, name, url }</code> del dato da cui è stato ricavato il meteo. La sua presenza significa che la registrazione viene riprodotta esattamente come è stata composta e non viene mai più consultata. Se manca, è il resoconto del testimone stesso</td></tr>
      <tr><td><code>lightPollution</code></td><td>La brillanza del cielo notturno del luogo, città comprese: lo zenit di una notte senza Luna in magnitudini per secondo d'arco quadrato, come lo legge uno Sky Quality Meter o come lo dà l'<a href="https://doi.org/10.1126/sciadv.1600377">atlante mondiale della brillanza artificiale del cielo notturno</a> (la sua cifra «SQM», Falchi et al. 2016, che <a href="https://www.lightpollutionmap.info">lightpollutionmap.info</a> mostra per ogni luogo). <code>22</code> è un cielo naturale, una periferia intorno a <code>19</code>, un centro città <code>17</code>. Se manca, un cielo naturale. La parte delle città, ciò che resta tolti i 22 naturali, si aggiunge al cielo come luce: più forte verso l'orizzonte, dove l'aria bassa ne rimanda di più, e disegnata nel bianco caldo di una lampada a 3000 K. Annega la Via Lattea e la luce zodiacale, e toglie stelle, della differenza nella stella più debole che un occhio distingue (Crumey 2014): circa due magnitudini a <code>19</code>. Ora la Luna fa lo stesso. <code>"derived"</code> quando è ricavata dall'atlante, <code>"stated"</code> quando il testimone l'ha misurata. L'editor la compila dall'atlante per un'osservazione dal 2015 in poi, come <code>"derived"</code> con l'atlante nominato, e non sostituisce mai una cifra scritta a mano; prima del 2015 non consulta nulla, perché il cielo era più buio di quello dell'atlante</td></tr>
      <tr><td><code>around</code></td><td>Ciò che faceva rumore intorno all'osservatore, contro cui si sente un aereo come contro il vento e la pioggia: <code>cars</code> (auto), <code>trucks</code> (camion e autobus), <code>people</code> (persone) e quante di loro <code>talking</code> (parlavano), presenti insieme entro <code>withinM</code> metri (200 se assente), e <code>roads</code> (strade), ciascuna <code>{ distanceM, vehiclesPerMinute, trucksPerMinute, speedKmh }</code> (50 km/h se assente), poiché un testimone può dire l'uno o l'altro. Ciò che se ne sente dove si trova l'osservatore si ricava dalla potenza sonora dei veicoli di <a href="https://eur-lex.europa.eu/legal-content/IT/TXT/?uri=CELEX:32021L1226">CNOSSOS-EU</a> (un'auto a 50 km/h fa 73 dB(A) a 7,5 m) e dai 55 dB(A) a 1 m di una conversazione (Pearsons et al. 1977): ciò che è contato come distribuito sul suo disco, una strada come una linea. Si somma al rumore del tempo: il traffico di una città copre aerei che un campo tranquillo lascia sentire. Niente ne suona ancora: il rumore di una strada suonato come sfondo era un soffio sopra gli aerei; si sentirà quando la scena avrà veicoli propri. Ogni cifra ha la sua provenienza, in <code>around.cars</code> o <code>around.roads.0.distanceM</code>. Se assente: un luogo tranquillo</td></tr>
      <tr><td><code>observerMap</code></td><td>Se la mappa di dove si trovava il testimone parte aperta quando la registrazione viene riprodotta o modificata: <code>true</code> o <code>false</code>. Se manca, decide il lettore: aperta per un testimone che si è spostato, chiusa per uno rimasto fermo. Una pagina che incorpora il lettore ha l'ultima parola (il suo attributo <code>show-observer-map</code>). L'editor lo scrive quando la mappa viene aperta o chiusa al suo interno, così che un lettore veda ciò che l'autore ha lasciato</td></tr>
      <tr><td><code>snapshots</code></td><td>Dove sono conservati, in file accanto alla registrazione (allegati), i dati che la scena chiederebbe altrimenti a terzi a ogni riproduzione, perché una registrazione finita si riproduca uguale fra dieci anni senza chiedere nulla a nessuno: <code>relief</code> (l'altezza del suolo, come la fonte di quota l'ha data per ogni porzione di terreno che la scena costruisce, uno zip), <code>imagery</code> (la foto del suolo, come le tessere servite dalla fonte di immagini, uno zip), <code>roads</code>, <code>water</code>, <code>railways</code> (strade, acque e binari di ogni porzione, in JSON), <code>upperAir</code> (l'aria alla quota degli aerei, in JSON) e <code>map</code> (la foto sotto la mappa del testimone, come le tessere servite dalla fonte di immagini per il terreno a cui la mappa è adattata, uno zip: una mappa presa come istantanea mostra quella foto e non ne chiede altre, ingrandita avvicinandosi, vuota oltre allontanandosi). Ognuno è <code>{ src, takenOn, attribution }</code>, con <code>src</code> letto rispetto all'indirizzo della registrazione, o un URL <code>data:</code> per un allegato conservato dentro la registrazione stessa. Un gruppo letto dal suo allegato non chiede nulla a nessuno; uno senza allegato è chiesto in diretta, come tutto prima. <code>"live": true</code> su un gruppo lo chiede in diretta a ogni riproduzione e non ne prende mai un'istantanea (ciò che dice scegliere la sua fonte in diretta invece di <em>File</em>), e su <code>snapshots</code> stesso tutti i gruppi; <code>"refresh": true</code> su un gruppo lo chiede in diretta una volta, e l'editor lo rileva al salvataggio successivo. L'editor rileva ciò che manca al salvataggio, e salva la registrazione e i suoi allegati in un unico zip da decomprimere dove è pubblicata. <code>weather</code>, <code>place</code>, <code>lightPollution</code> e <code>decor</code> dicono che il meteo (<code>weatherTrack</code>, <code>weatherSource</code>), il nome del luogo, la cifra del cielo notturno e la scenografia sono letti dal file invece di essere richiesti di nuovo (ai dati meteo quando cambiano la data o il luogo, al geocodificatore, all'atlante e al rilievo quando il testimone si sposta): <code>{}</code> se sono dentro la registrazione, <code>{ src }</code> per un allegato con le loro chiavi, che i lettori rimettono nella registrazione caricandola. Se mancano, sono dentro la registrazione e l'editor li richiede. Il fuso orario non è qui: è scritto nella registrazione stessa</td></tr>
      <tr><td><code>modules</code></td><td>I moduli di cui la registrazione ha bisogno per essere disegnata come è stata fatta (un catalogo da cui vengono i suoi modelli), per l'indirizzo del manifesto di ognuno, relativo alla registrazione o assoluto: vedi <a href="/docs/modules/">moduli</a>. Un lettore riceve ciò che ogni manifesto dichiara, mai il suo script a meno che non abbia aggiunto quel modulo lui stesso. Assente, non ne serve nessuno</td></tr>
      <tr><td><code>soundTrack</code></td><td><code>{ keyframes: [{ t, sound }] }</code> — <code>kind</code> (none/hum/whistle/rumble/crackle), <code>volume</code>, <code>pitchHz</code>, e un <code>src</code> facoltativo di una registrazione reale. <code>volume</code> e <code>pitchHz</code> scorrono fra i fotogrammi chiave, <code>kind</code> e <code>src</code> cambiano al fotogramma chiave. Un <code>src</code> su un altro sito deve essere servito a qualsiasi origine (CORS)</td></tr>
      <tr><td><code>references</code></td><td>Immagini del luogo sovrapposte alla scena: <code>src</code> (un indirizzo, o un URL <code>data:</code> per un'immagine aggiunta da un disco), <code>kind</code> (photo/panorama/video), <code>registration</code> (<code>headingDeg</code>, <code>pitchDeg</code>, <code>rollDeg</code>, <code>fovDeg</code>), <code>opacity</code>, <code>credit</code>/<code>creditUrl</code>, <code>t</code> e <code>drawing</code> facoltativi, <code>from</code> (<code>{ lat, lng }</code>, dove è stata scattata: il lettore la dissolve man mano che il testimone si allontana da quel punto; se manca, non si dissolve mai), e i <code>landmarks</code> su cui è stata allineata (<code>id</code>, <code>label</code>, <code>picture</code> come <code>{ u, v }</code> dall'angolo in alto a sinistra, <code>scene</code> come <code>{ azimuthDeg, altitudeDeg }</code>). Un <code>video</code> indica anche <code>t</code>, dove inizia il suo tratto sulla timeline, <code>video</code> (<code>fromS</code>, <code>toS</code>, <code>rate</code>: quale parte del file, a che velocità) e <code>registrationTrack</code>, dove puntava la sua camera in ogni istante allineato.</td></tr>
      <tr><td><code>traces</code></td><td>Ciò che un investigatore ha disegnato sul luogo, importato dal suo file Google Earth (KML, KMZ) o dal GeoJSON del suo GIS e mostrato sulla scena come suo, mai come parte della ricostruzione: <code>[{ id, title, kind, points, altitude, color, source }]</code>, dove <code>kind</code> è <code>point</code>, <code>line</code> o <code>polygon</code>, <code>points</code> i vertici come <code>[{ lat, lng, altM }]</code> esattamente come li aveva il file, <code>altitude</code> come si legge <code>altM</code> (<code>ground</code>, predefinito, <code>relative</code> al suolo sotto ogni punto, o <code>absolute</code> sul livello del mare), <code>color</code> un <code>#rrggbb</code> e <code>source</code> di chi è</td></tr>
      <tr><td><code>instrument</code>, <code>exposureSeconds</code></td><td>Attraverso che cosa è stato osservato, e per quanto tempo è rimasto aperto l'otturatore. Se manca, l'occhio nudo. <code>instrument</code> è uno fra <code>eye</code>, <code>rectilinear-lens</code> (una fotocamera di marca sconosciuta), <code>roamer-1-120</code>, <code>instamatic-126</code>, <code>slr-35mm-50</code>, <code>slr-35mm-zoom</code>, <code>phone-landscape</code>, <code>phone-portrait</code>, o una reflex digitale (<code>eos-5d-iii</code>, <code>nikon-d7000</code>… i sensori del catalogo di Stellarium), un binocolo (<code>binoculars-nikon-10x42-edg</code>…) o un telescopio (<code>telescope-celestron-c8</code>…); <code>exposureSeconds</code> è un unico valore per tutta la registrazione, contenuto nell'intervallo proprio di quel dispositivo; un apparecchio che registra un'immagine (una fotocamera, un telefono) vi aggiunge i riflessi fantasma del suo obiettivo su ogni luce, come fanno il vetro e il sensore: una copia più debole e sfocata sulla retta che passa per il centro dell'immagine, simmetrica rispetto a esso per il riflesso principale di un telefono, il disco rosso opposto a un semaforo. Un telefono si espone da sé in base a ciò che vede, fino a ISO 3200: una notte che filma resta scura attorno alle sue lampade</td></tr>
      <tr><td><code>lens</code></td><td>Attraverso cosa è stata presa l'immagine oltre all'obiettivo, e cosa c'era su quel vetro, per un apparecchio che ne registra una: <code>glass</code> (<code>filter</code>, <code>window</code> o <code>windscreen</code>: un filtro aggiunge un riflesso simmetrico rispetto al centro, un vetro un doppio più debole di ogni luce appena accanto, più lontano per un parabrezza inclinato), <code>drops</code>, <code>condensation</code> e <code>dirt</code> (da 0 a 1, ognuno con un alone attorno a ogni luce, che perde ciò che l'alone prende) e <code>sheltered</code>. Senza <code>drops</code>, le gocce seguono la pioggia o la neve che cade a ogni istante, salvo se <code>sheltered</code> è vero: ne cadono di nuove tanto più spesso quanto più la pioggia colpisce il vetro di fronte (un obiettivo alzato, un vetro di fronte al vento, un parabrezza inclinato ne ricevono di più), si fondono con le vicine; le piccole restano attaccate per minuti, le grandi scendono dopo qualche secondo lasciando una scia di perle e pulendo ciò che incontrano, e continuano anche quando ha smesso di piovere. I riflessi dell'obiettivo stesso seguono la sua apertura: più larghi a obiettivo aperto, e col poligono delle sue lamelle una volta diaframmato. <code>ghosts</code> indica i riflessi di un'ottica posta davanti all'obiettivo, che nessun catalogo conosce (lo specchio e i prismi di un periscopio), ciascuno come quelli di un obiettivo: <code>scale</code>, <code>share</code>, <code>blur</code>, <code>offset</code>, <code>tint</code>; <code>reachDeg</code> fin dove, oltre l'angolo dell'inquadratura, una luce colpisce ancora la sua prima superficie (30° per un obiettivo); <code>placedDrops</code> gocce indicate una a una invece di quelle che <code>drops</code> sparge a caso, ciascuna un <code>radius</code> (parte dell'altezza dell'immagine) e una <code>track</code> di <code>{t, x, y}</code> (ms, parti della larghezza e dell'altezza dell'immagine dal suo angolo in alto a sinistra), tenuta alle estremità; <code>drops</code> dice allora solo quanta luce diffondono</td></tr>
      <tr><td><code>lighting</code></td><td>Ciò che l'immagine mostra della luce in cui è stata presa, quando dice dove fosse il Sole (un lato illuminato, un lato in ombra): <code>sunFromViewDeg</code>, l'arco degli azimut del Sole, in senso orario dalla direzione in cui guardava lo strumento all'inizio (<code>{ fromDeg: 105, toDeg: 285 }</code>: dietro di esso, da una parte o dall'altra), e <code>sunAltitudeDeg</code> (<code>{ minDeg, maxDeg }</code>), la sua altezza minima e massima. Vincola una lettura dell'osservazione: la data, l'ora, il luogo e la rotta che indica possono muoversi entro ciò che si sa di ciascuno, ma il Sole che compongono deve illuminare la scena come la mostra l'immagine, così che spostare il luogo sposta le ore consentite, e viceversa</td></tr>
      <tr><td><code>iso</code></td><td>La sensibilità della pellicola o del sensore su cui è stata scattata l'immagine, quando è nota: <code>400</code> per una pellicola da 400 ISO. Se manca, quella del dispositivo stesso (il negativo a colori di una reflex è 100, quello di una Instamatic 64). L'immagine di una fotocamera non risponde come quella di un occhio: una pellicola non si adatta al cielo, riceve un'esposizione — la luce, per il tempo di otturazione, divisa per il quadrato del numero f — e vi risponde con la propria curva (quella morbida di un negativo, quella più ripida di una diapositiva, la linea retta di un sensore che si ferma al bianco). Così una posa notturna esce con un cielo nero e ciò che vi brillava in risalto. Indicata per un apparecchio che regola da sé l'esposizione (un telefono), è quell'apparecchio regolato a mano, come nella sua modalità manuale</td></tr>
      <tr><td><code>film</code></td><td>La pellicola della ripresa, quando è nota, con il suo identificativo nel catalogo: <code>"kodachrome-64"</code>. Dà la sensibilità, salvo che <code>iso</code> ne indichi un'altra, e la risposta alla luce, bianco e nero compreso. Se manca, nessuno lo dice.</td></tr>
      <tr><td><code>metering</code></td><td>Come un apparecchio che regola da sé l'esposizione ha letto la luce, quando lo si sa: <code>"average"</code>, la media di tutta l'immagine, come le videocamere e i telefoni vecchi, che brucia in bianco una luce viva in un'immagine scura; oppure <code>"highlights"</code>, come i telefoni recenti, trattenendosi perché una luce che occupa una parte notevole dell'immagine mantenga il suo colore (una lanterna a venti metri esce arancione, bianca solo vicino alla fiamma), il resto della notte più scuro. Assente: quella dell'apparecchio (un telefono protegge le sue alte luci)</td></tr>
      <tr><td><code>sway</code></td><td>Quanto il corpo che tiene lo strumento muove la vista quando non cammina: <code>1</code> per una persona in piedi o seduta, <code>0</code> per una fotocamera su treppiede, qualsiasi valore intermedio o superiore per meno o per più. Se manca, <code>1</code> — tranne per un testimone che il resoconto dice paralizzato (tag <code>paralysis</code>), per cui è <code>0</code>, e per un'esposizione più lunga di mezzo secondo, che nessuna mano tiene ferma: quello è un treppiede, e anche <code>0</code></td></tr>
      <tr><td><code>vehicle</code></td><td>Il veicolo in cui si trovava il testimone, quando lo scenario non lo disegna: <code>{ kind, windowsOpen, noise }</code>, dove <code>kind</code> è o un veicolo stradale (<code>car</code>, <code>van</code>, <code>truck</code>, <code>motorcycle</code>, <code>generic</code>) o un aeromobile, per la sua classe come si chiamano gli aerei del cielo (<code>business-jet</code>, <code>airliner-narrow</code>, <code>helicopter-light</code>…): un solo campo per entrambi, non avendo i due vocabolari alcuna parola in comune. Sentito dall'interno: il suo motore segue il tragitto del testimone stesso — la marcia dalla velocità, i giri dalla marcia, lo sforzo dall'accelerare o dal rallentare — con il rotolamento e il vento, attutiti da un abitacolo chiuso, lasciati entrare da finestrini aperti. Un aeromobile non ha né marce né cilindri: ciò che se ne sente è il rombo continuo della sua cabina, al livello che vi misura un passeggero per quella classe di macchina. <code>noise</code> è il suo livello sonoro rispetto a uno ordinario del suo tipo (1 per impostazione predefinita). Ciò su cui viaggia il testimone si frappone inoltre fra lui e tutto ciò che sta fuori, e toglie più agli acuti che ai gravi: un aereo a cento metri non è che un rombo attraverso una fusoliera, e sotto il rombo della cabina non si sente più affatto; la pioggia e il vento entrano attutiti allo stesso modo. <code>windowsOpen</code> lascia rientrare quasi tutto. È anche ciò che tiene attivo il pulsante del suono del lettore quando il file non ha <code>soundTrack</code>: il pulsante risponde di tutto ciò che la scena riproduce — questo motore, un <code>engine</code> dello scenario, un aeromobile dello scenario in volo, un corpo di una lettura che si sente, la pioggia e il vento — e non solo della traccia. Le sue luci: <code>headlights</code> è una regolazione come per un veicolo dello scenario (<code>off</code>, <code>position</code>, <code>dipped</code>, <code>main</code>, <code>fog</code>) o <code>auto</code>, predefinito: gli anabbaglianti dal crepuscolo e niente di giorno, come fa un conducente. <code>headlightKeyframes</code> è <code>[{ t, mode }]</code> per un cambiamento durante la registrazione. Il fascio illumina la strada davanti al testimone, nella direzione in cui va il veicolo.</td></tr>
      <tr><td><code>decor</code></td><td>Scenario a <code>eastM</code>/<code>northM</code> reali dal testimone: edifici (con <code>floors</code>, <code>windows</code>), alberi, arbusti, lampioni, veicoli, ponti, linee aeree, altri testimoni, aeromobili — facoltativamente con una <code>track</code> e delle <code>lights</code> il cui <code>pattern</code> porta una cadenza di lampeggio reale. Vedi sotto</td></tr>
    </table>
    </div>
    <p>Un <strong>elemento dello scenario</strong> si esprime in metri, come tutto ciò che non è il fenomeno:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>eastM</code>, <code>northM</code>, <code>headingDeg</code></td><td>Dove si trova rispetto al testimone, e verso dove è rivolta la sua parte anteriore, in senso orario dal nord vero</td></tr>
      <tr><td><code>sizeM</code></td><td><code>{ widthM, lengthM, heightM }</code> lungo i suoi assi, la lunghezza essendo la direzione verso cui è rivolto. Ogni asse è facoltativo: uno che nessuno ha misurato mantiene la proporzione propria della forma integrata</td></tr>
      <tr><td><code>model</code></td><td>Un vero modello 3D al posto della forma integrata: una voce del catalogo tramite <code>id</code>, o un file glTF/GLB a <code>url</code> (che prevale, deve essere leggibile da qualsiasi origine, e allora richiede il suo <code>credit</code>; uno relativo si legge dal file che lo indica). Non decide mai la dimensione: viene scalato, mantenendo le proporzioni, sul primo asse misurato fra lunghezza, altezza e larghezza, o sulla dimensione reale che gli dà il catalogo. Visto dall'interno, e ogni volta che il modello non si può ottenere, viene disegnata invece la forma integrata. <code>headingOffsetDeg</code> ruota il modello caricato attorno al suo asse verticale perché il muso punti dove la scena se lo aspetta (0 guarda a nord con una prua di 0); una voce del catalogo porta la sua. <code>credit</code> è <code>{ title, author, license, sourceUrl }</code>: <code>license</code> come la enuncia il suo autore (<code>"CC BY 4.0"</code>) e <code>sourceUrl</code> da dove viene, perché l'affermazione sia verificabile.</td></tr>
      <tr><td><code>bridge</code></td><td>Per un <code>"bridge"</code>: come è costruito. <code>sizeM.lengthM</code> è tutta la sua lunghezza lungo la strada, rilevati compresi, <code>widthM</code> la larghezza dell'impalcato e <code>heightM</code> l'altezza della carreggiata sull'impalcato sopra il suolo; <code>spanM</code> è la luce libera sotto l'impalcato, con la strada che corre su un rilevato di terra digradante fino al suolo su ciascun lato; <code>deckThicknessM</code> lo spessore della soletta (1,2 per impostazione predefinita); <code>railing</code> <code>{ heightM, postSpacingM, rails }</code> il parapetto lungo entrambi i bordi, montanti e correnti le cui aperture sono rettangoli (1,05 m, 1,5 m e 2 correnti per impostazione predefinita). Disegnato con quelle misure, mai stirato</td></tr>
      <tr><td><code>wire</code></td><td>Per un <code>"wire"</code> (una linea elettrica o telefonica): <code>sizeM.lengthM</code> è la campata fra i suoi pali, lungo il suo <code>headingDeg</code>, e <code>heightM</code> l'altezza del filo più basso; <code>strands</code> <code>[{ heightM, acrossM }]</code> ne appende diversi (quelli sovrapposti condividono un <code>acrossM</code>, quelli di una traversa differiscono); <code>poles</code> è <code>both</code> (predefinito), <code>start</code> o <code>end</code> (l'estremità da cui la sua direzione si allontana o verso cui punta: l'altra è ancorata a un edificio) o <code>none</code>; <code>diameterM</code> (8 mm per impostazione predefinita) e <code>poleHeightM</code> (mezzo metro sopra il filo più alto). Dritta, senza catenaria, e disegnata a quelle misure, mai allungata</td></tr>
      <tr><td><code>track</code></td><td><code>[{ t, eastM, northM, altitudeM, headingDeg }]</code> quando si muove, <code>altitudeM</code> sopra il suolo sotto di esso (l'occhio è a <code>elevationM</code> + 1,6 m: un corpo all'altezza dell'occhio ha quell'<code>altitudeM</code>). La posizione è interpolata fra i fotogrammi chiave; la direzione è mantenuta dall'uno al successivo</td></tr>
      <tr><td><code>lights</code></td><td>Le sue luci: <code>id</code>, <code>offsetM</code> <code>{ x, y, z }</code> dal suo centro (destra, alto, davanti), <code>color</code>, <code>intensity</code> (1 è una normale luce di navigazione) e un <code>pattern</code>: <code>{ "kind": "steady" }</code>, oppure <code>{ "kind": "flash", perMinute, dutyCycle, phase }</code>, la cadenza come la stabiliscono i regolamenti, la frazione accesa di ogni ciclo (circa 0,5 per un lampeggiatore a filamento, 0,01 per uno stroboscopio) e uno sfasamento da 0 a 1 fra le luci. L'editor le compila da preimpostazioni: “Aereo di linea”, “Elicottero”, “Auto, fari accesi”, “Auto, luci di emergenza”, “Lampeggianti di veicolo di soccorso”, “Lampione”. Come si accende o si spegne durante la registrazione, da ogni istante in poi, <code>keyframes</code> <code>[{ t, intensity, pattern }]</code>: ciò che danno gli eventi <code>light</code> e <code>blink</code> che la riguardano</td></tr>
      <tr><td><code>groups</code></td><td>Le sue luci prese insieme, perché un solo evento le riguardi tutte: <code>{ id, title, members }</code>, i suoi membri sue luci o altri suoi gruppi. Nominato in un evento come una luce, <code>id/gruppo</code>: i due flash di un aereo, <code>f-hobs/strobes</code>. Facoltativo</td></tr>
      <tr><td><code>engine</code></td><td>Un veicolo che si sente in moto: <code>{ kind, noise }</code>, come <code>vehicle</code> sopra. Il suo motore segue la sua <code>track</code>, sentito da dove si trova il testimone, più debole e più sordo con la distanza</td></tr>
      <tr><td><code>aircraftSound</code></td><td>Un aeromobile (kind <code>aircraft</code>) che si sente mentre vola, cosa che fa quando la sua <code>track</code> lascia il suolo: il tipo di rumore che fa, una classe di aeromobile (<code>airliner-narrow</code> per impostazione predefinita, <code>airliner-wide</code>, <code>airliner-supersonic</code>, <code>regional-jet</code>, <code>helicopter-light</code>, <code>light-piston</code>…) o <code>silent</code> per uno che non ne fa alcuno. Ciò che dice il suo modello vale quando questo manca (i sostituti di un fenomeno sono silenziosi). Si sente come gli aerei di un registro di traffico aereo: più debole e più cupo con la distanza, <em>in ritardo</em> per il tempo che il suono impiega ad arrivare (circa tre secondi per chilometro), così da essere sentito dov'era, più acuto mentre si avvicina e più grave mentre si allontana, e mascherato dal rumore del luogo; un aereo a reazione più forte al decollo che in avvicinamento, e dietro che davanti, con l'eco del suolo sotto di esso. Un aeromobile dentro il quale si trova l'osservatore (un pilota nella sua cabina di pilotaggio) è quello che monta: non lo si sente passare, ma come la sua cabina, e ciò che è fuori attraverso il suo guscio, come con <code>vehicle</code></td></tr>
      <tr><td><code>occludesSourceIds</code></td><td>I fenomeni davanti ai quali il testimone ha detto che questo elemento si trovava: vedi le <a href="/docs/format/#four-rules-that-decide-what-a-file-means">regole della pagina del formato</a></td></tr>
      <tr><td><code>facade</code></td><td>Solo il genere <code>building</code>: <code>{ color?, plain? }</code>. <code>color</code> è il muro, <code>"#rrggbb"</code>; salvo che <code>plain</code> sia <code>true</code>, si disegnano finestre a ogni piano e una porta al piano terra della faccia frontale. Disegnata alla <code>sizeM</code> enunciata (devono esserlo tutti e tre i lati), mai stirata, e non per un edificio con un testimone dentro. L'editor prende il colore dal materiale che la carta enuncia per i muri (pietra, mattone, calcestruzzo, blocco, legno), o un intonaco dove non ne enuncia. Assente è la semplice scatola.</td></tr>
      <tr><td><code>roof</code></td><td>Solo il genere <code>building</code>: <code>{ shape, riseM, color?, ridge? }</code>. <code>shape</code> è <code>"flat"</code> (la scatola), <code>"gable"</code> (due falde fino a un colmo lungo il lato maggiore, o la profondità con <code>ridge: "depth"</code>) o <code>"hip"</code> (quattro falde); <code>riseM</code> è quanto il colmo sta sopra la gronda, quindi i muri sono <code>sizeM.heightM</code> meno quello; <code>color</code> è il tetto visto dall'alto, <code>"#rrggbb"</code>. L'editor li legge dal laser e dalla foto aerea del rilievo. Assente è un tetto piano del colore dei muri.</td></tr>
      <tr><td><code>origin</code></td><td>Il rilievo da cui è stato ricavato questo oggetto, dall'id del suo fornitore (<code>"ign-lidar-topo"</code>), quando l'editor lo ha preso dal rilievo del luogo e l'autore non lo ha collocato a mano: un albero, un edificio, un ponte o una campata di linea. Scegliere un altro rilievo, o nessuno, o un altro luogo, sostituisce o toglie ciò che porta un <code>origin</code>, e mai ciò che non lo porta</td></tr>
      <tr><td><code>surveyedOn</code></td><td>Il giorno (<code>AAAA-MM-GG</code>) del rilievo più recente da cui è tratto questo oggetto, quando viene da uno (vedi <code>origin</code>): l'editor avvisa quando è successivo all'osservazione.</td></tr>
      <tr><td><code>lit</code>, <code>litKeyframes</code></td><td>Se la lampada di un lampione o i fari di un veicolo sono accesi. <code>litKeyframes</code> è <code>[{ t, lit }]</code>, ordinato per <code>t</code>, per una luce che si accende o si spegne durante la registrazione; senza, <code>lit</code> vale per tutta la durata. Ignorato per un edificio, un albero o un testimone</td></tr>
      <tr><td><code>headlights</code>, <code>headlightKeyframes</code></td><td>Come sono regolate le luci di un veicolo, perché non tutti le accendono, né come si dovrebbe: <code>off</code>, <code>position</code> (le luci di posizione, che mostrano il veicolo e non illuminano nulla), <code>dipped</code> (gli anabbaglianti), <code>main</code> (gli abbaglianti: lontani, stretti, accecanti) o <code>fog</code> (i fendinebbia: bassi e larghi). Un fascio illumina la strada, i bordi, gli alberi e i muri davanti al veicolo, comunque sia disegnato. <code>headlightKeyframes</code> è <code>[{ t, mode }]</code>, ordinato per <code>t</code>, per una regolazione che cambia durante la registrazione. Senza nessuno dei due, lo dice <code>lit</code>: acceso sono gli anabbaglianti. Ignorato per tutto ciò che non è un veicolo. Solo quattro veicoli (quello del testimone, poi i più vicini dello scenario) hanno un vero fascio. I fari del testimone proiettano ombre (una scarpata, un palo o una pila di ponte trattiene la luce di ciò che sta dietro), e il fascio si vede nell'aria in proporzione a ciò che l'aria ne diffonde: una traccia lieve con aria limpida, un cono di luce nella nebbia</td></tr>
      <tr><td><code>observerSide</code>, <code>observerFacing</code>, <code>observerKeyframes</code>, <code>occupiedFloor</code></td><td>Il testimone dentro l'oggetto, per un <code>building</code> o un veicolo (un solo oggetto alla volta lo contiene). <code>observerSide</code> dice dov'è: <code>front</code>, <code>behind</code>, <code>left</code>, <code>right</code>, <code>front-left</code>, <code>front-right</code>, <code>behind-left</code> o <code>behind-right</code>, l'occupante di un veicolo trovandosi a una delle sue quattro portiere. <code>observerFacing</code> è il finestrino da cui guarda quando non è quello del suo posto: un conducente siede in <code>front-left</code> e guarda dal parabrezza, <code>front</code>. <code>observerKeyframes</code>, <code>[{ t, side, facing }]</code>, dice dove siede nel tempo, ciascuno mantenuto fino al successivo, e un fotogramma senza <code>side</code> significa fuori da lì in poi, come un conducente che scende. <code>occupiedFloor</code> è il piano di un edificio su cui si trova, da 0 (piano terra) a <code>floors</code></td></tr>
      <tr><td><code>modelParameters</code></td><td>Le impostazioni del modello con cui l'oggetto è disegnato, per la chiave con cui la voce del catalogo pubblica ciascuna: <code>{ "costumeColor": "#5a6b3a" }</code> per i vestiti di una persona, <code>foliageColor</code> per un albero, <code>hullColor</code> per un velivolo, <code>gearUp</code> per un aereo di linea in volo. Un modello porta le sue (l'editor disegna un campo per ciascuna); un oggetto disegnato come forma integrata non ne ha, è dipinto da <code>color</code></td></tr>
      <tr><td><code>sightingUrl</code></td><td>Per un <code>observer</code>: l'indirizzo della registrazione propria di quell'testimone, quando è noto, così che il menu della scena possa offrire di vedere la sua testimonianza</td></tr>
    </table>
    </div>

    <h2>Eventi del cielo</h2>
    <p>Ciò che è accaduto nel cielo durante la registrazione, come fatti: un tiro laser, un lancio di razzo, un rientro. Ciascuno è avvenuto che qualcuno l'abbia visto o no: non è quindi la lettura del resoconto, né lo scenario, che dura più dell'osservazione (una casa, un albero). Sono dichiarati sotto <code>skyEvents</code>, al primo livello della registrazione; una registrazione che li metteva nella sua <code>interpretation</code>, come facevano le versioni precedenti, viene ancora letta. Accanto a essi la scena mette ciò che le fonti sanno di quella data e di quel luogo: le meteore degli sciami e il fondo sporadico, i bolidi registrati da una rete di telecamere, i rientri noti, i satelliti tracciati, gli aerei di un registro del traffico aereo. Ciò che dice la registrazione vi si aggiunge, senza mai sostituirli. <code>skySources: false</code>, al primo livello della registrazione, li lascia fuori: un cielo inserito a mano, che contiene solo ciò che dice la registrazione (i suoi eventi, e i velivoli del suo ambiente).</p>
    <pre data-json=""><code>{
  "skyEvents": {
    "beams": [{
      "id": "meudon-paris",
      "path": [
        { "lat": 48.805055, "lng": 2.231171, "altitudeM": 172.5 },
        { "lat": 48.83632, "lng": 2.33702, "altitudeM": 88 }
      ],
      "wavelengthNm": 532,
      "powerW": 10
    }]
  }
}</code></pre>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>auroras</code></td><td>Le aurore della notte: un ovale di luce emessa dall'alta atmosfera intorno al polo magnetico, da 90 a 900 km di quota, che la scena percorre lungo ogni linea di vista. <code>kp</code> dice quanto era agitato il campo (da 0 a 9, o oltre 9 l'indice Hp del GFZ, senza tetto), e <code>activity</code> come è andato, <code>{ t, kp }</code> a istanti della registrazione uniti linearmente; 3 se nessuno dei due è indicato. Ne discendono il bordo dell'ovale verso l'equatore a mezzanotte magnetica (66,5° di latitudine di apice del campo reale a 0, circa due gradi più vicino all'equatore per passo), la sua larghezza, un bagliore verde diffuso, i suoi archi e la loro luminosità, e il rosso alto di una tempesta; <code>edgeLatDeg</code>, <code>arcs</code> (0 per il solo bagliore), <code>arcKR</code> (kilorayleigh di verde guardando attraverso l'altezza di un arco: 1 la luminosità della Via Lattea, 1000 illumina il suolo come la luna piena) e <code>redKR</code> li indicano ciascuno altrimenti. <code>fromT</code> e <code>untilT</code> dicono quando c'è, apparendo e scomparendo in un minuto. Richiede la data della registrazione, perché la posizione del Sole decide quella dell'ovale. Una registrazione che non ne indica nessuna riceve quella che l'indice archiviato dal GFZ implica (Kp dal 1932, Hp60 dal 1985), citato, a meno che <code>skySources</code> sia false.</td></tr>
      <tr><td><code>reentries</code></td><td>I rientri atmosferici avvenuti, un satellite o uno stadio di razzo che si disintegra in pezzi che bruciano. Non sono corpi: un rientro brucia tra 70 e 100 km di quota e si vede a centinaia di chilometri, quindi è collocato sulla Terra e visto attraverso la sua curvatura dal punto in cui stava il testimone. La sua <code>track</code> dà il punto di testa in istanti della registrazione, <code>{ t, lat, lng, altitudeKm }</code>, uniti da cerchi massimi; ciascuno dei suoi <code>fragments</code> segue lo stesso percorso <code>lagS</code> secondi dietro, si vede da <code>fromT</code> finché si spegne a <code>untilT</code>, brilla della sua <code>absoluteMagnitude</code> (a 100 km, come per un bolide) riportata alla distanza reale, nel suo <code>color</code>, con una scia degli ultimi <code>trainS</code> secondi del percorso (4 se manca: la scia di un rientro è lunga). Ogni pezzo si disgrega come fanno i pezzi che bruciano (<code>sheds</code>): uno sgretolarsi lento in frammenti deboli, ciascuno con la sua striscia, che restano indietro, si scostano e scendono in un ventaglio stretto, e una raffica di una trentina a ogni picco della sua <code>lightCurve</code>, un picco essendo una rottura (Zander &amp; Löhle, <em>CEAS Space Journal</em> 2025). Un elenco di fasi lo dichiara al suo posto, <code>{ fromT, untilT, perS, lifeS, magnitudeDrop, dropBack, spreadKmS, sinkKmS, trainS }</code>, e un elenco vuoto un pezzo che non perde nulla. Un picco più brillante della magnitudine −12 sotto i 50 km si sente come una detonazione, dopo il tempo che il suono impiega a percorrere la distanza (Čeljabinsk: due minuti e mezzo). La sua luce è propria: si vede che il Sole la raggiunga o no. <code>type</code> dice ciò che è entrato, e con esso la sua natura: <code>meteor</code> (meteora) o <code>fireball</code> (bolide), naturali, <code>satellite</code>, <code>rocket-stage</code> (stadio di razzo) o <code>capsule</code>, messi in orbita, o un tipo che aggiunge un modulo (il punto di estensione <code>reentryTypes</code>); sconosciuto se manca, ciò che spesso un resoconto lascia in dubbio. Non cambia nulla di ciò che è disegnato, che segue dal percorso e dai pezzi. <code>seen</code> dice dove l'ha visto il testimone, <code>{ fromAzimuthDeg, fromAltitudeDeg, toAzimuthDeg, toAltitudeDeg, durationS }</code>: l'editor ne deduce il percorso, alle quote del primo e dell'ultimo punto del percorso, e lo conserva come ciò che è stato detto. <code>object</code> nomina ciò che è ricaduto (<code>name</code>, <code>cosparId</code>, <code>norad</code>). Nulla è propagato da elementi orbitali, sbagliati di minuti nell'ultima orbita: il percorso è ciò che le fonti stabiliscono, con la sua provenienza</td></tr>
      <tr><td><code>launches</code></td><td>I lanci di razzo avvenuti, illuminato da un Sole tramontato per il suolo ma non per la scia, la «medusa spaziale». Collocati sulla Terra come un rientro: la loro <code>track</code> dà lo stadio in istanti della registrazione, <code>{ t, lat, lng, altitudeKm }</code> (può cominciare prima della registrazione), e <code>burnFromT</code> e <code>burnUntilT</code> i secondi in cui il motore ha bruciato. La scia è una fila di sbuffi lasciati lungo quel percorso, ciascuno che si allarga con l'età; ciò che si vede di ciascuno è la luce del Sole che diffonde verso il testimone. L'ombra della Terra (dove il Sole illumina o no all'altezza dello sbuffo, e quanta aria ha sfiorato la sua luce, che la arrossa o la rende blu), l'angolo di diffusione e l'espansione sono calcolati dal vero Sole alla vera data: nulla ne è dichiarato. Un <code>plume</code> facoltativo sostituisce i valori predefiniti: <code>exhaustKgPerS</code> (273, un Merlin Vacuum), <code>condensedShare</code> (0,065, l'unico numero che nessuno ha misurato), <code>particleRadiusUm</code>, <code>expansionKmPerS</code>, <code>initialRadiusKm</code>, <code>lifetimeS</code>, e per il collare (lo scarico appena rilasciato, largo e presto sparito, accanto alla scia stretta che resta) <code>collarShare</code> (0,85), <code>collarExpansionKmPerS</code> (2,5), <code>collarLifetimeS</code> (20). <code>vehicle</code> nomina ciò che ha volato e, in <code>engine</code>, il motore di cui è lo scarico: <code>thrustKN</code> e <code>specificImpulseS</code> (da cui si ricavano la portata dello scarico e la sua velocità, quindi la larghezza del collare) e <code>propellant</code> (<code>rp1-lox</code>, <code>methane-lox</code>, <code>hydrogen-lox</code>, <code>hypergolic</code> o <code>solid</code>, che dice quanta parte diventa particelle e di che dimensione). Ciò che dice <code>plume</code> prevale su ciò che dice il motore. La scia ha bisogno della data della registrazione: senza non c'è Sole che la illumini. <code>vehicle.mission</code> nomina la missione che compiva (<code>"Starlink Group 10-49"</code>). Ogni sbuffo vola da solo una volta rilasciato, alla velocità dello stadio più quella con cui è stato lanciato, attratto dalla Terra e frenato dall'aria solo dove è abbastanza densa da scorrergli attorno (sotto i 200-300 km): la scia è la stessa cosa nello spazio vista da ogni lato, una scia vista di fronte è un disco, una spirale vista di taglio una linea. Il suo colore è quello della dimensione delle sue particelle: il ghiaccio grosso diffonde bianco, quello più fine della lunghezza d'onda blu. <code>jets</code> elenca cos'altro rilascia lo stadio, ciascuno <code>{ kind, fromT, untilT, angleDeg, azimuthDeg, spinPeriodS, speedKmPerS, massKgPerS, condensedShare, particleRadiusUm, expansionKmPerS, initialRadiusKm, lifetimeS }</code>: <code>kind</code> <code>burn</code> (un'altra accensione del motore, con i valori della scia; una frenata di deorbitazione è <code>angleDeg</code> 180, lo scarico che parte davanti) o <code>vent</code> (propellenti scaricati dai serbatoi, più lenti, fini e freddi: 0,7 km/s, 20 kg/s, metà che gela, per default); <code>angleDeg</code> da dietro il moto (0) fino al lato (90); <code>azimuthDeg</code> il lato da cui esce attorno al moto (0 opposto alla Terra); <code>spinPeriodS</code> il giro dello stadio attorno al suo moto, che fa girare il getto con lui e disegnare una spirale ai propellenti scaricati. Quando ci sono getti, l'accensione dell'ascesa è disegnata solo se è dato <code>burnFromT</code> o <code>burnUntilT</code>.</td></tr>
      <tr><td><code>beams</code></td><td>I fasci di luce inviati nell'aria dal suolo, un tiro laser o un proiettore. Ciascuno ha un <code>path</code> di almeno due punti <code>{ lat, lng, altitudeM }</code> (altitudini sul mare): dove lascia l'emettitore, dove uno specchio lo devia se c'è, e dove finisce. Tra due punti è una retta nello spazio, non lungo il suolo, che si abbassa sotto di essa. <code>wavelengthNm</code> è il suo colore (532 per un laser verde), <code>powerW</code> la sua potenza ottica media, <code>divergenceMrad</code> quanto in fretta si allarga (0,1 se assente) e <code>apertureM</code> la sua larghezza alla partenza (0,01 m se assente); <code>fromT</code> e <code>untilT</code> dicono quando è acceso. Nulla della sua luminosità è dichiarato: ciò che si vede di ogni metro è ciò che l'aria in quel punto (molecole e foschia, alla sua lunghezza d'onda) diffonde verso l'occhio della potenza che gli resta, secondo l'angolo di cui la luce deve girare; è quindi molto più vivo visto risalendolo che guardandolo allontanarsi. È nascosto da ciò che gli sta davanti e si ferma dove incontra il suolo.</td></tr>
    </table>
    </div>

    <h2>Il meteo, e le sue nuvole</h2>
    <p>Un fotogramma chiave <code>weather</code> esprime le condizioni del cielo in un momento dell'orologio
      della registrazione; fra due fotogrammi chiave ogni numero viene interpolato, mentre il tipo di precipitazione e il
      temporale vengono mantenuti. Contiene:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>cloudLayers</code></td><td>Le nuvole, come elenco di strati — vedi sotto. <strong>Se manca</strong>, le descrivono i campi più vecchi delle righe vicine, adattati in uno strato d'acqua e un velo di cirri; <strong>un elenco vuoto</strong> significa un cielo sereno che qualcuno ha guardato</td></tr>
      <tr><td><code>cloudCover</code>, <code>lowerCloudCover</code>, <code>highCloudCover</code></td><td>Frazioni di cielo (0–1): il totale, solo gli strati d'acqua, e solo il velo ghiacciato. Scritte dalle registrazioni fatte prima che esistessero gli strati, e ancora tenute aggiornate dall'editor come riassunto di questi</td></tr>
      <tr><td><code>cloudBaseM</code>, <code>cloudDarkness</code></td><td>L'unica base della stessa epoca, in metri sopra il suolo di riferimento, e un'unica tonalità (0 bianco, 1 molto scuro)</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>0–1, con quanta regolarità cadevano i cristalli di ghiaccio — ciò che trasforma un semplice anello in pareli, archi e una colonna. Nessun dato lo misura; uno strato di cirri porta il proprio</td></tr>
      <tr><td><code>rareIceCrystals</code></td><td>0–1, la quota dei cristalli di un velo di cirri che sono di tipi rari: colonne con estremità piramidali (gli aloni a raggio dispari, a 9°, 20° e 35°) e lastrine libere di ruotare attorno a un asse orizzontale (gli archi di Lowitz). Assente significa 5%, un velo ordinario. Come l'allineamento, nessun dato li conta: è dichiarato. La simulazione che ne deriva è stata verificata coerente con <a href="https://atoptics.co.uk">Atmospheric Optics</a></td></tr>
      <tr><td><code>relativeHumidity</code></td><td>0–1, vicino al suolo. Decide quanto è lattiginoso il cielo sereno: la foschia si gonfia d'acqua man mano che l'aria si avvicina alla saturazione. Un dato consultato la contiene (dalla temperatura e dal punto di rugiada di ERA5); se manca, una foschia tipica</td></tr>
      <tr><td><code>visibilityKm</code></td><td>La visibilità meteorologica vicino al suolo, in chilometri, come la dà un bollettino. È la foschia stessa: dichiarata, decide quanta ce n'è, per la lontananza come per il cielo, e l'umidità non viene più letta per questo Oltre i 30 km, è anche la distanza fino a cui è disegnato il rilievo (150 km al massimo), che scende con la curvatura della Terra: una montagna che un'aria limpida mostra lontano c'è.</td></tr>
      <tr><td><code>precipitationType</code>, <code>precipitationIntensity</code></td><td>none/rain/snow/hail, e 0–1. Indicata a un fotogramma chiave, riprodotta come cade: un rovescio inizia al fotogramma chiave che lo avvia con le sue prime gocce, e non raggiunge l'intensità indicata più in fretta di una pioggia reale (da niente al massimo in venti secondi); smette allo stesso modo. Un cambiamento che i fotogrammi chiave distribuiscono su un tempo più lungo viene seguito esattamente. <code>precipitationAmount</code> (0–1, assente significa tutta) dice quanta parte di quella precipitazione sta già cadendo.</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>Il vento generale: la direzione VERSO cui soffia, in senso orario dal nord, e metri al secondo. È ciò che trasporta le nuvole — dall'istante zero, così che cercare e riprodurre di nuovo diano lo stesso cielo</td></tr>
      <tr><td><code>storm</code></td><td>Fulmini e tuoni, con il giusto ritardo</td></tr>
    </table>
    </div>
    <p>Ogni <strong>strato</strong> di <code>cloudLayers</code> è una coltre di nuvole a un'altezza
      reale, e resta sé stesso da un fotogramma chiave al successivo:</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>id</code></td><td>Stabile fra i fotogrammi chiave — gli strati vengono abbinati tramite esso, mai per posizione nell'elenco. Uno strato presente in un fotogramma chiave e assente dal successivo svanisce; riordinarli non cambia nulla</td></tr>
      <tr><td><code>type</code></td><td><code>cumulus</code>, <code>stratus</code>, <code>stratocumulus</code>, <code>cirrus</code> o <code>unknown</code>. Decide la forma delle sommità e quanto è sottile il velo; un cirro è anche quello che rifrange gli aloni. Cambia al fotogramma chiave, non viene interpolato</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>Metri. La base è sopra il suolo di RIFERIMENTO della registrazione, non sopra un testimone che sale; un testimone sopra la base è dentro la coltre o al di sopra, e il cielo viene disegnato di conseguenza</td></tr>
      <tr><td><code>coverage</code></td><td>0–1, e significa ciò che dice: la frazione di cielo che questo strato copre, qualunque sia la dimensione delle sue nuvole</td></tr>
      <tr><td><code>sizeM</code></td><td>La larghezza caratteristica di una nuvola, in metri. Indipendente dalla copertura: la stessa frazione di cielo può essere molte nuvole piccole o poche grandi</td></tr>
      <tr><td><code>density</code></td><td>0–2, quanto è opaca la materia della nuvola; 0 è trasparente. Anch'essa indipendente dalla copertura</td></tr>
      <tr><td><code>darkness</code></td><td>Da 0 bianco a 1 molto scuro. Se manca, il <code>cloudDarkness</code> del fotogramma chiave</td></tr>
      <tr><td><code>seed</code></td><td>Quale motivo, fra gli infiniti che gli stessi numeri possono disegnare. Se manca, uno ricavato dall'id, ed è per questo che l'id non deve cambiare</td></tr>
      <tr><td><code>windDirectionDeg</code>, <code>windSpeed</code></td><td>Il vento proprio di questo strato, quando differisce da quello generale — di solito è il caso dello strato alto. Se manca, il vento generale</td></tr>
      <tr><td><code>iceCrystalAlignment</code></td><td>Solo per un cirro</td></tr>
      <tr><td><code>instances</code></td><td>Nuvole singole all'interno di questo strato — vedi sotto</td></tr>
    </table>
    </div>
    <p>Una <strong>nuvola singola</strong> in <code>instances</code> è una nuvola del suo strato che il
      file colloca con esattezza, perché il resoconto lo ha fatto: quella dietro cui è passato il fenomeno, quella che
      era lì e da nessun'altra parte. Viene disegnata come una delle altre del suo strato — la stessa texture, la stessa
      soglia —, distinta dalle vicine soltanto da dove si trova e da quanto è grande,
      ed è presente anche quando la <code>coverage</code> dello strato è nulla. Segue il vento dello strato
      come le altre, e nasconde un fenomeno davanti al quale passa.</p>
    <div class="table-scroll">
    <table>
      <tr><th>Campo</th><th>Significato</th></tr>
      <tr><td><code>id</code></td><td>Stabile fra i fotogrammi chiave, stessa regola di uno strato</td></tr>
      <tr><td><code>eastM</code>, <code>northM</code></td><td>Dove si trovava il suo centro all'istante zero, in metri dal punto di partenza del testimone. Il vento la trasporta da lì</td></tr>
      <tr><td><code>baseM</code>, <code>thicknessM</code></td><td>La sua base e la sua altezza, in metri — una nuvola può stare più in basso o elevarsi più della sua coltre</td></tr>
      <tr><td><code>widthM</code>, <code>depthM</code>, <code>rotationDeg</code></td><td>La sua impronta, in metri, e la direzione verso cui quell'impronta è ruotata</td></tr>
      <tr><td><code>density</code>, <code>darkness</code></td><td>Le proprie; se manca l'oscurità, quella dello strato</td></tr>
    </table>
    </div>
    <pre data-json="weatherTrack.keyframes"><code>{
  "weather": {
    "cloudLayers": [
      {
        "id": "low", "type": "cumulus",
        "baseM": 1500, "thicknessM": 800,
        "coverage": 0.55, "sizeM": 1400, "density": 1, "darkness": 0.15,
        "instances": [
          { "id": "the-one", "eastM": 0, "northM": 4200,
            "baseM": 1500, "thicknessM": 800,
            "widthM": 1900, "depthM": 1300, "rotationDeg": 12, "density": 1 }
        ]
      },
      { "id": "high", "type": "cirrus", "baseM": 8000, "thicknessM": 400,
        "coverage": 0.2, "sizeM": 2200, "density": 0.35, "iceCrystalAlignment": 0.65 }
    ],
    "precipitationType": "none", "precipitationIntensity": 0,
    "windDirectionDeg": 90, "windSpeed": 5, "storm": false
  }
}</code></pre>
    <p>Una registrazione il cui meteo è stato <strong>consultato</strong> (ha un <code>weatherSource</code>)
      contiene la risposta del dato, non un link a esso: ERA5 fornisce le fasce bassa, media e alta come tre
      strati chiamati <code>record-low</code>, <code>record-mid</code> e <code>record-high</code>, la
      base bassa stimata dallo scarto fra temperatura e punto di rugiada, le altre due a 3 500 m
      e 8 000 m. Il loro tipo è <code>unknown</code> (cirro per quello alto), la loro dimensione e la loro
      densità sono ipotesi di disegno: una rianalisi sa quanta parte di ogni fascia era coperta, non che aspetto
      avessero le nuvole. Richiedi il dato dall'editor e gli strati vengono riscritti; modifica
      uno strato a mano e la registrazione diventa dell'autore, con la fonte rimossa.</p>
`
  }
}
